INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('e5922eaa-65ee-5cce-ada9-6e6e5f81d740', '93e280cc-fa4b-5de5-a17f-2921cff9225b', '4a3b43e8-3537-5c14-ac18-3e196083e956', 1, 17, 'ዳዊትም ስለ ሳኦልና ስለ ልጁ ዮናታን ይህን የኀዘን ቅኔ ተቀኘ፤'),
  ('d4a9d0a0-56d3-5d2a-a1b2-fe8b0a43d9ec', '93e280cc-fa4b-5de5-a17f-2921cff9225b', '4a3b43e8-3537-5c14-ac18-3e196083e956', 2, 18, 'የይሁዳንም ልጆች ያስተምሩ ዘንድ አዘዘ። እነሆ ይህ በጻድቃን መጽሐፍ ተጽፎአል።'),
  ('88fe023f-f0fc-5969-ad53-3e6c89286229', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', 'af8f4aee-b77a-594b-aca0-1ff312bf6131', 1, 1, 'ከዚያም በኋላ ዳዊት፥ “ከይሁዳ ከተሞች ወደ አንዲቱ ልውጣን?” ብሎ እግዚአብሔርን ጠየቀ። እግዚአብሔርም፥ “ውጣ” አለው። ዳዊትም፥ “ወዴት ልውጣ?” አለ። እርሱም፥ “ወደ ኬብሮን ውጣ” አለው።'),
  ('01af530b-b93b-5210-a88e-4e10e7275eda', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', 'af8f4aee-b77a-594b-aca0-1ff312bf6131', 2, 2, 'ዳዊትም ከሁለቱ ሚስቶቹ ከኢይዝራኤላዊቱ ከአኪናሆምና የቀርሜሎሳዊው የናባል ሚስት ከነበረችው ከአቤግያ ጋር ወደዚያ ወደ ኬብሮን ወጣ።'),
  ('6153f0f1-8628-54f8-a966-a7b410f01315', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', 'af8f4aee-b77a-594b-aca0-1ff312bf6131', 3, 3, 'ከእርሱም ጋር የነበሩት ሰዎች ሁሉ ከቤተ ሰባቸው ጋር ወጡ፤ በኬብሮንም ከተሞች ተቀመጡ።'),
  ('b7e3a829-a910-51ac-af59-29017d28837f', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', 'af8f4aee-b77a-594b-aca0-1ff312bf6131', 4, 4, 'የይሁዳም ሰዎች መጥተው በይሁዳ ቤት ይነግሥ ዘንድ ዳዊትን በዚያ ቀቡት። ሳኦልን የቀበሩት የኢያቢስ ገለዓድ ሰዎች ናቸው ብለው ለዳዊት ነገሩት።'),
  ('2501bf9a-cee1-583a-a0f8-c73940233414', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', 'af8f4aee-b77a-594b-aca0-1ff312bf6131', 5, 5, 'ዳዊትም ወደ ኢያቢስ ገለዓድ ገዦች መልእክተኞችን ላከ፤ ዳዊትም እንዲህ አላቸው፥ “እናንተ እግዚአብሔር ለቀባው ለጌታችሁ ለሳኦል ይህን ቸርነት አድርጋችኋልና፥ እርሱንና ልጁን ዮናታንንም ቀብራችኋቸዋልና በእግዚአብሔር የተባረካችሁ ሁኑ።'),
  ('14d061d9-4edc-5996-a261-0ca8f713a174', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', 'af8f4aee-b77a-594b-aca0-1ff312bf6131', 6, 6, 'አሁንም እግዚአብሔር ምሕረትንና ጽድቅን ያድርግላችሁ፤ ይህንም ነገር አድርጋችኋልና እኔ ደግሞ ይህን በጎነት እመልስላችኋለሁ።'),
  ('65d4cc8d-dd4f-5722-ac0f-9b5e4e357e5c', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', 'af8f4aee-b77a-594b-aca0-1ff312bf6131', 7, 7, 'አሁንም ጌታችሁ ሳኦል ሞቶአልና እጃችሁ ትጽና፤ እናንተም በርቱ፤ የይሁዳም ቤት በእነርሱ ላይ ንጉሥ እሆን ዘንድ ቀብተውኛል።”'),
  ('9c0e7028-6efb-55c2-ad30-9db10392bfb0', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '0b7bc2a3-8588-5ff3-aef7-5ae5be0bd817', 1, 8, 'የሳኦልም ጭፍራ አለቃ የኔር ልጅ አበኔር የሳኦልን ልጅ ኢያቡስቴን ወስዶ ከሰፈር ወደ መሃናይም አወጣው፤'),
  ('bba1246b-2fd5-5d1d-a20f-f2acee63415d', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '0b7bc2a3-8588-5ff3-aef7-5ae5be0bd817', 2, 9, 'በገለዓድና በታሲሪ፥ በኢይዝራኤልም፥ በኤፍሬምም፥ በብንያምም፥ በእስራኤልም ሁሉ ላይ አነገሠው።'),
  ('60ab5350-2b27-51cc-adc7-0ca042afb103', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '0b7bc2a3-8588-5ff3-aef7-5ae5be0bd817', 3, 10, 'የሳኦል ልጅ ኢያቡስቴም በእስራኤል ላይ በነገሠ ጊዜ አርባ ዓመት ሆኖት ነበረ፤ ዳዊትን ከተከተሉት ከይሁዳ ወገኖች ብቻ በቀር ሁለት ዓመት ነገሠ።'),
  ('1656f96b-95cf-57e0-a9b1-f590e66830ca', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '0b7bc2a3-8588-5ff3-aef7-5ae5be0bd817', 4, 11, 'ዳዊትም በይሁዳ ቤት በኬብሮን የነገሠበት ዘመን ሰባት ዓመት ከስድስት ወር ነበረ።'),
  ('3a6cf6d5-f63e-5bd3-a3de-d0ec76adc1dc', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 1, 12, 'የኔር ልጅ አበኔርና የሳኦል ልጅ የኢያቡስቴ ብላቴኖች ከመሃናይም ወደ ገባዖን ወጡ።'),
  ('df183a40-0c14-5ddb-a58e-c5174946073e', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 2, 13, 'የሶርህያ ልጅ ኢዮአብና የዳዊት ብላቴኖች ከኬብሮን ወጥተው በገባዖን ውኃ መቆሚያ አጠገብ ተገናኙአቸው፤ በውኃውም መቆሚያ በአንዱ ወገን እነዚህ፥ በሌላውም ወገን እነዚያ ሆነው ተቀመጡ።'),
  ('eca1da42-eeee-5d91-a15e-c0f19db519d7', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 3, 14, 'አበኔርም ኢዮአብን፥ “ጐልማሶቻችን ይነሡ፤ በፊታችንም ይቈራቈሱ” አለው፤ ኢዮአብም፥ “ይነሡ” አለ።'),
  ('074933ea-f824-50d3-ac96-a8a866e7790a', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 4, 15, 'ለሳኦል ልጅ ለኢያቡስቴ ከብንያም ልጆች ዐሥራ ሁለት፥ ከዳዊትም ብላቴኖች ዐሥራ ሁለት ተቈጥረው ተነሡ።'),
  ('4b5a97b6-e656-5afb-aea8-ecb450bf73ce', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 5, 16, 'ሁሉም እያንዳንዱ የወደረኛውን ራስ በእጁ ያዘ፤ ሰይፉንም በወደረኛው ጐን ሻጠ፤ ተያይዘውም ወደቁ። የዚያም ስፍራ ስም “በገባዖን የሸመቁ ሰዎች ድርሻ” ተብሎ ተጠራ፤'),
  ('651c5054-7285-524a-ace7-f8822971aa25', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 6, 17, 'በዚያም ቀን እጅግ ጽኑ ሰልፍ ሆነ፤ በዳዊትም ሰዎች ፊት አበኔርና የእስራኤል ሰዎች ተሸነፉ።'),
  ('b4a94cc9-71f1-510d-ae0b-ebea3db0d686', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 7, 18, 'በዚያም ሦስቱ የሦርህያ ልጆች ኢዮአብና አቢሳ፥ አሣሄልም ነበሩ፤ የአሣሄልም እግሮቹ ፈጣኖች ነበሩ፤ እንደ ዱር ሚዳቋም ሯጭ ነበረ።'),
  ('eee8466e-10a4-5c60-acc0-f86cce8e9a43', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 8, 19, 'አሣሄልም የአበኔርን ፍለጋ ተከታተለ፤ አበኔርንም ከማሳደድ ቀኝና ግራ አላለም።'),
  ('4c89f127-5302-5f24-aebb-5f4ab9bfe7cd', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 9, 20, 'አበኔርም ወደ ኋላው ተመልሶ፥ “አንተ አሣሄል ነህን?” አለው። እርሱም፥ “አዎ፥ እኔ ነኝ” አለው።'),
  ('653ffd21-f34c-5414-a90f-ecf984c79c35', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 10, 21, 'አበኔርም፥ “ወደ ቀኝ ወይም ወደ ግራ ፈቀቅ በል፤ ከብላቴኖቹም አንድ ጐልማሳ ያዝ፤ መሣሪያውንም ለራስህ ውሰድ” አለው። አሣሄል ግን እርሱን ከማሳደድ ፈቀቅ ይል ዘንድ እንቢ አለ።'),
  ('d5fc5bb0-8efa-5057-a588-c299ef4edc62', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 11, 22, 'አበኔርም አሣሄልን፥ “ከምድር ጋር እንዳላጣብቅህ እኔን ከማሳደድ ፈቀቅ በል፤ ወደ ወንድምህ ወደ ኢዮአብ ፊቴን አቅንቼ አይ ዘንድ እንዴት ይቻለኛል? እንደዚህ አይሆንምና ወደ ወንድምህ ወደ ኢዮአብ ተመለስ” አለው።'),
  ('43861686-ca60-59e1-a76f-dbcef798ed35', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 12, 23, 'ነገር ግን ከእርሱ ፈቀቅ ይል ዘንድ እንቢ አለ። አበኔርም በጦሩ ጫፍ ወገቡን ወጋው፤ ጦሩም በኋላው ወጣ፤ በዚያም ስፍራ ወድቆ በበታቹ ሞተ። አሣሄልም ወድቆ በሞተበት ስፍራ የሚያልፍ ሁሉ ይቆም ነበር።'),
  ('adc2dd5c-a40a-52fb-a9bc-8964dcfdbc3e', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 13, 24, 'ኢዮአብና አቢሳም አበኔርን አሳደዱ፤ ፀሐይም ጠለቀች፤ እነርሱም በገባዖን ምድረ በዳ መንገድ በጋይ ፊት ለፊት እስካለው እስከ አማን ኮረብታ ድረስ መጡ።'),
  ('834e1bc9-8926-5a4b-a3d5-78bd381b22c8', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 14, 25, 'በአበኔር ኋላ የነበሩ የብንያምም ልጆች ተሰበሰቡ፥ በአንድነትም ሆኑ፤ በአንድ ኮረብታም ራስ ላይ ቆሙ።'),
  ('1a54246d-d320-560e-a3a5-3e0b4835218f', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 15, 26, 'አበኔርም ኢዮአብን ጠርቶ እንዲህ አለው፥ “ሰይፍ ለድል የምታጠፋ አይደለምን? ፍጻሜዋስ መራራ እንደ ሆነ አታውቅምን? ሕዝቡ ወንድሞቻቸውን ከማሳደድ ይመለሱ ዘንድ ሕዝቡን የማትናገር እስከ መቼ ነው?”'),
  ('87078330-2a07-54e4-a070-d9327b1886e9', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 16, 27, 'ኢዮአብም፥ “ሕያው እግዚአብሔርን! ባትናገር ኖሮ ሕዝቡ ሁሉ በጥዋት በወንድሞቻቸው ላይ በወጡ ነበር” አለ።'),
  ('31039da5-97e2-5cab-a405-4f34e3596a51', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 17, 28, 'ኢዮአብም ቀንደ መለከት ነፋ፤ ሕዝቡም ሁሉ ተመለሰ፤ ከዚያም በኋላ እስራኤልን አላሳደዱአቸውም፤ ደግመውም አልተዋጉም።'),
  ('f3105756-4752-56e6-ae2e-d51f50311e52', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 18, 29, 'አበኔርና ሰዎቹም ሌሊቱን ሁሉ ወደ ምዕራብ ሄዱ፤ ዮርዳኖስንም ተሻገሩ፤ ያን ቀጥተኛ መንገድ ካለፉ በኋላም ወደ ሰፈር መጡ።'),
  ('12603959-c69a-5482-a3c8-ea89f88865eb', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 19, 30, 'ኢዮአብም አበኔርን ከማሳደድ ተመለሰ፤ ሕዝቡንም ሁሉ ሰበሰበ፤ የዳዊትንም ብላቴኖች አስቈጠራቸው፤ የሞቱትም ሰዎች ከአሣሄል ሌላ ዐሥራ ዘጠኝ ሰዎች ናቸው።'),
  ('14ab6a3a-7997-5da6-a3bc-16177dec3248', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 20, 31, 'የዳዊትም ብላቴኖች ከብንያም እና ከአበኔር ሰዎች ሦስት መቶ ስድሳ ሰዎችን ገደሉ።'),
  ('2d1da00d-ed44-5ecf-a531-096ddac1ba19', 'f46bd9d5-1403-5175-a83b-b9b46c65f9a3', '8cffad68-e2f5-5850-aa4e-93c013d35cc7', 21, 32, 'አሣሄልንም አንሥተው በቤተ ልሔም በአባቱ መቃብር ቀበሩት፤ ኢዮአብና ከእርሱ ጋር የነበሩ ሰዎቹም ሌሊቱን ሁሉ፤ ሄዱ፥ በኬብሮንም አነጉ።'),
  ('6ad5d9fe-8a00-5322-a5c7-a40da465ea81', '1b3d675c-7951-572f-acaf-568600e36910', '738bd328-8635-553e-ade4-6b0f464f223b', 1, 1, 'በሳኦል ቤትና በዳዊት ቤት መካከል ለብዙ ጊዜ ጦርነት ሆነ፤ የዳዊት ቤት እየበረታ፥ የሳኦል ቤት ግን እየደከመ የሚሄድ ሆነ።'),
  ('5cf71e01-6631-5f3c-add4-0ff4fecf0687', '1b3d675c-7951-572f-acaf-568600e36910', '738bd328-8635-553e-ade4-6b0f464f223b', 2, 2, 'ለዳዊትም ወንዶች ልጆች በኬብሮን ተወለዱለት፤ በኵሩም ከኢይዝራኤላዊቱ ከአኪናሆም የተወለደው አምኖን ነበረ።'),
  ('86aff47f-c586-52c6-a2ba-e46c358f8e03', '1b3d675c-7951-572f-acaf-568600e36910', '738bd328-8635-553e-ade4-6b0f464f223b', 3, 3, 'ሁለተኛውም ከቀርሜሎሳዊቱ ከአቤግያ የተወለደው ዶሎሕያ ነበረ። ሦስተኛውም ከጌድሶር ንጉሥ ከቶልሜልም ልጅ ከመዓክ የተወለደው አቤሴሎም ነበረ።'),
  ('cbcce217-3010-53ec-a5da-635bb09e5ffb', '1b3d675c-7951-572f-acaf-568600e36910', '738bd328-8635-553e-ade4-6b0f464f223b', 4, 4, 'አራተኛውም የአጊት ልጅ አዶንያስ፥ አምስተኛውም የአቢጣል ልጅ ሰፋጥያ ነበረ።'),
  ('64ccbd92-eaeb-5549-ad0b-bc5ec8d57b8c', '1b3d675c-7951-572f-acaf-568600e36910', '738bd328-8635-553e-ade4-6b0f464f223b', 5, 5, 'ስድስተኛውም የዳዊት ሚስት የዒገል ልጅ ይትረኃም ነበረ። ለዳዊት በኬብሮን የተወለዱለት እነዚህ ነበሩ።'),
  ('ae5570d2-e65a-5ba6-ab99-d9998e2053f2', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 1, 6, 'በሳኦል ቤትና በዳዊት ቤት መካከል ጦርነት ሆኖ ሳለ አበኔር የሳኦልን ቤት ያበረታ ነበር።'),
  ('274a7828-e3ca-576e-a3d4-d5bbad544da3', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 2, 7, 'ለሳኦልም የኢዮሄል ልጅ ሩጻፋ የተባለች ዕቅብት ነበረችው፤ ኢያቡስቴም አበኔርን፥ “ወደ አባቴ ዕቅብት ለምን ገባህ?” አለው።'),
  ('294c5abc-7200-5be3-a3ab-ef7e5c789af9', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 3, 8, 'አበኔርም ኢያቡስቴ እንዲህ ስላለው እጅግ ተቈጣ፤ አበኔርም እንዲህ አለው፥ “በውኑ እኔ የውሻ ራስ ነኝን? እኔ ለአባትህ ለሳኦል ቤት ለወንድሞቹም፥ ለዘመዶቹም ቸርነት አድርጌአለሁ፤ አንተንም ለዳዊት እጅ አሳልፌ አልሰጠሁህም፤ አንተም ዛሬ ከዚህች ሴት ጋር ስለ ሠራሁት ኀጢአት ትከስሰኛለህ።'),
  ('60418d3b-28bd-5c57-a49b-4041b3360ac5', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 4, 9, 'እግዚአብሔር ለዳዊት እንደ ማለለት እንዲሁ ከእርሱ ጋር ዛሬ ባላደርግ እግዚአብሔር በአበኔር ይህን ያድርግበት፤ ይህንም ይጨምርበት።'),
  ('ff0f0174-8725-564b-a766-cad7272e3f28', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 5, 10, 'የዳዊትንም ዙፋን በእስራኤልና በይሁዳ ከዳን ጀምሮ እስከ ቤርሳቤህ ድረስ ከፍ ያደርግ ዘንድ መንግሥትን ከሳኦል ቤት ወሰዳት።”'),
  ('ca07405b-5080-57dd-a843-d38abaeec2c9', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 6, 11, 'ኢያቡስቴም አበኔርን ይፈራው ነበርና ቃልን ይመልስለት ዘንድ አልቻለም።'),
  ('3007d648-f575-584d-a40c-c49914489f08', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 7, 12, 'አበኔርም ለዳዊት፥ “ከእኔ ጋር ቃል ኪዳን አድርግ፤ እጄም ከአንተ ጋር ትሆናለች፤ እስራኤልንም ሁሉ ወደ አንተ እመልሰዋለሁ” ብለው በስሙ ይነግሩት ዘንድ መልእክተኞችን ወዲያውኑ ላከለት።'),
  ('a9347967-fd7c-5e1f-a80d-58c8e4810852', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 8, 13, 'ዳዊትም፥ “ይሁን፤ በመልካም ፈቃደኛነት ከአንተ ጋር ቃል ኪዳን አደርጋለሁ፤ ነገር ግን አንድ ነገር ከአንተ እሻለሁ፤ ፊቴን ለማየት በመጣህ ጊዜ፥ የሳኦልን ልጅ ሜልኮልን ካላመጣህልኝ ፊቴን አታይም” አለው።'),
  ('4716a4f9-9359-5477-af5f-f23c50284bbb', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 9, 14, 'ዳዊትም ወደ ሳኦል ልጅ ወደ ኢያቡስቴ፥ “በመቶ ፍልስጥኤማውያን ሸለፈት ያጨኋትን ሚስቴን ሜልኮልን መልስልኝ” ብሎ መልእክተኞችን ላከ።'),
  ('83733b5a-d7c0-543a-ae87-a40d44ebf65a', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 10, 15, 'ኢያቡስቴም ልኮ ከሴሊስ ልጅ ከባልዋ ከፈላጥያል ወሰዳት።'),
  ('3302a1bb-aebd-5ae7-af79-6cfec95d8e95', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 11, 16, 'ባልዋም እያለቀሰ ከእርስዋ ጋር ሄደ፤ እስከ ብራቂም ድረስ ተከተላት። አበኔርም፥ “ሂድ፤ ተመለስ” አለው፤ እርሱም ተመለሰ።'),
  ('ff38b246-3823-5fe6-ad2d-74fc067e30ce', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 12, 17, 'አበኔርም ለእስራኤል ሽማግሌዎች፥ “አስቀድሞ ዳዊት በእናንተ ላይ ንጉሥ ይሆን ዘንድ ፈልጋችሁ ነበር።'),
  ('6a6bbe55-ff04-578e-aa10-74369f3e798f', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 13, 18, 'እግዚአብሔርም ስለ ዳዊት፦ በባሪያዬ በዳዊት እጅ ሕዝቤን እስራኤልን ክፍልስጥኤማውያን እጅና ከጠላቶቻቸው ሁሉ እጅ አድናለሁ ብሎ ተናግሮአልና እንግዲህ አሁን አድርጉ´ ብሎ ነገራቸው።'),
  ('88ca7081-6e78-51df-a2ad-69b3111f36a7', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 14, 19, 'አበኔርም ደግሞ በብንያም ልጆች ጆሮ ተናገረ፤ አበኔርም ደግሞ በእስራኤልና በብንያም ቤት ሁሉ መልካም የነበረውን ለዳዊት ሊነግረው ወደ ኬብሮን ሄደ።'),
  ('bcafedb1-d897-567c-af70-67d700982568', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 15, 20, 'አበኔርም ከሃያ ሰዎች ጋር ወደ ዳዊት ወደ ኬብሮን መጣ፤ ዳዊትም ለአበኔርና ከእርሱ ጋር ለነበሩት ሰዎች ግብዣ አደረገላቸው።'),
  ('2f6b3258-f758-5fd5-ae9b-58ad8cdcbe32', '1b3d675c-7951-572f-acaf-568600e36910', '6178a69e-c731-52e9-ae0c-2f41b73ed3a4', 16, 21, 'አበኔርም ዳዊትን፥ “ተነሥቼ ልሂድ፤ ካንተ ጋርም ቃል ኪዳን እንዲያደርጉ፥ ነፍስህም እንደ ወደደች ሁሉን እንድትገዛ እስራኤልን ሁሉ ለጌታዬ ለንጉሥ ልሰብስብ” አለው። ዳዊትም አበኔርን አሰናበተው፤ በሰላምም ሄደ።'),
  ('afc0e1bd-a3bd-52c5-a182-08de8fa10a7d', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 1, 22, 'በዚያ ጊዜም የዳዊት ብላቴኖችና ኢዮአብ ከዘመቻ ታላቅ ምርኮ ይዘው መጡ። አበኔር ግን ዳዊት አሰናብቶት በደኅና ሄዶ ነበር እንጂ በኬብሮን አልነበረም።'),
  ('5d08de31-481f-5be1-ac5e-9b87942af761', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 2, 23, 'ኢዮአብና ከእርሱም ጋር የነበረ ጭፍራ ሁሉ በመጡ ጊዜ፥ “የኔር ልጅ አበኔር ወደ ንጉሥ መጣ፤ አሰናበተውም፤ በሰላምም ሄደ” ብለው ሰዎች ለኢዮአብ ነገሩት።'),
  ('a5bd0d46-552f-567c-a54d-2fab3c8a4af1', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 3, 24, 'ኢዮአብም ወደ ንጉሥ ገብቶ፥ “ይህ ያደረግኸው ነገር ምንድን ነው? እነሆ፥ አበኔር መጥቶልህ ነበር፤ በደኅና እንዲሄድ ስለምን አሰናበትኸው?'),
  ('43ca6337-5e87-503f-a868-dc177fccc9f2', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 4, 25, 'የኔር ልጅ አበኔር ያታልልህ ዘንድ፥ መውጫህንና መግቢያህንም ያውቅ ዘንድ ፥ የምታደርገውንም ነገር ሁሉ ያስተውል ዘንድ እንደ መጣ አታውቅምን?” አለው።'),
  ('785f9016-0ecd-5274-a2f2-1dc9d2dc43f2', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 5, 26, 'ኢዮአብም ከዳዊት በወጣ ጊዜ መልእክተኞችን ከአበኔር በኋላ ላከ፤ ከሴይርም ጕድጓድ መለሱት። ዳዊት ግን ይህን አላወቀም።'),
  ('65adce39-f2bb-5971-aca1-dfc236cda715', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 6, 27, 'አበኔርም ወደ ኬብሮን በተመለሰ ጊዜ ኢዮአብ በበር ውስጥ በቈይታ ይናገረው ዘንድ ወደ አጠገቡ ወሰደው፤ በዚያም ለወንድሙ ለአሣሄል ደም ተበቅሎ ወገቡን መታው፤ ሞተም።'),
  ('54c13c98-195e-5bf9-a412-9864100506a1', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 7, 28, 'ከዚህም በኋላ ዳዊት ሰማ፤ እንዲህም አለ፥ “ከኔር ልጅ ከአበኔር ደም በእግዚአብሔር ዘንድ ለዘለዓለም እኔ ንጹሕ ነኝ፤ መንግሥቴም ንጹሕ ነው፤'),
  ('159f293f-114b-57f1-aecf-c37146eb1c3e', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 8, 29, 'በኢዮአብ ራስ ላይና በአባቱ ቤት ሁሉ ላይ ይምጣበት፤ በኢዮአብም ቤት ፈሳሽ ነገር ያለበት ወይም ለምጻም ወይም አንካሳ ወይም በሰይፍ የሚወድቅ ወይም እንጀራ የሌለው ሰው አይታጣ።”'),
  ('37d09209-2870-5513-a69b-2e36bb6d3bca', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 9, 30, 'ኢዮአብና ወንድሙ አቢሳም በሰልፍ በገባዖን ወንድማቸውን አሣሄልን ገድሎ ነበርና አበኔርን ይገድሉት ዘንድ ይጠባበቁ ነበር።'),
  ('dc91e987-5c45-5ed8-a4c5-723159671938', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 10, 31, 'ዳዊትም ኢዮአብንና ከእርሱ ጋር የነበሩትን ሕዝብ ሁሉ፥ “ልብሳችሁን ቅደዱ፤ ማቅም ልበሱ፤ በአበኔርም ፊት አልቅሱ” አላቸው። ንጉሡም ዳዊት ከቃሬዛው በኋላ ሄደ።'),
  ('cde6790d-9c5c-5e09-adbb-74c11c653d14', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 11, 32, 'አበኔርንም በኬብሮን ቀበሩት፤ ንጉሡም ድምፁን ከፍ አድርጎ በመቃብሩ አጠገብ አለቀሰ፤ ሕዝቡም ሁሉ ለአበኔር አለቀሱለት።'),
  ('dcf8752f-2301-5b6d-ae85-26f8da9da60d', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 12, 33, 'ንጉሡም ለአበኔር አለቀሰለት፤ እንዲህም አለ፦'),
  ('ce77fbb4-b66b-5a13-a43f-e409f546a2d7', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 13, 35, 'ሕዝቡም ሁሉ ገና ሳይመሽ ዳዊትን እንጀራ ይበላ ዘንድ ሊጋብዙት መጡ፤ ዳዊት ግን፥ “ፀሐይ ሳትጠልቅ እንጀራ ወይም ሌላ ነገር ብቀምስ እግዚአብሔር ይህን ያድርግብኝ፥ ይህንም ይጨምርብኝ” ብሎ ማለ።'),
  ('270c07f4-e3ed-5478-a9df-420148dd66bc', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 14, 36, 'ሕዝቡም ሁሉ ይህን ዐወቁ፤ በሕዝቡም ሁሉ ፊት ንጉሥ ያደረገው ሁሉ ደስ አሰኛቸው።'),
  ('87475dec-9086-54df-a6c3-31a919a89929', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 15, 37, 'በዚያም ቀን ሕዝቡ ሁሉ እስራኤልም ሁሉ የኔር ልጅ አበኔርን እንዲገድሉት ንጉሡ እንዳላዘዘ ዐወቁ።'),
  ('51d96adb-0a09-5203-ad50-0e1c00ce63d1', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 16, 38, 'ንጉሡም ብላቴኖቹን፥ “ዛሬ በእስራኤል ዘንድ ታላቅ መኰንን እንደ ወደቀ አታውቁምን?'),
  ('2837da2b-e61a-5e55-a143-76bc5a24210a', '1b3d675c-7951-572f-acaf-568600e36910', '8cb1d75f-7ce7-52d7-a1db-643d08a3de91', 17, 39, 'እኔም ዛሬ ዘመዱ እንደ ሆንሁ፥ እርሱም በንጉሡ ዘንድ የተሾመ እንደ ሆነ አታውቁምን? እነዚህም ሰዎች የሦርህያ ልጆች በርትተውብኛል፤ እግዚአብሔርም ክፋት በሠራ ላይ እንደ ክፋቱ ይመልስበት” አላቸው።'),
  ('78e44e0b-7860-50ea-a9d0-c0d47a954868', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 1, 1, 'የሳኦልም ልጅ ኢያቡስቴ አበኔር በኬብሮን እንደ ሞተ ሰማ፤ እጆቹም ደከሙ፤ እስራኤላውያንም ሁሉ ደነገጡ።'),
  ('769b240f-375f-5177-a880-5f7784d4d530', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 2, 2, 'ለሳኦልም ልጅ ለኢያቡስቴ የጭፍራ አለቆች የሆኑ ሁለት ሰዎች ነበሩት፤ የአንደኛው ስም በዓና፥ የሁለተኛውም ስም ሬካብ ነበረ፤ ከብንያምም ልጆች የቤሮታዊው የሬሞን ልጆች ነበሩ፤ ቤሮትም ለብንያም ተቈጥራ ነበር።'),
  ('923b20f0-0159-5f3a-a289-83589b23c412', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 3, 3, 'ቤሮታውያንም ወደ ጌቴም ሸሽተው ነበር፤ እስከ ዛሬም ድረስ በዚያ ተጠግተው ነበር።'),
  ('92060490-3ff3-55ff-a5ca-2c33f71bde59', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 4, 4, 'ለሳኦልም ልጅ ለዮናታን አንድ ሽባ የሆነ ልጅ ነበረው። የሳኦልና የዮናታን ወሬ ከኢይዝራኤል በመጣ ጊዜ የአምስት ዓመት ልጅ ነበረ፤ ሞግዚቱም አዝላው ሸሸች፤ ልትሸሽም ስትሮጥ ወድቆ ሽባ ሆነ። ስሙም ሜምፌቡስቴ ነበረ።'),
  ('18cbfa9e-8dbd-508f-a7c5-2ae6f81af7c5', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 5, 5, 'የቤሮታዊውም የሬሞን ልጆች ሬካብና በዓና ቀኑ ሲሞቅ ወደ ኢያቡስቴ ቤት መጡ፤ እርሱም በቀትር ጊዜ በአልጋው ላይ ተኝቶ ነበር።'),
  ('d8cc760f-edad-59da-ac6c-3dac460132ca', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 6, 6, 'በረኛዪቱም ስንዴ ታበጥር ነበር፤ አንቀላፍታም ተኝታ ነበር፤ ወንድማማቾቹ ሬካብና በዓናም በቀስታ ወደ ቤት ገቡ።'),
  ('8de89ee0-ed98-5097-a4d7-58abe8009a99', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 7, 7, 'ወደ ቤትም በገቡ ጊዜ ኢያቡስቴ በእልፍኙ በምንጣፉ ላይ ተኝቶ ሳለ መቱት፥ ገደሉትም፤ ራሱንም ቈርጠው ወሰዱት፥ በዓረባም መንገድ ሌሊቱን ሁሉ ሄዱ።'),
  ('f9f6ba01-bd44-58cc-ab40-01471b72df80', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 8, 8, 'የኢያቡስቴንም ራስ ይዘው ወደ ዳዊት ወደ ኬብሮን መጡ፤ ንጉሡንም፥ “ነፍስህን ይሻ የነበረው የጠላትህ የሳኦል ልጅ የኢያቡስቴ ራስ እነሆ፤ እግዚአብሔርም ዛሬ ከጠላትህ ከሳኦልና ከዘሩ ለጌታችን ለንጉሥ በቀሉን መለሰለት” አሉት።'),
  ('88849b38-af7a-50ac-a08c-722e1bd01090', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 9, 9, 'ዳዊትም ለቤሮታዊው ለሬሞን ልጆች ለሬካብና ለወንድሙ ለበዓና እንዲህ ብሎ መለሰላቸው፥ “ነፍሴን ከመከራ ሁሉ ያዳነ ሕያው እግዚአብሔርን!'),
  ('5d77a012-f799-5812-a1b5-65bd3984d342', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 10, 10, 'መልካም ወሬ የያዘ መስሎት እነሆ፥ ሳኦል ሞተ ብሎ የነገረኝን የምስራቹ ዋጋ እንዲሆን ይዤ በሴቄላቅ ገደልሁት።'),
  ('c1b12ac7-43ef-5556-a64f-30ad815c1cbb', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 11, 11, 'አሁንም እናንተ ክፉዎች ሰዎች በቤቱ ውስጥ በአልጋው ላይ ጻድቁን ሰው ገደላችሁት፤ እነሆ፥ ደሙን ከእጃችሁ እሻለሁ፤ ከምድርም አጠፋችኋለሁ።”'),
  ('ef75af22-7c12-5a58-a2c6-dced1f4d81fe', '2031756b-c91b-5a7f-aec5-099f7df0059b', '037a2dbc-fa49-5066-a932-f4f7b55f6d15', 12, 12, 'ዳዊትም ጐልማሶቹን አዘዘ፤ ገደሉአቸውም፤ እጆቻቸውንና እግሮቻቸውን ቈርጠው በኬብሮን በውኃ መቆሚያ አጠገብ አንጠለጠሉአቸው። የኢያቡስቴን ራስ ግን ወስደው በአበኔር መቃብር በኬብሮን ቀበሩት።'),
  ('4a353d5c-feaa-5732-aeec-a2789cff11c7', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 1, 1, 'የእስራኤልም ነገድ ሁሉ ወደ ኬብሮን ወደ ዳዊት መጥተው እንዲህ አሉት፥ “እኛ የአጥንትህ ፍላጭ የሥጋህ ቍራጭ ነን።'),
  ('2bb05207-7826-5b06-a9e8-9097e09f4868', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 2, 2, 'አስቀድሞ ሳኦል በእኛ ላይ ንጉሥ ሆኖ ሳለ እስራኤልን የምታወጣና የምታገባ አንተ ነበርህ፤ እግዚአብሔርም፦ አንተ ሕዝቤን እስራኤልን ትጠብቃለህ፤ በእስራኤልም ላይ አለቃ ትሆናለህ ብሎህ” ነበር።'),
  ('5481d88a-a482-5ae1-a9f9-d9a5a61c3807', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 3, 3, 'የእስራኤልም ሽማግሌዎች ሁሉ ወደ ንጉሡ ወደ ኬብሮን መጡ፤ ንጉሡ ዳዊትም በኬብሮን በእግዚአብሔር ፊት ከእነርሱ ጋር ቃል ኪዳን አደረገ፤ በእስራኤልም ንጉሥ ይሆን ዘንድ ዳዊትን ቀቡት።'),
  ('91fba798-2491-5f5c-a4f2-767280fe4eb0', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 4, 4, 'ዳዊትም መንገሥ በጀመረ ጊዜ የሠላሳ ዓመት ጐልማሳ ነበረ፤ አርባ ዓመትም ነገሠ፤'),
  ('a3dae697-dba3-5aab-a719-19a431efdacf', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 5, 5, 'በኬብሮን በይሁዳ ላይ ሰባት ዓመት ከስድስት ወር ነገሠ፤ በኢየሩሳሌምም በእስራኤል ሁሉና በይሁዳ ላይ ሠላሳ ሦስት ዓመት ነገሠ።'),
  ('2f0c3c36-7eef-59ba-a659-f6f2068f8e38', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 6, 6, 'ዳዊትና ሰዎቹም በሀገሩ ውስጥ ወደሚኖሩት ወደ ኢያቡሴዎናውያን ወደ ኢየሩሳሌም ሄዱ፤ እነርሱም ዳዊትን፥ “ወደዚህ አትገባም” አሉት። ዕውሮችና አንካሶችም ወደዚህ አትገባም ብለው ተቃወሙት።'),
  ('e87e116a-6b0f-5f67-a7db-bbd8d9e86750', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 7, 7, 'ነገር ግን ዳዊት አንባዪቱን ጽዮንን ያዘ፤ እርስዋም የዳዊት ከተማ ናት።'),
  ('e23ce444-7638-5c85-ac7f-095905bc68d0', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 8, 8, 'በዚያም ቀን ዳዊት፥ “ኢያቡሴዎናውያንን የሚመታ ሁሉ፥ ዕውሮችንና አንካሶችን፥ የዳዊትንም ነፍስ የሚጠሉትን ሁሉ በሳንጃ ይውጋቸው” አለ። ስለዚህም፥ “ዕውርና አንካሳ ወደ እግዚአብሔር ቤት አይግቡ” ተባለ።'),
  ('394208f6-99ef-5cf4-a655-213379eb5bf0', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 9, 9, 'ዳዊትም በአንባዪቱ ውስጥ ተቀመጠ፤ እርስዋም የዳዊት ከተማ ተባለች። ከተማዋንም ዙሪያዋን እስከ ዳርቻዋ ድረስ ቀጠራት፤ ቤቱንም ሠራ።'),
  ('36bf2379-4feb-5ec9-a996-2d02b1615db8', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 10, 10, 'ዳዊትም እየበረታ፥ ከፍ እያለም ሄደ፤ ሁሉን የሚችል እግዚአብሔርም ከእርሱ ጋር ነበረ።'),
  ('682db299-ff3c-5a70-a260-a968167ab3d6', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 11, 11, 'የጢሮስ ንጉሥ ኪራም ወደ ዳዊት መልእክተኞችን፥ የዝግባ እንጨትንም፥ አናጢዎችንም፥ ድንጋይ ጠራቢዎችንም ላከ፤ ለዳዊትም ቤት ሠሩለት።'),
  ('e7ccfc12-3250-56d6-a44a-fbc0bcbedd02', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 12, 12, 'ዳዊትም እግዚአብሔር በእስራኤል ላይ ንጉሥ አድርጎ እንዳዘጋጀው፥ ስለ ሕዝቡ ስለ እስራኤልም መንግሥቱን ከፍ እንዳደረገ ዐወቀ።'),
  ('ab872f01-7ab2-51ed-acc1-851fa7112b57', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 13, 13, 'ዳዊትም ከኬብሮን ከመጣ በኋላ እንደ ገና ቁባቶቹንና ሚስቶቹን ከኢየሩሳሌም ወሰደ፤ ለዳዊትም ደግሞ ወንዶችና ሴቶች ልጆች ተወለዱለት።'),
  ('a36631d6-6b44-55fc-a7f6-b8e93898df81', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 14, 14, 'በኢየሩሳሌምም የተወለዱለት ስማቸው ይህ ነው፤ ሳሚስ፥ ሶባብ፥ ናታን፥ ሰሎሞን፥'),
  ('078fee9a-ee0f-507d-a5fe-80fd1455229f', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 15, 15, 'ኢያቢሖር፥ ኤሊሱስ፥ ናፌቅ፥ ያፍያ፥'),
  ('796eea94-0930-533d-a9c6-9beb019c78a2', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'b32da413-940b-54ff-a033-2b6d7108c3d3', 16, 16, 'ኤሊሳማ፥ ኤሊዳሂ፥ ኤሊፋላት፥ ሶሜኤ፥ ኢያሴቦት፥ ናታን፥ ጋላማሄን፥ የበአር፥ ትሄሱስ፥ ኤልፋላት፥ ናጌድ፥ ናሬት፥ ያናታ፥ ሊሳሚስ፥ በአሊማት፥ ኤልፋላድ።'),
  ('3420decb-3a27-53db-af61-d1a1d1784f93', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'c196b86b-19bc-5657-abb3-19a8aca50d68', 1, 17, 'ፍልስጥኤማውያንም ዳዊት በእስራኤል ላይ ንጉሥ ሆኖ እንደ ተቀባ ሰሙ፤ ፍልስጥኤማውያንም ሁሉ ዳዊትን ሊፈልጉ ወጡ፤ ዳዊትም በሰማ ጊዜ ወደ ምሽጉ ወረደ።'),
  ('44f9cc42-865c-5d5b-a81b-0a5e68607522', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'c196b86b-19bc-5657-abb3-19a8aca50d68', 2, 18, 'ፍልስጥኤማውያንም መጥተው በረዓይት ሸለቆ ተበትነው ሰፈሩ።'),
  ('77e1bfac-145d-5ef6-ac0d-cb57bc477878', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'c196b86b-19bc-5657-abb3-19a8aca50d68', 3, 19, 'ዳዊትም፥ “ወደ ፍልስጥኤማውያን ልውጣን? በእጄስ አሳልፈህ ትሰጣቸዋለህን?” ብሎ እግዚአብሔርን ጠየቀ። እግዚአብሔርም ዳዊትን፥ “ፍልስጥኤማውያንን በርግጥ በእጅህ አሳልፌ እሰጣቸዋለሁና ውጣ” አለው።'),
  ('2f9ecb87-139b-5900-ac58-1039162eee09', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'c196b86b-19bc-5657-abb3-19a8aca50d68', 4, 20, 'ዳዊትም ከላይኛው መጋደያ መጣ፤ በዚያም መታቸውና፥ “ውኃ እንደሚያጠፋ እግዚአብሔር ጠላቶቼን ፍልስጥኤማውያንን በፊቴ አጠፋቸው” አለ። ስለዚህም የዚያ ስፍራ ስም “የላይኛው መጋደያ” ተብሎ ተጠራ።'),
  ('49859ae9-7c7c-53bc-a8b6-b7544ed20298', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'c196b86b-19bc-5657-abb3-19a8aca50d68', 5, 21, 'ጣዖቶቻቸውንም በዚያ ተዉ፤ ዳዊትና ሰዎቹም ወሰዱአቸው።'),
  ('dc7a85e2-42f9-51f3-a1c7-e79a61ea777d', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'c196b86b-19bc-5657-abb3-19a8aca50d68', 6, 22, 'ፍልስጥኤማውያንም ደግሞ መጡ፤ ወደ ረዓይትም ሸለቆ ወረዱ።'),
  ('82f90056-3b67-5188-ad9a-b9d276a5e299', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'c196b86b-19bc-5657-abb3-19a8aca50d68', 7, 23, 'ዳዊትም እግዚአብሔርን ጠየቀ፤ እግዚአብሔርም፥ “በኋላቸው ዞረህ በሾላው ዛፍ ፊት ለፊት ግጠማቸው እንጂ አትውጣ።'),
  ('83a5d4fc-3f75-5d8d-a25a-107e7be7d13e', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'c196b86b-19bc-5657-abb3-19a8aca50d68', 8, 24, 'በሾላውም ዛፍ ራስ ውስጥ የሽውሽውታ ድምፅ ስትሰማ፥ በዚያ ጊዜ እግዚአብሔር የፍልስጥኤማውያንን ጭፍራ ለመምታት በፊትህ ወጥቶ ይሆናልና በዚያ ጊዜ ፍጠን” አለው።'),
  ('29d85d0c-43f4-5af6-af56-c94a7ffed2f2', '45de5d3e-7d6d-5292-aa32-4a74bf5e8d10', 'c196b86b-19bc-5657-abb3-19a8aca50d68', 9, 25, 'ዳዊትም እግዚአብሔር እንዳዘዘው አደረገ፤ ከገባዖንም እስከ ጌሴራ ድረስ ፍልስጥኤማውያንን መታ።'),
  ('3b43e55f-4045-5b35-a689-8f6a3b45931a', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 1, 1, 'ዳዊትም ደግሞ ከእስራኤል የተመረጡትን ሰባ ሺህ ያህል ሰው ሰበሰበ።'),
  ('a7e85cac-1c96-50b0-a027-89e053f15032', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 2, 2, 'ዳዊትና ከእርሱ ጋር የነበሩት ሕዝብ ሁሉ ከይሁዳ አለቆች ጋር ተነሥተው በኪሩቤል ላይ የተቀመጠ የሠራዊት ጌታ የእግዚአብሔር ስም የተጠራባትን የእግዚአብሔርን ታቦት ከዚያ ያመጡ ዘንድ ሄዱ።'),
  ('19cd059c-b946-5029-a1d3-cebb64cd82f2', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 3, 3, 'የእግዚአብሔርንም ታቦት በአዲስ ሰረገላ ላይ ጫኑአት፥ በኮረብታውም ላይ ከነበረው ከአሚናዳብ ቤት አመጡአት፤ የአሚናዳብ ልጆችም ዖዛና ወንድሞቹ ታቦቷ ያለችበትን ሰረገላ ይነዱ ነበር።'),
  ('b7797396-a2bf-5a6b-ae31-07f952044026', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 4, 4, 'ወንድሞቹም በታቦቷ ፊት ይሄዱ ነበር።'),
  ('223b09a5-81cb-5c66-a3d5-5ee78e1fd28f', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 5, 5, 'ዳዊትና የእስራኤልም ልጆች ሁሉ በዜማ መሣሪያዎች በበገናና በመሰንቆ፥ በከበሮና በነጋሪት፥ በጸናጽልና በዕንዚራ በእግዚአብሔር ፊት በሙሉ ኀይላቸው ይጫወቱ ነበር።'),
  ('e44c339c-6766-5bb4-aa55-53189e13f368', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 6, 6, 'ወደ ናኮንም አውድማ ደረሱ፤ ዖዛም በሬዎቹ አነቃንቀዋት ነበርና ይይዛት ዘንድ ወደ እግዚአብሔር ታቦት እጁን ዘረጋ፤ አስተካከላትም። ሲይዛትም በሬው ወጋው።'),
  ('bd51b44d-4c6d-5754-a1ec-5a4765e9dfe8', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 7, 7, 'እግዚአብሔርም በዖዛ ላይ ተቈጣ፤ እግዚአብሔርም በዚያው ቀሠፈው። በእግዚአብሔርም ታቦት አጠገብ በእግዚአብሔር ፊት በዚያው ሞተ።'),
  ('a6dbd127-f1c6-53a7-a4e9-b77d3ba6e29c', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 8, 8, 'እግዚአብሔርም ዖዛን ስለ ገደለው ዳዊት አዘነ፤ እስከ ዛሬም ድረስ የዚያ ስፍራ ስም “ዖዛ የሞተበት” ተባለ።'),
  ('e260a47e-a9b6-539f-a446-ee66521d6f89', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 9, 9, 'በዚያም ቀን ዳዊት እግዚአብሔርን ፈራና፥ “የእግዚአብሔር ታቦት ወደ እኔ እንዴት ትገባለች?” አለ።'),
  ('23bdde3c-cc40-57fb-a5b3-09c113bc702a', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 10, 10, 'ዳዊትም የእግዚአብሔርን ታቦተ ሕግ ወደ እርሱ ወደ ዳዊት ከተማ ያመጣት ዘንድ አልወደደም፤ ዳዊትም በጌት ሰው በአቢዳራ ቤት አገባት።'),
  ('ea4fb481-c80a-5f7a-a8ca-7042cedb02cc', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 11, 11, 'የእግዚአብሔርም ታቦት በጌት ሰው በአቢዳራ ቤት ሦስት ወር ተቀመጠች፤ እግዚአብሔርም አቢዳራንና ቤቱን ሁሉ ባረከ።'),
  ('7cba593b-fcb8-5882-abf5-9e7653ff3c0a', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 12, 12, 'ለንጉሡ ዳዊትም “እግዚአብሔር የአቢዳራን ቤትና የነበረውን ሁሉ ስለ እግዚአብሔር ታቦት ባረከ” ብለው ነገሩት። ዳዊትም ሄዶ የእግዚአብሔርን ታቦት ከአቢዳራ ቤት ወደ ዳዊት ከተማ በደስታ አመጣት።'),
  ('e7c33120-0cfd-5b03-a20c-fc5df815abe8', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 13, 13, 'ከእርሱም ጋር የእግዚአብሔርን ታቦት የተሸከሙ ሰባት መሰንቆ የሚመቱ ክፍሎች ነበሩ። በሬዎችንና በጎችን ይሠዉ ነበር።'),
  ('8cbcccf0-003c-5320-a1f2-d10bc3fd7815', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 14, 14, 'ዳዊትም በእግዚአብሔር ፊት በገና ይደረድር ነበር፤ ዳዊትም ለዐይን የሚያንጸባርቅ የሐር ቀሚስ ለብሶ ነበር።'),
  ('18e1a5da-7e71-5eda-a675-189040c21039', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 15, 15, 'ዳዊትና የእስራኤልም ቤት ሁሉ በእልልታ ቀንደ መለከት እየነፉ የእግዚአብሔርን ታቦት አመጡአት።'),
  ('e05d5494-da72-547d-a586-82c06514ad6d', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 16, 16, 'የእግዚአብሔርም ታቦት ወደ ዳዊት ከተማ በደረሰች ጊዜ የሳኦል ልጅ ሜልኮል በመስኮት ሆና ተመለከተች፤ ንጉሡም ዳዊት በእግዚአብሔር ፊት ሲዘልልና ሲዘምር አየችው፥ በልብዋም ናቀችው።'),
  ('ac944afd-fb84-5d31-a8bd-51b2c187860f', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 17, 17, 'የእግዚአብሔርንም ታቦት አምጥተው ዳዊት በተከለላት ድንኳን ውስጥ በስፍራዋ አኖሩአት፤ ዳዊትም የሚቃጠልና የሰላም መሥዋዕትን በእግዚአብሔር ፊት አሳረገ።'),
  ('28a176d4-4fda-51eb-a816-21cc42e6a1d7', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 18, 18, 'ዳዊትም የሚቃጠልና የሰላም መሥዋዕት ማሳረግን ከፈጸመ በኋላ ሕዝቡን በሰራዊት ጌታ በእግዚአብሔር ስም መረቀ።'),
  ('7da8ceaa-fb55-5dff-af68-aa03c6a9e8d8', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 19, 19, 'ለሕዝቡም ሁሉ ለእስራኤል ወገን ከዳን እስከ ቤርሳቤህ ለወንዱም፥ ለሴቱም ለእያንዳንዱ አንዳንድ እንጀራ፥ አንዳንድም የሥጋ ቍራጭ፥ አንዳንድም ጽዋዕ ወይን አከፋፈለ። ሕዝቡም ሁሉ እያንዳንዱ ወደ ቤቱ ሄደ።'),
  ('b76834e4-f19d-5e15-ac3b-ad3e79a7d1ff', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 20, 20, 'ዳዊትም ቤተ ሰቡን ሊመርቅ ተመለሰ። የሳኦል ልጅ ሜልኮልም ዳዊትን ለመቀበል ወጣችና ሰላምታ ሰጠችው፥ “ከሚዘፍኑት አንዱ እንደሚገለጥ የእስራኤል ንጉሥ በአገልጋዮቹ ሚስቶች ፊት በመገለጡ ምንኛ የተከበረ ነው!” አለች።'),
  ('721e5032-5d73-52c8-a7d2-839a40466e6a', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 21, 21, 'ዳዊትም ሜልኮልን፥ “በእግዚአብሔር ፊት ዘምሬአለሁ፤ በእግዚአብሔር ሕዝብ በእስራኤል ላይ አለቃ እሆን ዘንድ ከአባትሽና ከቤቱ ሁሉ ይልቅ የመረጠኝ እግዚአብሔር የተመሰገነ ይሁን፤ ስለዚህም በእግዚአብሔር ፊት እጫወታለሁ፤ እዘምራለሁም፤'),
  ('67b41870-64a2-5b73-a7d4-4fa7d0b8a46e', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 22, 22, 'አሁንም እገለጣለሁ፤ በዐይንሽ ፊትና እንዴት ከበርህ ባልሽባቸው ሴቶች ልጆች ፊት የተናቅሁ እሆናለሁ” አላት።'),
  ('d2cfd48a-4d07-5b4f-abde-e35de531daea', '2a35cdca-b774-5ae9-abf0-6673893f1206', '179f13ea-793a-56a5-a1b3-23160fa5b44c', 23, 23, 'የሳኦልም ልጅ ሜልኮል እስከ ሞተችበት ቀን ድረስ ልጅ አልወለደችም።'),
  ('bb82841e-d6e5-57e5-a538-cd4c610aa24e', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 1, 1, 'እንዲህም ሆነ፤ ንጉሡ በቤቱ በተቀመጠ ጊዜ እግዚአብሔርም በዙሪያው ያሉ ጠላቶቹን ሁሉ ባወረሰው ጊዜ፥'),
  ('c9677e66-28c0-55a1-a8b0-ca70eddf9c7e', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 2, 2, 'ንጉሡ ነቢዩ ናታንን፥ “እኔ ከዝግባ በተሠራ ቤት ተቀምጬአለሁ፤ የእግዚአብሔር ታቦት ግን በድንኳን ውስጥ ተቀምጣለች” አለው።'),
  ('5e1201c3-b03b-5e65-abdf-d862b90d88ee', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 3, 3, 'ናታንም ንጉሡን፥ “እግዚአብሔር ከአንተ ጋር ነውና፥ ሂድና በልብህ ያሰብኸውን ሁሉ አድርግ” አለው።'),
  ('1d069822-1ea5-5529-a099-e7a7b46b9c66', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 4, 4, 'በዚያም ሌሊት የእግዚአብሔር ቃል ወደ ናታን መጣ፤ እንዲህም አለው፦'),
  ('7b90b519-63e4-5616-a45d-1fe1731ebed7', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 5, 5, '“ሂድ ለባሪያዬ ለዳዊት ንገረው፦ እግዚአብሔር እንዲህ ይላል፦ አንተ የምኖርበትን ቤት አትሠራልኝም።'),
  ('976307a6-ddd8-5c5b-a073-243134282d7c', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 6, 6, 'የእስራኤልን ልጆች ከግብፅ ምድር ካወጣሁበት ቀን ጀምሮ እስከ ዛሬ ድረስ በድንኳንና በማደሪያ እሄድና እመላለስ ነበር እንጂ በቤት አልተቀመጥሁምና፥'),
  ('fc56c716-3c95-5676-ad6c-3feedc759092', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 7, 7, 'ከእስራኤል ልጆች ሁሉ ጋር ባለፍሁበት ስፍራ ሁሉ፦ ስለምን ቤትን ከዝግባ እንጨት አልሠራችሁልኝም? ብዬ ሕዝቤን እስራኤልን ይጠብቅ ዘንድ ከእስራኤል ነገድ ላዘዝሁት ለአንዱ በውኑ ተናግሬአለሁን?'),
  ('d4c3b0d8-382c-5a4d-a092-a6d8a4b0eb6a', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 8, 8, 'አሁንም ዳዊትን ባሪያዬን እንዲህ በለው፦ ሁሉን የሚገዛ እግዚአብሔር እንዲህ ይላል፦ በሕዝቤ በእስራኤል ላይ አለቃ ትሆን ዘንድ ከበግ ጥበቃ ወሰድሁህ፤'),
  ('76724563-d78a-55af-a640-12e320ba12ba', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 9, 9, 'በሄድህበትም ሁሉ ከአንተ ጋር ነበርሁ፤ ጠላቶችህንም ሁሉ ከፊትህ አጠፋሁ፤ በምድርም ላይ እንዳሉ እንደ ታላላቆቹ ስም ስምህን ታላቅ አደረግሁ።'),
  ('7e447196-061e-5e79-ab0f-3b04e720f2e3', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 10, 10, 'ለሕዝቤም ለእስራኤል ስፍራ አደርጋለሁ፤ እተክላቸውማለሁ፤ ብቻቸውን ይቀመጣሉ፤ ከዚያም በኋላ የሚጠራጠሩት የለም፤ እንደ ቀድሞው ዘመን የኀጢአት ልጅ መከራ አያጸናባቸውም።'),
  ('fd26e415-5bef-574d-a600-d5ede8ed95d5', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 11, 11, 'በሕዝቤ በእስራኤል ላይ ፈራጆችን በሾምሁ ጊዜ ከጠላቶችህ ሁሉ አሳርፍሃለሁ። እግዚአብሔርም ደግሞ፦ ቤት እንደምትሠራለት ይነግርሃል፤ እሠራለታለሁ ብለሃልና።'),
  ('6a10314a-daaf-57cb-a972-91dfbcfefc4e', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 12, 12, 'ዕድሜህም በተፈጸመ ጊዜ፤ ከአባቶችህም ጋር ባንቀላፋህ ጊዜ፥ ከወገብህ የሚወጣውን ዘርህን ከአንተ በኋላ አስነሣለሁ፤ መንግሥቱንም አዘጋጃለሁ ።'),
  ('19a051ec-cc08-577c-a7e2-f57513a419d3', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 13, 13, 'እርሱ ለስሜ ቤት ይሠራል፤ ዙፋኑን ለዘለዓለም አጸናለሁ።'),
  ('3a71a62c-8f9b-5839-a429-5abf73d49ba9', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 14, 14, 'እኔም አባት እሆነዋለሁ፤ እርሱም ልጅ ይሆነኛል፤ ክፉ ነገርም ቢያደርግ፥ በሰዎች በትርና በሰው ልጆች አለንጋ እገሥጸዋለሁ፤'),
  ('72d69744-00ed-5c3d-a11c-f63418a199cc', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 15, 15, 'ከፊቴም ከጣልሁት ከሳኦል ቤት እንዳራቅሁ ምሕረቴን ከእርሱ አላርቅም።'),
  ('83833983-e66d-51fc-ab47-f1a27b0e4bc7', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 16, 16, 'ቤቱ የታመነ ይሆናል፤ መንግሥቱም በፊቴ ለዘለዓለም፥ ዙፋኑም ለዘለዓለም ይጸናል።”'),
  ('f51c764e-6a10-5fa3-a72f-dc04aad85019', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '7ce80d26-6f5a-51a6-a225-402fd047c1de', 17, 17, 'እንደዚህ ቃል ሁሉ፥ እንደዚህም ራእይ ሁሉ ናታን ለዳዊት እንዲሁ ነገረው።'),
  ('0cf353a0-f960-58b6-a7de-672953354512', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 1, 18, 'ንጉሡ ዳዊትም ገባ፤ በእግዚአብሔርም ፊት ተቀምጦ እንዲህ አለ፥ “ጌታዬ እግዚአብሔር ሆይ፥ ይህን ያህል የወደድኸኝ እኔ ማን ነኝ? ቤቴስ ምንድን ነው?'),
  ('c74dda51-da91-543b-a001-bb5af5278b71', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 2, 19, 'ጌታዬ እግዚአብሔር ሆይ፥ እኔ በፊትህ እጅግ ታናሽ ስሆን ስለ ባሪያህ ቤት ደግሞ ለሩቅ ዘመን ተናገርህ፤ ጌታዬ እግዚአብሔር ሆይ፥ ይህ የሰው ሕግ ነው።'),
  ('90551d34-850b-5eb8-aae0-508078f5f733', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 3, 20, 'ጌታዬ እግዚአብሔር ሆይ፥ አንተ ባሪያህን ታውቃለህና ዳዊትስ ይናገርህ ዘንድ የሚጨምረው ምንድን ነው?'),
  ('97742bea-6ff2-50a8-adc2-36467558332a', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 4, 21, 'ለባሪያህም ታስታውቀው ዘንድ ስለ ቃልህ ምክንያትና እንደ ልብህ አሳብ ይህን ታላቅ ነገር ሁሉ አደረግህ።'),
  ('9c1a959d-70d5-5c34-a3ab-a63a1dd15ed2', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 5, 22, 'ስለዚህም አቤቱ አምላኬ ሆይ፥ እንዳንተ ያለ የለምና፥ በጆሮአችንም እንደ ሰማን ሁሉ ከአንተ በቀር አምላክ የለምና አንተ ታላቅ ነህ።'),
  ('afc24686-b81c-5d4d-a387-23bdb4c9c3ee', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 6, 23, 'ለእርሱ ለራሱ እንዲሆን ሕዝብን ይቤዥ ዘንድ ለእርሱ ለራሱም ታላቅ ስምን ያደርግ ዘንድ አሕዛብንና ሰፈሮቻቸውን በመበተን ከግብፅ በተቤዠኸው ሕዝብህ ፊት ታምራትንና ድንቅን ያደርግ ዘንድ እግዚአብሔር እንደ መራው እንደ ሕዝብህ እንደ እስራኤል ያለ በምድር ላይ ምን ሕዝብ አለ?'),
  ('579bf793-d80d-575d-acff-f7875734357a', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 7, 24, 'ሕዝብህንም እስራኤልን ለዘለዓለም ሕዝብ አድርገህ አዘጋጅተኸዋል፤ አንተም፥ አቤቱ፥ አምላክ ሆነሃቸዋል።'),
  ('4b5cc2ef-ea71-5cd1-a245-d1fe0edf8a0a', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 8, 25, 'አቤቱ ሁሉን የምትገዛ የእስራኤል አምላክ ሆይ፥ አሁንም ለባሪያህና ለቤቱ የተናገርኸውን ለዘለዓለም አጽናው፤ አሁንም እንደ ተናገርህ አድርግ።'),
  ('6c183bbc-35c2-5f98-aeec-c3347460dc8c', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 9, 26, 'ስምህ ለዘለዓለም ታላቅ ይሁን።'),
  ('edbf9717-9c7f-5e41-a926-f1b43e0bc963', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 10, 27, 'አቤቱ የእስራኤል አምላክ የሰራዊት ጌታ ሆይ፥ የባሪያህን ጆሮ ከፈትህ። አንተ፦ እኔ ቤት እሠራልሃለሁ አልህ፤ ስለዚህም ባሪያህ ይህችን ጸሎት ወደ አንተ ይጸልይ ዘንድ በልቡ አሰበ።'),
  ('b952ab15-27a6-51f3-aec7-d88541d1cf3d', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 11, 28, 'ጌታዬ እግዚአብሔር ሆይ፥ አሁንም አንተ አምላክ ነህ፤ ቃልህም እውነት ነው፤ ይህንም መልካም ነገር ለባሪያህ ተናግረሃል።'),
  ('6cf55a67-e057-5a7d-abbf-91ab0087f905', 'd6082cdb-c9f1-51ac-afe6-529395dec6ad', '8137c62c-903a-56d2-a551-b536372afb63', 12, 29, 'ጌታዬ እግዚአብሔር ሆይ፥ አንተ ተናግረሃልና አሁን እንግዲህ ለዘለዓለም በፊትህ ይሆን ዘንድ የባሪያህን ቤት እባክህ ባርክ፤ በበረከትህም የባሪያህ ቤት ለዘለዓለም ይባረክ።”'),
  ('b728c265-0f8f-5afc-af11-2f5ef4c1f74a', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 1, 1, 'ከዚህም በኋላ ዳዊት ፍልስጥኤማውያንን መታ፤ አዋረዳቸውም፤ ዳዊትም ከፍልስጥኤማውያን እጅ ምርኮን ወሰደ።'),
  ('5de51c14-0154-58ad-a28f-500bf439fd4e', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 2, 2, 'ዳዊትም ሞዓባውያንን መታ፤ በምድርም ጥሎ በገመድ ሰፈራቸው፤ በሁለትም ገመድ ለሞት፥ በአንድም ገመድ ለሕይወት ሰፈራቸው፤ ሞዓባውያንም ለዳዊት ገባሮች ሆኑ፤ ግብርም አመጡለት።'),
  ('dd391c50-2d6d-5c17-ac95-19105dde4480', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 3, 3, 'ዳዊትም ደግሞ እስከ ኤፍራጥስ ወንዝ ግዛት ለማስፋፋት በሄደ ጊዜ የሱባን ንጉሥ የረአብን ልጅ አድርአዛርን መታ።'),
  ('1d43d34d-8344-519b-a3b7-d2fab64f1a9f', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 4, 4, 'ዳዊትም ከእርሱ ሺህ ሰረገላዎችን፥ ሰባት ሺህ ፈረሰኞችን፥ ሃያ ሺህም እግረኞችን ያዘ፤ ዳዊትም የሰረገለኛውን ፈረስ ሁሉ ቋንጃ ቈረጠ፤ ለራሱም መቶ ሰረገላዎችን ብቻ አስቀረ።'),
  ('39380de9-c4ea-5b0a-abff-62524ccd934a', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 5, 5, 'ከደማስቆም ሶርያውያን የሱባን ንጉሥ አድርአዛርን ሊረዱ መጡ፤ ዳዊትም ከሶርያውያን ሃያ ሁለት ሺህ ሰዎችን ገደለ።'),
  ('a323d823-4d84-547c-a96b-cbc4cb15c38f', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 6, 6, 'ዳዊትም በደማስቆ ሶርያ ጭፍሮች አኖረ፤ ሶርያውያንም ለዳዊት ገባሮች ሆኑ፤ ግብርም አመጡለት፤ እግዚአብሔርም ዳዊትን በሄደበት ሁሉ ጠበቀው።'),
  ('d23a2ba6-d9de-5c69-ad5a-e27bdd998486', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 7, 7, 'ዳዊትም ለሱባን ንጉሥ ለአድርአዛር አገልጋዮች የነበሩትን ጋሻ አግሬዎች ወሰደ፤ ወደ ኢየሩሳሌምም አመጣቸው። እነዚህንም የግብፅ ንጉሥ ሱስቀም በሰሎሞን ልጅ በሮብዓም ዘመን ወደ ኢየሩሳሌም በወጣ ጊዜ ወሰዳቸው።'),
  ('a946c863-3472-5b4d-a646-9c942196d6a5', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 8, 8, 'ንጉሡም ዳዊት ከሶቤቅና ከተመረጡት ከአድርአዛር ከተሞች እጅግ ብዙ ናስን ወሰደ። በእርሱም ሰሎሞን የብረት ባሕርና ምሰሶዎችን፥ ሰኖችንና ሌሎች ዕቃዎችን ሠራ።'),
  ('c2f24ad6-2570-5587-a75c-cc3fe9d9de28', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 9, 9, 'የሓማትም ንጉሥ ታይ ዳዊት የአድርአዛርን ጭፍራ ሁሉ እንደ መታ ሰማ።'),
  ('c86fd24b-f6c3-5137-a9d6-75fc7109b627', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 10, 10, 'ታይም የአድርአዛር ጠላት ነበርና ዳዊት አድርአዛርን ስለ ተዋጋውና ስለ ገደለው፥ ታይ ልጁን ኢያዱራን ደኅንነቱን ይጠይቅ ዘንድ፥ ይመርቀውም ዘንድ ወደ ንጉሥ ዳዊት ላከው፤ እርሱም የብርና የወርቅ የናስም ዕቃ ይዞ መጣ፤'),
  ('a2607aff-a8b4-5fc4-a9a6-861bfb76b766', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 11, 11, 'እርሱንም ንጉሥ ዳዊት ከሀገሮች ሁሉ አምጥቶ ከቀደሰው ከወርቁና ከብሩ ጋር ለእግዚአብሔር ቀደሰ፤'),
  ('057fbd56-09fa-50bf-a2df-bdc693d07213', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 12, 12, 'ይኸውም ከሶርያ ከሞዓብና ከአሞን ልጆች፥ ከፍልስጥኤማውያንም፥ ከአማሌቅም፥ ከረአብም ልጅ ከሱባ ንጉሥ ከአድርአዛር ምርኮ ያመጣው ነው።'),
  ('4c5cfebc-8868-5ffd-addf-70f1b07a0aa4', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 13, 13, 'ዳዊትም በተመለሰ ጊዜ ከኤዶምያስ ዐሥራ ስምንት ሺህ ሰዎች በጨው ሸለቆ ውስጥ በመምታቱ ስሙ ተጠራ።'),
  ('fbff1825-2622-5f34-a131-1380eb693604', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 14, 14, 'መላዋን ኤዶምያስን ይጠብቁ ዘንድ በኤዶምያስ ሁሉ ጭፍሮችን አኖረ፤ ኤዶማውያንም ሁሉ ለንጉሥ ዳዊት ገባሮች ሆኑ፤ እግዚአብሔርም ዳዊትን በሚሄድበት ቦታ ሁሉ ጠበቀው።'),
  ('a0bcce87-4488-5ed2-aa2a-450a911de579', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 15, 15, 'ዳዊትም በእስራኤል ሁሉ ላይ ነገሠ፤ ዳዊትም ለሕዝቡ ሁሉ ፍርድንና ጽድቅን አደረገላቸው።'),
  ('2f5774a2-6683-5aca-aca1-601abb775682', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 16, 16, 'የሦርህያ ልጅ ኢዮአብም የሠራዊት አለቃ ነበረ፤ የአሒሎድም ልጅ ኢዮሣፍጥ ታሪክ ጸሓፊ ነበረ፤'),
  ('5003af15-9091-5dde-a0d6-0830df71a9b3', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 17, 17, 'የአኪጦብም ልጅ ሳዶቅ፥ የአቤሜሌክም ልጅ አብያታር ካህናት ነበሩ። አሳም ጸሓፊ ነበረ፤'),
  ('9c678284-307a-5858-a702-8510b3d2ff26', '12603a35-5360-541f-aa29-8ed25b73826a', 'ed4ec7e3-a927-59e0-acba-f5b6f85089fd', 18, 18, 'የዮዳሄ ልጅ በናያስም አማካሪ ነበረ፤ ከሊታውያንና፥ ፊሊታውያን፥ የዳዊትም ልጆች የፍርድ ቤት አለቆች ነበሩ።'),
  ('46809715-0bfb-5b38-aa2b-f553845ad7b5', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 1, 1, 'ዳዊትም፥ “ስለ ዮናታን ቸርነት አደርግለት ዘንድ ከሳኦል ቤት የቀረ አንድ ሰው አለን?” አለ።'),
  ('a1bc25ff-6676-5a58-a3f3-cea50825255f', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 2, 2, 'ከሳኦልም ቤት አንድ ብላቴና ነበረ፤ ስሙም ሲባ ነበረ፤ ወደ ዳዊትም ጠሩት፤ ንጉሡም፥ “አንተ ሲባ ነህን?” አለው። እርሱም፥ “እኔ አገልጋይህ ነኝ” አለ።'),
  ('70053983-e994-5533-a87c-cd6ddfa6e6c1', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 3, 3, 'ንጉሡም፥ “የእግዚአብሔርን ቸርነት አደርግለት ዘንድ ከሳኦል ቤት የቀረ ሰው አለን?” አለ። ሲባም ንጉሡን፥ “እግሮቹ ሽባ የሆኑ አንድ የዮናታን ልጅ አለ” አለው።'),
  ('a9672f67-38d5-5547-a3f7-935992170019', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 4, 4, 'ንጉሡም፥ “ወዴት ነው?” አለው፤ ሲባም ለንጉሡ፥ “እነሆ እርሱ በሎዶባር በአብያል ልጅ በማኪር ቤት አለ” አለው።'),
  ('0f5d3612-2e41-5d46-a94b-e5736c3ba771', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 5, 5, 'ንጉሡም ዳዊት ልኮ ከሎዶባር ከአብያል ልጅ ከማኪር ቤት አስመጣው።'),
  ('ea6638fa-be2a-5a6e-a5a5-786b32f9dacc', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 6, 6, 'የሳኦልም ልጅ የዮናታን ልጅ ሜምፌቡስቴ ወደ ዳዊት መጣ፤ በግንባሩም ወድቆ ሰገደለት፤ ንጉሥ ዳዊትም፥ “ሜምፌቡስቴ ሆይ፥” አለ፤ እርሱም፥ “እነሆኝ አገልጋይህ” አለ።'),
  ('1b42b95c-8496-588c-a5ff-469384e9f60f', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 7, 7, 'ዳዊትም፥ “ስለ አባትህ ስለ ዮናታን ቸርነት ፈጽሜ አደርግልሃለሁና አትፍራ፤ የአባትህን አባት የሳኦልን መሬት ሁሉ እመልስልሃለሁ፤ አንተም ሁል ጊዜ ከገበታዬ እንጀራን ትበላለህ” አለው።'),
  ('7ab30bef-3afd-5e9f-a7a1-03147580e61f', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 8, 8, 'እርሱም፥ “የሞተ ውሻ ወደምመስል ወደ እኔ ትመለከት ዘንድ እኔ አገልጋይህ ምንድን ነኝ?” ብሎ ሰገደ።'),
  ('05a9504c-7f89-5d41-a5f2-36f31e879cb2', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 9, 9, 'ንጉሡም የሳኦልን አገልጋይ ሲባን ጠርቶ፥ “ለሳኦልና ለቤቱ ሁሉ የነበረውን ሁሉ ለጌታህ ልጅ ሰጥቻለሁ።'),
  ('21918ebb-473b-50cc-a938-26fde5134a85', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 10, 10, 'አንተና ልጆችህ፥ ሎሌዎችህም ምድሩን እረሱለት፤ ለጌታህም ልጅ እንጀራ ይሆነው ዘንድ ፍሬውን አግቡ፤ እናንተም ትመግቡታላችሁ፤የጌታህ ልጅ ሜምፌቡስቴ ግን ሁልጊዜ ከገበታዬ ይበላል” አለው። ለሲባም ዐሥራ አምስት ልጆችና ሃያ አገልጋዮች ነበሩት።'),
  ('bb24ac9c-11bd-548c-abb3-7c64a620554b', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 11, 11, 'ሲባም ንጉሡን፥ “ጌታዬ ንጉሡ አገልጋዩን እንዳዘዘ እንዲሁ አገልጋይህ ያደርጋል” አለው። ሜምፌቡስቴም ከንጉሡ ልጆች እንደ አንዱ ከዳዊት ገበታ ይበላ ነበር።'),
  ('5ebcbcf9-a769-52bf-a563-0f8f000a7937', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 12, 12, 'ለሜምፌቡስቴም ሚካ የተባለ ታናሽ ልጅ ነበረው፤ በሲባም ቤት ያሉ ሁሉ ለሜምፌቡስቴ ያገለግሉ ነበር።'),
  ('59837aa1-47af-5cd3-adf1-89983551e60a', '9e9ad670-4287-548c-a77d-043a8db4d697', 'c9682f30-d1cd-5a44-a740-476d7bdeb6ef', 13, 13, 'ሜምፌቡስቴም ከንጉሥ ገበታ ሁልጊዜ እየበላ በኢየሩሳሌም ኖረ፤ ሁለት እግሮቹም ሽባ ነበሩ።'),
  ('432a0cc6-2217-5ae5-ac84-7a65d8e5efcc', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 1, 1, 'ከዚህ በኋላ የአሞን ልጆች ንጉሥ ሞተ፤ ልጁም ሐኖን በፋንታው ነገሠ።'),
  ('615c6e9a-c8cf-5fa1-a941-68a443d88a9d', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 2, 2, 'ዳዊትም፥ “አባቱ ቸርነትን እንዳደረገልኝ እኔ ለናዖስ ልጅ ለሐኖን ቸርነት አደርጋለሁ” አለ። ዳዊትም ስለ አባቱ ያጽናኑት ዘንድ ብላቴኖቹን ላከ፤ የዳዊትም ብላቴኖች ወደ አሞን ልጆች ሀገር መጡ።'),
  ('0a415ada-db0d-599f-ace5-3bf943d673ae', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 3, 3, 'የአሞንም ልጆች አለቆች ጌታቸውን ሐኖንን፥ “ዳዊት አባትህን በፊትህ ለማክበር አጽናኞችን ወደ አንተ የላከ ይመስልሃልን? ዳዊትስ ከተማዪቱን ለመመርመርና ለመሰለል፥ ለመፈተንም አገልጋዮቹን የላከ አይደለምን?” አሉት።'),
  ('ee14cabe-a43e-5bb9-aa95-0e3a89db86b5', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 4, 4, 'ሐኖንም የዳዊትን አገልጋዮች ወስዶ የጢማቸውን ገሚስ ላጨ፤ ልብሳቸውንም እስከ ወገባቸው ድረስ ከሁለት ቀድዶ ሰደዳቸው።'),
  ('ea5ce2a4-dd89-5416-a6b2-5d714f6950d6', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 5, 5, 'ለዳዊትም ስለ ሰዎቹ ነገሩት፤ ሰዎቹ እጅግ አፍረው ነበሩና ተቀባዮችን ላከ። ንጉሡም፥ “ጢማችሁ እስኪያድግ ድረስ በኢያሪኮ ተቀመጡ፤ ከዚያም በኋላ ተመለሱ” አላቸው።'),
  ('7890a409-4fc6-516a-a934-4b683bb8e7bc', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 6, 6, 'የአሞንም ልጆች የዳዊት ወገኖች እንደ አፈሩ ባዩ ጊዜ፥ የአሞን ልጆች ልከው ከቤትሮዖብ ሶርያውያንና ከሱባ ሶርያውያን ሃያ ሺህ እግረኞችን፥ ከአማሌቅ ንጉሥም አንድ ሺህ ሰዎችን፥ ከአስጦብም ዐሥራ ሁለት ሺህ ሰዎችን ቀጠሩ።'),
  ('e905ab70-af13-5df0-a52d-0368a715e611', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 7, 7, 'ዳዊትም በሰማ ጊዜ ኢዮአብንና የኀያላኑን ሰራዊት ሁሉ ላከ።'),
  ('7e5b01ff-0205-585c-a1a2-ab58b6135138', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 8, 8, 'የአሞንም ልጆች ወጥተው በበሩ መግቢያ ፊት ለፊት ይዋጉ ጀመሩ፤ የሱባና የሮዖብ ሶርያውያን፥ የአስጦብና የአማሌቅም ሰዎች ለብቻቸው በሰፊ ሜዳ ላይ ነበሩ።'),
  ('eaae07fe-ffd7-52fa-a089-fcdd0ec721aa', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 9, 9, 'ኢዮአብም በፊትና በኋላ ሰልፍ እንደ ከበበው ባየ ጊዜ ከእስራኤል ጐልማሶችን ሁሉ መረጠ፤ በሶርያውያንም ፊት አሰለፋቸው።'),
  ('5424770a-158e-56a2-a764-419115ac3a15', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 10, 10, 'የቀረውንም ሕዝብ ከወንድሙ ከአቢሳ ጋር ላከ፤ በአሞን ልጆች ፊትም አሰለፋቸው።'),
  ('07161c65-74e0-5955-a39c-7889cdd6a71b', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 11, 11, 'እርሱም አለው፥ “ሶርያውያን ቢበረቱብኝ ትረዳኛለህ፤ የአሞን ልጆችም ቢበረቱብህ እኔ መጥቼ እረዳሃለሁ።'),
  ('8831e4a2-6211-5136-a88e-08ab90c77659', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 12, 12, 'በርታ፤ ስለ ሕዝባችንና ስለ አምላካችንም ከተሞች እንጽና፤ እግዚአብሔርም በዐይኑ ፊት ደስ ያሰኘውን መልካሙን ያድርግ።”'),
  ('c9f9e355-14e1-5a69-a795-c404cd882497', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 13, 13, 'ኢዮአብና ከእርሱም ጋር የነበረው ሕዝብ ከሶርያውያን ጋር ሊዋጉ ቀረቡ፤ እነርሱም ከፊቱ ሸሹ።'),
  ('7ebaa501-a90e-581b-ad91-87aa112d110b', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 14, 14, 'የአሞን ልጆችም ሶርያውያን እንደ ሸሹ ባዩ ጊዜ እነርሱ ደግሞ ከአቢሳ ፊት ሸሹ፤ ወደ ከተማዪቱም ገቡ፤ ኢዮአብም ከአሞን ልጆች ዘንድ ተመልሶ ወደ ኢየሩሳሌም ገባ።'),
  ('8d1a6368-3653-5c95-a97a-08e2966d9240', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 15, 15, 'ሶርያውያንም በእስራኤል ፊት እንደ ተሸነፉ ባዩ ጊዜ በአንድነት ተሰበሰቡ።'),
  ('0fd8eb71-511e-59b9-aa9e-5bc94096f0c3', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 16, 16, 'አድርአዛርም ልኮ በካላማቅ ወንዝ ማዶ የነበሩትን ሶርያውያን ሰበሰባቸው፤ ወደ ኤላምም መጡ፤ የአድርአዛርም ሠራዊት አለቃ ሶቤቅ በፊታቸው ነበረ።'),
  ('0c87bc4e-d178-5b1f-a5d6-db2829555598', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 17, 17, 'ለዳዊትም ነገሩት፤ እስራኤልንም ሁሉ ሰበሰበ፤ ዮርዳኖስንም ተሻግሮ ወደ ኤላም መጣ፤ ሶርያውያንም በዳዊት ፊት ተሰልፈው ከእርሱ ጋር ተዋጉ።'),
  ('818fc653-0572-5a56-a0ac-246abd641036', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 18, 18, 'ሶርያውያንም ከእስራኤል ፊት ሸሹ፤ ዳዊትም ከሶርያውያን ሰባት መቶ ሰረገለኞችን፥ አርባ ሺህም ፈረሰኞችን ገደለ፤ የሠራዊቱንም አለቃ ሶቤቅን መታ፤ እርሱም በዚያ ሞተ።'),
  ('82326622-3a95-5762-ab82-75560631a8c9', '24235cc2-300e-5180-a1f8-8227609ea2c4', '6024d86b-e86b-58f3-af8a-420866334bc1', 19, 19, 'ለአድርአዛርም የሚገብሩ ነገሥታት ሁሉ በእስራኤል ፊት እንደ ተሸነፉ ባዩ ጊዜ ለእስራኤል ተገዙ፤ ገበሩላቸውም። ሶርያውያንም ከዚያ ወዲያ የአሞንን ልጆች ይረዱ ዘንድ ፈሩ።'),
  ('99e1ae74-75f4-5376-a781-b13e5744b81d', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 1, 1, 'እንዲህም ሆነ፤ በዓመቱ መጨረሻ ነገሥታት ወደ ሰልፍ በሚወጡበት ጊዜ፥ ዳዊት ኢዮአብን ከእርሱም ጋር አገልጋዮቹን፥ እስራኤልንም ሁሉ ሰደደ። የአሞንንም ልጆች አጠፉ፤ አራቦትንም ከበቡ፤ ዳዊት ግን በኢየሩሳሌም ቀርቶ ነበር።'),
  ('36406a66-80b0-50aa-af49-9b06d9d9b998', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 2, 2, 'እንዲህም ሆነ፤ ወደ ማታ ጊዜ ዳዊት ከምንጣፉ ተነሣ፤ በንጉሥም ቤት በሰገነት ላይ ተመላለሰ፤ በሰገነቱም ሳለ አንዲት ሴት ስትታጠብ አየ፤ ሴቲቱም እጅግ የተዋበች መልከ መልካም ነበረች።'),
  ('7942aa78-c424-5587-a2d8-abe05829472e', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 3, 3, 'ዳዊትም ልኮ ስለ ሴቲቱ ጠየቀ፤ አንድ ሰውም፥ “የኤልያብ ልጅ የኬጤያዊው የኦርዮ ሚስት ቤርሳቤህ አይደለችምን?” አለው።'),
  ('c236453e-e240-52d9-a6dd-f13d746b7688', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 4, 4, 'ዳዊትም መልእክተኞችን ልኮ አስመጣት፤ ወደ እርሱም ገባች፤ ከርኵሰቷም ነጽታ ነበርና ከእርስዋ ጋር ተኛ፤ ወደ ቤቷም ተመለሰች።'),
  ('496699c6-13ab-5598-a622-da5209f2e531', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 5, 5, 'ሴቲቱም አረገዘች፤ ወደ ዳዊትም “አርግዤአለሁ” ብላ ላከችበት።'),
  ('57055cf8-f40f-537f-a6f1-e8db886dd350', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 6, 6, 'ዳዊትም ወደ ኢዮአብ፦ ኬጤያዊውን ኦርዮን ወዲህ ላከው ብሎ ላከ። ኢዮአብም ኦርዮን ወደ ዳዊት ላከው።'),
  ('7f180d14-b3ca-5235-acf4-c53d17aefd91', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 7, 7, 'ኦርዮም ደርሶ ወደ እርሱ በገባ ጊዜ ዳዊት የኢዮአብንና የሕዝቡን ደኅንነት፥ ሰልፉም እንዴት እንደ ሆነ ጠየቀው።'),
  ('87b41564-b361-5216-a62f-6bb0e0e083f2', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 8, 8, 'ዳዊትም ኦርዮን፥ “ወደ ቤትህ ሂድ፤ እግርህንም ታጠብ” አለው። ኦርዮም ከንጉሡ ቤት ሲወጣ አንድ የንጉሥ መልእክተኛ ተከተለው።'),
  ('f4b7fd88-9c0f-5bb5-abac-bcc0dccb1974', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 9, 9, 'ኦርዮ ግን ከጌታው አገልጋዮች ሁሉ ጋር በንጉሥ ቤት ደጅ ተኛ፤ ወደ ቤቱም አልወረደም።'),
  ('bb3884b4-626a-577e-a521-0761110e8767', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 10, 10, '“ኦርዮ ወደ ቤቱ አልሄደም” ብለው ለዳዊት ነገሩት፤ ዳዊትም ኦርዮን፥ “አንተ ከመንገድ የመጣህ አይደለህምን? ስለምን ወደ ቤትህ አልወረድህም?” አለው።'),
  ('0394fa2c-a87e-514c-ad3b-6f1dcdea07a2', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 11, 11, 'ኦርዮም ለዳዊት፥ “የእግዚአብሔር ታቦትና እስራኤል፥ ይሁዳም በድንኳን ተቀምጠዋል፤ ጌታዬ ኢዮአብና የጌታዬም አገልጋዮች በሰፊ ሜዳ ሰፍረዋል፤ እኔ ልበላና ልጠጣ ወይስ ከሚስቴ ጋር ልተኛ ወደ ቤቴ እሄዳለሁን? በሕይወትህና በሕያው ነፍስህ እምላለሁ! ይህን ነገር አላደርገውም” አለው።'),
  ('1a992ee2-2e20-56b2-a2c7-e91dcd54c99d', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 12, 12, 'ዳዊትም ኦርዮን፥ “ዛሬ ደግሞ በዚህ ተቀመጥ፤ ነገም አሰናብትሃለሁ” አለው። ኦርዮም በዚያ ቀንና በነጋው በኢየሩሳሌም ተቀመጠ።'),
  ('340bb1e7-3ec2-5ea0-af94-4e69f861655f', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 13, 13, 'ዳዊትም ጠራው፤ በፊቱም በላና ጠጣ፤ አሰከረውም፤ ነገር ግን በመሸ ጊዜ ወጥቶ ከጌታው አገልጋዮች ጋር በምንጣፉ ላይ ተኛ፤ ወደ ቤቱም አልወረደም።'),
  ('dee5c5c1-6707-5881-ad52-b684dc150b02', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 14, 14, 'በነጋም ጊዜ ዳዊት ለኢዮአብ ደብዳቤ ጻፈ፤ በኦርዮም እጅ ላከው።'),
  ('b162e595-1201-54e0-aeb3-d89d2fc8076a', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 15, 15, 'በደብዳቤውም፥ “ኦርዮን ጽኑ ሰልፍ ባለበት በፊተኛው ስፍራ አቁሙት፤ ተወግቶም ይሞት ዘንድ ከኋላ ሽሹ” ብሎ ጻፈ።'),
  ('1282920f-173b-5031-af23-a46a9e8b3435', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 16, 16, 'ኢዮአብም ከተማዪቱን በከበበ ጊዜ ጀግኖች እንዳሉበት በሚያውቀው ስፍራ ኦርዮን አቆመው።'),
  ('5e6d16b1-8022-5331-a30c-10579501ccc6', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 17, 17, 'የከተማዪቱም ሰዎች ወጥተው ከኢዮአብ ጋር ተዋጉ፤ ከዳዊትም አገልጋዮች ከሕዝቡ አንዳንዱ ወደቁ፤ ኬጤያዊው ኦርዮም ደግሞ ሞተ።'),
  ('ee8d52ce-0352-509f-ac52-eb6d3be860f9', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 18, 18, 'ኢዮአብም የጦርነቱን ዜና ሁሉ ለዳዊት ይነግሩት ዘንድ ላከ፤'),
  ('9bd0760b-c3ed-5c69-a10d-15dd2f1580da', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 19, 19, 'ለመልእክተኛውም እንዲህ ብሎ አዘዘው፥ “የጦርነቱን ነገር ሁሉ ለንጉሡ ነግረህ በፈጸምህ ጊዜ፤'),
  ('a7e372c7-0367-5137-a2c4-0d43d13bd00f', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 20, 20, 'ንጉሡ ቢቈጣ፥ እንዲህም ቢል፦ ልትዋጉ ወደ ከተማዪቱ ለምን ቀረባችሁ? ከቅጥሩ በላይ ፍላጻ እንዲወረወር አታውቁምን?'),
  ('b34b674a-6dff-5505-a8c3-600d19c5a489', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 21, 21, 'የኔር ልጅ የይሩበዓልን ልጅ አቤሜሌክን ማን ገደለው? አንዲት ሴት ከቅጥር ላይ የወፍጮ መጅ ጥላበት የሞተ አይደለምን? ስለምን ወደ ቅጥሩ እንደዚህ ቀረባችሁ? አንተም፦ ባሪያህ ኬጤያዊው ኦርዮ ደግሞ ሞተ በለው።”'),
  ('ee35c6b1-f66b-5639-a7bc-f950cfdeb79a', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 22, 22, 'የኢዮአብም መልእክተኛ ወደ ኢየሩሳሌም ወደ ንጉሡ ሄደ። ደርሶም ኢዮአብ የነገረውን የጦርነቱን ዜና ሁሉ ለዳዊት ነገረው። ዳዊትም በኢዮአብ ላይ ተቈጣ። ያንም መልእክተኛ፥ “ትዋጉ ዘንድ ወደ ከተማዋ ቅጥር ለምን ቀረባችሁ? በቅጥሩም እንደምትቈስሉ አታውቁምን? የይሩበዓል ልጅ አቤሜሌክን ማን ገደለው? አንዲት ሴት ከቅጥር ላይ የወፍጮ መጅ ጥላበት በቴቤስ የሞተ አይደለምን? ስለምን ወደ ቅጥሩ ቀረባችሁ?” አለው።'),
  ('30375ad5-7b9e-5fbb-ae28-083c0496594f', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 23, 23, 'መልእክተኛውም ዳዊትን፥ “ሰዎቹ በረቱብን፤ ወደ ሜዳም ወጡብን፤ እኛም እስከ በሩ መግቢያ ድረስ አሳደድናቸው።'),
  ('35ae00c4-a54c-59aa-ab9b-0bf7fe9b35b1', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 24, 24, 'ፍላጻም የሚወረውሩ በቅጥሩ ላይ ሆነው በአገልጋዮችህ ላይ ወረወሩ፤ ከንጉሡም ብላቴኖች አንዳንድ ሞቱ፤ አገልጋይህ ኬጤያዊው ኦርዮ ደግሞ ሞተ” አለው።'),
  ('aa7d86d6-c686-5f21-a903-d3893a12d4f6', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 25, 25, 'ዳዊትም መልእክተኛውን፥ “ሰይፍ አንድ ጊዜ ይህን፥ አንድ ጊዜም ያን ይበላልና ይህ ነገር በዐይንህ አይክፋ፤ ከተማዪቱን የሚወጉትን አበርታ፤ አፍርሳትም ብለህ ለኢዮአብ ንገረው፤ አንተም አጽናው” አለው።'),
  ('b99e53df-ca1f-552e-a66a-5fa8d8cfd9cf', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 26, 26, 'የኦርዮም ሚስት ባልዋ ኦርዮ እንደ ሞተ በሰማች ጊዜ ለባልዋ አለቀሰች።'),
  ('2f3da9bb-c0c7-5924-aaea-25d07df528b7', '1ca4d290-e65a-516f-a3d9-bfeafc6a7faa', 'ce92991c-9c3b-5249-a1ef-dd6119cee658', 27, 27, 'የልቅሶዋም ወራት ሲፈጸም ዳዊት ልኮ ወደ ቤቱ አስመጣት፤ ሚስትም ሆነችው፤ ወንድ ልጅም ወለደችለት፤ ነገር ግን ዳዊት ያደረገው ነገር ሁሉ በእግዚአብሔር ፊት ክፉ ሆነ።'),
  ('5507f5f3-5cb0-51ba-aeb2-62a39b6e8b64', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 1, 1, 'እግዚአብሔርም ነቢዩ ናታንን ወደ ዳዊት ላከ፤ ወደ እርሱም መጥቶ አለው፥ “በአንድ ከተማ አንዱ ባለጠጋ፥ አንዱም ድሃ የሆኑ ሁለት ሰዎች ነበሩ።'),
  ('5b1fb302-bc9e-5ffb-a4f4-3cabbbeaa92a', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 2, 2, 'ባለጠጋውም እጅግ ብዙ የበግና የላም መንጋ ነበረው።'),
  ('ca26dd4e-65c7-544d-a2ba-2c6124a4d2ab', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 3, 3, 'ለድሃው ግን ከገዛት አንዲት ታናሽ በግ በቀር አንዳች አልነበረውም፤ አሳደጋትም፤ ተንከባከባትም፤ ከእርሱና ከልጆቹ ጋር አደገች፤ ከእንጀራውም ትበላ፥ ከዋንጫውም ትጠጣ፥ በብብቱም ትተኛ ነበረ፤ እንደ ልጁም ነበረች።'),
  ('62f1c9a9-12be-57f2-a863-ac479396c33c', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 4, 4, 'ወደ ባለጠጋውም እንግዳ በመጣ ጊዜ ከበጉና ከላሙ ወስዶ ለዚያ ወደ እርሱ ለመጣው እንግዳ ያዘጋጅለት ዘንድ ሳሳ፤ የዚያንም የድሃውን ሰው በግ ወስዶ ለዚያ ለመጣው ሰው አዘጋጀ።'),
  ('a279c4c0-6cd2-5c2b-a0c2-042556e1aa22', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 5, 5, 'ዳዊትም በዚያ ሰው ላይ ተቈጣ፤ ዳዊትም ናታንን፥ “ሕያው እግዚአብሔርን! ይህን ያደረገ ሰው ሞት የሚገባው ነው።'),
  ('67719a08-d44f-5f82-a8b1-e0f796e3f578', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 6, 6, 'ይህን አድርጎአልና፥ አላዘነምና ስለ አንዲቱ በግ አራት አድርጎ ይመልስ” አለው።'),
  ('468f7704-d2cc-5aff-a446-9375ca2e9040', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 7, 7, 'ናታንም ዳዊትን አለው፥ “ይህን ያደረገ ያ ሰው አንተ ነህ፤ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ በእስራኤል ላይ ንጉሥ ልትሆን ቀባሁህ፤ ከሳኦልም እጅ አዳንሁህ፤'),
  ('8fde3581-7027-5410-a36b-8fcd108ef620', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 8, 8, 'የጌታህንም ቤት ሰጠሁህ፤ የጌታህንም ሚስቶች በብብትህ ጣልሁልህ፤ የእስራኤልንና የይሁዳን ቤት ሰጠሁህ፤ ይህም አንሶ ቢሆን ኖሮ ከዚህ የበለጠ እጨምርልህ ነበር።'),
  ('d71ec888-5cb1-5345-a887-59aa82826f55', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 9, 9, 'አሁንስ በፊቱ ክፉ ትሠራ ዘንድ የእግዚአብሔርን ነገር ለምን አቃለልህ? ኬጤያዊውን ኦርዮን በሰይፍ መትተሃል፤ ሚስቱንም ለአንተ ሚስት ትሆን ዘንድ ወስደሃል፤ እርሱንም በአሞን ልጆች ሰይፍ ገድለሃል።'),
  ('6bfa4fa0-c591-5c50-a94a-b0079e45d584', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 10, 10, 'ስለዚህም አቃልለኸኛልና፥ የኬጤያዊውንም የኦርዮን ሚስት ለአንተ ሚስት ትሆን ዘንድ ወስደሃልና ለዘለዓለም ከቤትህ ሰይፍ አይርቅም።'),
  ('59e09d9d-a3aa-5494-a9ee-1a61bb40adf0', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 11, 11, 'እግዚአብሔር እንዲህ ይላል፦ እነሆ ከቤትህ ክፉ ነገርን አስነሣብሃለሁ፤ ሚስቶችህንም በዐይኖችህ እያየህ እወስዳለሁ፤ ለዘመድህም እሰጣቸዋለሁ፤ በዚችም ፀሐይ ፊት ከሚስቶችህ ጋር ይተኛል።'),
  ('ddf1a675-4dcf-5c72-aa04-9ee6dfe0ffcd', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 12, 12, 'አንተ ይህን በስውር አድርገኸዋል፤ እኔ ግን ይህን በእስራኤል ሁሉ ፊትና በፀሐይ ፊት አደርገዋለሁ።”')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('31ec17e9-62fa-5792-a865-0d6a93b06df6', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 13, 13, 'ዳዊትም ናታንን፥ “እግዚአብሔርን በድያለሁ” አለው። ናታንም ዳዊትን አለው፥ “እግዚአብሔር ደግሞ ኀጢአትህን አርቆልሃል፤ አትሞትምም።'),
  ('d20524ec-e463-5b23-ab8f-635d1ba44852', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 14, 14, 'ነገር ግን በዚህ ነገር ለእግዚአብሔር ጠላቶች መነሣሣት ምክንያት አድርገሃልና ስለዚህ ደግሞ የተወለደልህ ልጅ ፈጽሞ ይሞታል” አለው።'),
  ('8c45b18b-47fc-59d5-aa5a-03cca9897124', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 15, 15, 'ናታንም ወደ ቤቱ ተመለሰ።'),
  ('a4cb6eaf-6c71-5b61-a2ad-db9fe826c159', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 16, 16, 'ዳዊትም ስለ ሕፃኑ እግዚአሔርን ለመነ፤ ዳዊትም ጾመ፤ ገብቶም በመሬት ላይ ተኛ።'),
  ('f135cb2d-35a8-54d7-a924-c3bdddf0e4b2', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 17, 17, 'የቤቱም ሽማግሌዎች ተነሥተው ከምድር ያነሡት ዘንድ በአጠገቡ ቆሙ፤ እርሱ ግን እንቢ አለ፤ ከእነርሱም ጋር እንጀራ አልበላም።'),
  ('9d7bdf00-75a1-57d1-af78-a828eec052bb', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 18, 18, 'በሰባተኛውም ቀን ሕፃኑ ሞተ። የዳዊትም ብላቴኖች፥ “ሕፃኑ በሕይወት ሳለ ብንነግረው አልሰማንም፤ ይልቁንስ ሕፃኑ እንደ ሞተ ብንነግረው እንዴት ይሆን? በራሱ ላይ ክፉ ያደርጋል” ብለው ሕፃኑ እንደ ሞተ ይነግሩት ዘንድ ፈሩ።'),
  ('5582bec1-de8b-52e9-a348-b8f26081914e', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 19, 19, 'ዳዊትም ብላቴኖቹ በሹክሹክታ ሲነጋገሩ ባየ ጊዜ ዳዊት ሕፃኑ እንደ ሞተ ዐወቀ፤ ዳዊትም ብላቴኖቹን፥ “ሕፃኑ ሞቶአል?” አላቸው። እነርሱም፥ “ሞቶአል” አሉት።'),
  ('4bb34c5a-6f8a-5918-aeb2-00269a704a98', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 20, 20, 'ዳዊትም ከምድር ተነሥቶ ታጠበ፤ ተቀባም፤ ልብሱንም ለወጠ፤ ወደ እግዚአብሔርም ቤት ገብቶ ሰገደ። ወደ ቤቱም መጣ፦ እንጀራም አምጡልኝ አለ፤ በፊቱም እንጀራ አቀረቡለት፤ በላም።'),
  ('1262a0ba-12ac-5727-a858-af9d4142d60d', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 21, 21, 'ብላቴኖቹም፥ “ይህ ስለ ሕፃኑ ያደረግኸው ነገር ምንድን ነው? እርሱ በሕይወት ሳለ ጾምህና አለቀስህ፤ እንቅልፍም አጣህ፤ ሕፃኑ ከሞተ በኋላ ግን ተነሥተህ እንጀራ በላህ፤ ጠጣህም” አሉት።'),
  ('70cae2a8-e9c0-5ea2-ab7c-d8328865a13a', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 22, 22, 'ዳዊትም፥ “ሕፃኑ ሕያው ሳለ፤ ምናልባት እግዚአብሔር ይምረኝ፥ ሕፃኑም በሕይወት ይኖር እንደ ሆነ ማን ያውቃል? ብዬ ጾምሁ፤ አለቀስሁም።'),
  ('9c9b9526-f221-51ce-abbc-dadd5d9f87d5', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 23, 23, 'አሁን ግን ሞቶአል፤ የምጾመው ስለ ምንድን ነው? በውኑ እንግዲህ እመልሰው ዘንድ ይቻለኛልን? እኔ ወደ እርሱ እሄዳለሁ እንጂ እርሱ ወደ እኔ አይመለስም” አለ።'),
  ('0737a0fa-d5ff-5128-a2d2-9dc17596ba38', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 24, 24, 'ዳዊትም ሚስቱን ቤርሳቤህን አጽናናት፤ ወደ እርስዋም ገባ፤ ከእርስዋም ጋር ተኛ፤ ፀነሰችም፤ ወንድ ልጅም ወለደች፤ ስሙንም ሰሎሞን ብሎ ጠራው። እግዚአብሔርም ወደደው።'),
  ('45f492ac-f959-5101-a0be-349b8a22dc4d', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '18edcfa8-9f9d-55e6-a615-77b1da6bbcb7', 25, 25, 'ደግሞም በነቢዩ በናታን እጅ ልኮ ስሙን ስለ እግዚአብሔር ፍቁረ እግዚአብሔር ብሎ ጠራው።'),
  ('793b3f55-5eac-5420-a1ea-5dc17f41b8de', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '179758c0-a236-5ca5-aab0-48e6c1ed1b21', 1, 26, 'ኢዮአብም የአሞንን ልጆች ከተማ ራባትን ወጋ፤ የመንግሥታቸውንም ከተማ ያዘ።'),
  ('d4c6a225-d286-5e86-a0ee-70576a5e2cbe', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '179758c0-a236-5ca5-aab0-48e6c1ed1b21', 2, 27, 'ኢዮአብም ወደ ዳዊት እንዲህ ብሎ መልእክተኞችን ላከ፥ “ራባትን ወግቻለሁ፤ የውኃውንም ከተማ ይዤአለሁ።'),
  ('be811233-074a-5cca-a356-db1d0c056e99', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '179758c0-a236-5ca5-aab0-48e6c1ed1b21', 3, 28, 'አሁንም ከተማዪቱን እኔ ቀድሜ እንዳልይዝ፥ በስሜም እንዳትጠራ፥ የቀረውን ሕዝብ ሰብስብ፥ ከተማዪቱንም ከብበህ ቀድመህ ያዛት።”'),
  ('56f54c58-4a48-544f-a423-ad3ce6482385', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '179758c0-a236-5ca5-aab0-48e6c1ed1b21', 4, 29, 'ዳዊትም ሕዝቡን ሁሉ ሰብስቦ ወደ ራባት ሄደ፤ ወግቶም ያዛት።'),
  ('1518b49f-e4ac-54a9-a8bd-eadd079787df', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '179758c0-a236-5ca5-aab0-48e6c1ed1b21', 5, 30, 'የንጉሣቸውንም የሜልኮምን ዘውድ ከራሱ ላይ ወሰደ። ክብደቱም አንድ መክሊት ወርቅ ያህል ነበር፤ ክቡር ዕንቍም ነበረበት፤ ዳዊትም በራሱ ላይ አደረገው። ከከተማዪቱም እጅግ ብዙ ምርኮ አወጣ።'),
  ('e1e9a2a4-5fdb-5a3e-af73-1bffccad84f0', 'ba64542f-829f-5f0f-aa03-574cafedbaa1', '179758c0-a236-5ca5-aab0-48e6c1ed1b21', 6, 31, 'በውስጥዋም የነበሩትን ሕዝብ አውጥቶ በመጋዝና በብረት መቈፈሪያ በብረት መጥረቢያም ሥር አኖራቸው፤ በሸክላ ጡብ እቶንም አሳለፋቸው። በአሞን ልጆች ከተሞች ሁሉ እንዲሁ አደረገ። ዳዊትም፥ ሕዝቡም ሁሉ ወደ ኢየሩሳሌም ተመለሱ።'),
  ('9a72276f-9ee1-5ec4-ae09-12fa028297aa', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 1, 1, 'ከዚህም በኋላ እንዲህ ሆነ፤ ለዳዊት ልጅ ለአቤሴሎም አንዲት የተዋበች እኅት ነበረችው፤ ስምዋም ትዕማር ነበረ፤ የዳዊትም ልጅ አምኖን ወደዳት።'),
  ('cd65041c-652d-5ff1-aa4e-4b82aac11db1', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 2, 2, 'አምኖንም ከእኅቱ ከትዕማር የተነሣ እስከሚታመም ድረስ እጅግ ተከዘ፤ ድንግልም ነበረችና አንዳች ነገር ያደርግባት ዘንድ በዐይኑ ፊት ጭንቅ ሆኖበት ነበር።'),
  ('29814841-a981-5abb-aafa-fbec0ba6d061', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 3, 3, 'ለአምኖንም የዳዊት ወንድም የሳምዓ ልጅ ኢዮናዳብ የሚባል ወዳጅ ነበረው፤ ኢዮናዳብም እጅግ ብልህ ሰው ነበረ።'),
  ('1c96541b-cdb9-5f7f-ae7a-1c78e28cc859', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 4, 4, 'እርሱም፥ “የንጉሥ ልጅ ሆይ፥ ስለምን በየቀኑ እንዲህ ከሳህ? አትነግረኝምን?” አለው። አምኖንም፥ “የወንድሜን የአቤሴሎምን እኅት ትዕማርን እወድዳታለሁ” አለው።'),
  ('ce29d5ce-7315-5f11-a528-62332de64d46', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 5, 5, 'ኢዮናዳብም አለው፦“ ታምሜአለሁ ብለህ በአልጋህ ላይ ተኛ፤ አባትህም ሊያይህ ይመጣል፦ እኅቴ ትዕማር እንድትመጣና እኔ የምበላውን እንጀራ እንድትሰጠኝ፥ መብሉንም እኔ እያየሁ እንድታበስልልኝ፥ ከእጅዋም እንድበላው እለምንሃለሁ በለው።”'),
  ('da780e2c-06e3-5bac-a424-63556e624e44', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 6, 6, 'እንዲሁም አምኖን፥ ታምሜአለሁ ብሎ ተኛ፤ ንጉሡም ሊያየው መጣ፤ አምኖንም ንጉሡን፥ “እኅቴ ትዕማር እንድትመጣና እኔ እያየሁ ሁለት እንጎቻ እንድታበስልልኝ፥ ከእጅዋም እንድበላ እለምንሃለሁ” አለው።'),
  ('d36ce370-99bc-596c-a214-cd230da39853', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 7, 7, 'ዳዊትም፥ “ወደ ወንድምሽ ወደ አምኖን ቤት ሂጂ፤ መብልንም አዘጋጂለት” ብሎ ወደ ትዕማር ቤት ላከ።'),
  ('4cdab8cf-d524-5f2f-ab86-15e88b0bdd92', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 8, 8, 'ትዕማርም ወደ ወንድምዋ ወደ አምኖን ቤት ሄደች፤ ተኝቶም ነበር፤ ዱቄትም ወስዳ ለወሰች፤ በፊቱም እንጎቻ አደረገች፤ ጋገረችም።'),
  ('e9882370-08ed-5d4d-a2e4-da2b56115d6c', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 9, 9, 'ምጣዱንም ወስዳ በፊቱ ገለበጠች፤ እርሱ ግን ይበላ ዘንድ እንቢ አለ። አምኖንም፥ “ሰውን ሁሉ ከእኔ ዘንድ አስወጡ” አለ፤ ሰውም ሁሉ ከእርሱ ዘንድ ወጣ።'),
  ('099d94c7-1536-5cae-acc7-4e2023110295', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 10, 10, 'አምኖንም ትዕማርን፥ “በእጅሽ እበላ ዘንድ መብሉን ወደ እልፍኙ አግቢው” አላት፤ ትዕማርም የሠራችውን እንጎቻ ወስዳ ወንድምዋ አምኖን ወዳለበት እልፍኝ አገባችው።'),
  ('7a0296a2-8911-5bb9-adaa-476fe267dbdb', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 11, 11, 'ይበላም ዘንድ መብሉን አቀረበችለት። እርሱም ያዛትና፥ “እኅቴ ሆይ፥ ነዪ ከእኔ ጋር ተኚ” አላት።'),
  ('a9eb6e52-6338-5321-a515-b0ba690408ce', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 12, 12, 'እርስዋም አለችው፥ “ወንድሜ ሆይ፥ አታዋርደኝ፤ እንዲህ ያለ ነገር በእስራኤል ዘንድ አይገባምና ይህን ነውረኛ ሥራ አታድርግ።'),
  ('26ba9b62-12a9-5b0f-a020-48dce8ec6d49', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 13, 13, 'እኔም ነውሬን ወዴት እጥላታለሁ? አንተም በእስራኤል ዘንድ ከሰነፎች እንደ አንዱ ትሆናለህ፤ እንግዲያስ ለንጉሡ ንገረው፥ እኔንም አይነሣህም” አለችው።'),
  ('6645ffbf-a401-546c-af40-36ecfd294725', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 14, 14, 'አምኖንም ቃልዋን አልሰማም፤ ይዞም አደከማት፤ ከእርስዋም ጋር ተኛ።'),
  ('37f23d91-083a-5d37-ac3a-6ae109c35718', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 15, 15, 'ከዚያም በኋላ አምኖን ፈጽሞ ጠላት፤ አስቀድሞ ከአፈቀራት ፍቅር ይልቅ በኋላ የጠላት ጥል በለጠ። አምኖንም፥ “ተነሥተሽ ሂጂ” አላት።'),
  ('877e8e84-88c9-529c-a910-c65e3b7f0121', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 16, 16, 'ትዕማርም፥ “ቀድሞ ከሠራኸው ክፋት ይልቅ እኔን በማውጣትህ የበለጠ ክፋት ትሠራለህ” አለችው፤ አምኖን ግን ቃልዋን አልሰማትም።'),
  ('8c6f5a2a-d45e-5775-add7-551203f67092', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 17, 17, 'በበር ቁሞ የሚያገለግለውንም ብላቴና ጠርቶ፥ “ይህችን ሴት ከፊቴ አስወጥተህ በሩን ዝጋባት” አለው።'),
  ('51f2c014-4ba1-5b44-a229-3c2819bd8c7e', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 18, 18, 'ብዙ ኅብር ያለውንም ልብስ ለብሳ ነበር፤ የንጉሡ ልጆች ደናግሉ እንዲህ ያለውን ልብስ ይለብሱ ነበርና፤ አገልጋዩም አስወጥቶ በሩን ዘጋባት።'),
  ('ada1e9da-44bb-5059-a1ea-ffcc25badcf3', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 19, 19, 'ትዕማርም አመድ ወስዳ በራስዋ ላይ ነሰነሰች፤ በላይዋ የነበረውንም ብዙ ኅብር ያለውን ልብስዋን ቀደደችው፤ እጅዋንም በራስዋ ላይ ጭና እየጮኸች ሄደች።'),
  ('6601ea2d-7234-5fc5-ad07-f86c5f75ad9d', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 20, 20, 'ወንድምዋም አቤሴሎም፥ “ወንድምሽ አምኖን ከአንቺ ጋር ነበርን? እኅቴ ሆይ፥ አሁን ግን ዝም በዪ፤ ወንድምሽ ነውና፤ ይህን ነገር ትናገሪ ዘንድ በልብሽ አታስቢ” አላት። ትዕማርም በወንድምዋ በአቤሴሎም ቤት መበለት ሆና ተቀመጠች።'),
  ('bc438300-fb6b-5198-a1fd-488f54883507', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 21, 21, 'ንጉሡም ዳዊት ይህን ነገር ሁሉ ሰማ፤ እጅግም ተቈጣ፥ ነገር ግን የበኵር ልጁ ነበረና ስለ ወደደው የልጁን የአምኖንን ነፍስ አላሳዘነም።'),
  ('9fca0e79-c672-5c51-a8e9-54ecf015d87d', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '26010037-7ba4-5d3e-ab78-b2ea44aef7c4', 22, 22, 'አቤሴሎምም አምኖንን ክፉም ሆነ መልካም አልተናገረውም። እኅቱን ትዕማርን ስላስነወራት አቤሴሎም አምኖንን ጠልቶታልና።'),
  ('83978199-b134-5921-afe6-868d3a01fdc1', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 1, 23, 'ከሁለት ዓመትም በኋላ አቤሴሎም በኤፍሬም አቅራቢያ ባለችው በቤላሶር በጎቹን በሚያሸልትበት ጊዜ አቤሴሎም የንጉሡን ልጆች ሁሉ ጠራ።'),
  ('e1d77141-9906-5ce1-a988-038e87dc7a7d', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 2, 24, 'አቤሴሎምም ወደ ንጉሡ መጥቶ፥ “እነሆ፥ አገልጋይህ በጎቹን ያሸልታል፤ ንጉሡ ከአገልጋይህ ጋር ይሂድ፤ አገልጋዮቹም ይሂዱ” አለው።'),
  ('44d9e8cc-e446-511c-a60f-9cd194869793', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 3, 25, 'ንጉሡም አቤሴሎምን፥ “ልጄ ሆይ፥ አይሆንም፤ እንከብድብሃለንና ሁላችን አንሄድም” አለው። የግድም አለው፤ እርሱ ግን መረቀው እንጂ ለመሄድ እንቢ አለ።'),
  ('021b57b1-78f3-5a85-a443-fe547d5e7c2e', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 4, 26, 'አቤሴሎምም፥ “አንተ እንቢ ካልህ ወንድሜ አምኖን ከእኛ ጋር እንዲሄድ እለምንሃለሁ” አለ። ንጉሡም፥ “ከአንተ ጋር ለምን ይሄዳል?” አለው።'),
  ('7960ee28-e801-51a0-a8ca-7a257eb4600f', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 5, 27, 'አቤሴሎምም የግድ አለው፤ አምኖንንና የንጉሡንም ልጆች ከእርሱ ጋር ላከ።'),
  ('61078704-4b9e-5a7c-aaaa-7beee322f384', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 6, 28, 'አቤሴሎምም እንደ ንጉሥ ግብዣ ያለ ግብዣ አደረገ፤ አቤሴሎምም አገልጋዮቹን፥ “አምኖን የወይን ጠጅ ጠጥቶ ልቡን ደስ ባለው ጊዜ እዩ፦ አምኖንን ግደሉ ባልኋችሁ ጊዜ ግደሉት። አትፍሩም፤ ያዘዝኋችሁም እኔ ነኝና በርቱ፤ ጽኑም” ብሎ አዘዛቸው።'),
  ('658dd37e-08b1-5468-a452-8b29535152b7', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 7, 29, 'የአቤሴሎምም አገልጋዮች አቤሴሎም እንዳዘዛቸው በአምኖን ላይ አደረጉበት። የንጉሡም ልጆች ሁሉ ተነሥተው በየበቅሎዎቻቸው ተቀምጠው ሸሹ።'),
  ('7c185e86-def4-511e-a3a7-889eb364c67a', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 8, 30, 'ገናም በመንገድ ሲሄዱ ለዳዊት፥ “አቤሴሎም የንጉሡን ልጆች ሁሉ ገደላቸው፤ ከእነርሱም አንድ አልቀረም” የሚል ወሬ መጣ።'),
  ('a2cfb244-509a-58cf-a3d1-4632cb959abe', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 9, 31, 'ንጉሡም ተነሥቶ ልብሱን ቀደደ፤ በምድር ላይም ወደቀ፤ በዙሪያውም ቁመው የነበሩ ብላቴኖቹ ሁሉ ልብሳቸውን ቀደዱ።'),
  ('fe5f4ae3-9b5b-5b24-a2e7-fe6213646c8e', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 10, 32, 'የዳዊትም ወንድም የሳምዓ ልጅ ኢዮናዳብ መልሶ እንዲህ አለው፥ “ጌታዬ ጐልማሶቹ የንጉሡ ልጆች ሁሉ እንደ ሞቱ አያስብ፤ እኅቱን ትዕማርን በግድ ካስነወራት ጀምሮ በአቤሴሎም ዘንድ የተቈረጠ ነገር ነበረና የሞተ አምኖን ብቻ ነው።'),
  ('89dd6749-85bb-539a-a4a4-a774718ad208', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 11, 33, 'አሁንም የሞተ አምኖን ብቻ ነው እንጂ የንጉሥ ልጆች ሁሉ ሞቱ ብሎ ጌታዬ ንጉሡ ይህን ነገር በልቡ አያስብ።”'),
  ('4737e77f-6f5e-5b5c-ab9c-1c518f989a35', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 12, 34, 'አቤሴሎምም ኰበለለ። ጕበኛውም ጐልማሳ ዐይኑን ከፍ አደረገ፤ እነሆም፥ ብዙ ሰዎች በኋላው በተራራው አጠገብ በመንገድ ሲመጡ አየ። ጕበኛውም መጥቶ ለንጉሡ እንዲህ ብሎ ነገረው፥ “ብዙ ሰዎች በተራራው ጎን ባለው በአርኖን መንገድ ሲመጡ አየሁ።”'),
  ('91b30639-e8be-5983-a1b5-2f3c315e1d8d', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 13, 35, 'ኢዮናዳብም ንጉሡን፥ “እነሆ፥ የንጉሡ ልጆች መጥተዋል፤ አገልጋይህ እንዳለው እንዲሁ ሆኖአል” አለው።'),
  ('c72311c7-c614-5e54-a050-e4a581d1ed45', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 14, 36, 'ተናግሮም በጨረሰ ጊዜ እነሆ፥ ወዲያው የንጉሥ ልጆች ገቡ፤ ድምፃቸውንም ከፍ አድርገው አለቀሱ፤ ደግሞም ንጉሡና ብላቴኖቹ ሁሉ እጅግ ታላቅ ልቅሶ አለቀሱ።'),
  ('088e4b4d-c141-5ed2-a8b8-d82912986060', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 15, 37, 'አቤሴሎም ግን ኰብልሎ ወደ መአክ ሀገር ወደ ጌድሶር ንጉሥ ወደ አሚሁድ ልጅ ወደ ቶልማይዮ ሄደ። ዳዊትም ሁል ጊዜ ለልጁ ያለቅስ ነበር።'),
  ('44f67a8a-3207-52bf-a0ab-a319acc68c9c', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 16, 38, 'አቤሴሎምም ኰብልሎ ወደ ጌድሶር ሄደ፤ በዚያም ሦስት ዓመት ያህል ተቀመጠ።'),
  ('2a017b63-d99d-5f76-afe1-a013eed9dff5', '4e03dab4-e0a0-529d-a402-68c32c7a22f1', '43227c4b-df23-56ef-a2d5-92b564f66404', 17, 39, 'ንጉሡም ዳዊት አቤሴሎምን መከታተልን ተወ፤ ስለ ሞተው ልጁ ስለ አምኖን ተጽናንቶ ነበርና።'),
  ('4e7cc767-699b-5ed7-aefb-9ebf64ee5c2c', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 1, 1, 'የሶርህያ ልጅ ኢዮአብም የንጉሡ ልብ ወደ አቤሴሎም እንዳዘነበለ ዐወቀ።'),
  ('245fed6e-751d-5b53-a12c-9388bb813a0e', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 2, 2, 'ኢዮአብም ወደ ቴቁሔ ልኮ ከዚያ ብልሃተኛ ሴት አስመጣና፥ “አልቅሺ፤ የኀዘንም ልብስ ልበሺ፤ ዘይትም አትቀቢ፤ ስለ ሞተ ሰውም ብዙ ዘመን እንደምታለቅስ ሴት ሁኚ፤'),
  ('9ed46787-5400-51f1-a9f5-8913b0bec561', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 3, 3, 'ወደ ንጉሡም ገብተሽ እንዲህ ያለውን ቃል ንገሪው” አላት፤ ኢዮአብም ቃሉን በእርስዋ አፍ አደረገ።'),
  ('7ebd85fd-aa69-5c56-ab6d-4a380951e787', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 4, 4, 'እንዲሁም የቴቁሔዪቱ ሴት ወደ ንጉሥ ገብታ በግንባርዋ በምድር ላይ ወደቀች፤ ሰግዳም “ንጉሥ ሆይ፥ አድነኝ፤ አድነኝ” አለች።'),
  ('42c56cfd-f175-59a5-a63f-fd110b72b154', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 5, 5, 'ንጉሡም፥ “ምን ሆነሻል?” አላት። እርስዋም አለች፥ “በእውነት እኔ ባሌ የሞተብኝ ባልቴት ሴት ነኝ።'),
  ('1e2ce381-cb4b-5de7-a257-c20e96676ac0', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 6, 6, 'ለእኔም ለአገልጋይህ ሁለት ወንዶች ልጆች ነበሩኝ፤ በሜዳም ተጣሉ፤ የሚገላግላቸውም አልነበረም፤ አንዱም ሌላውን መትቶ ገደለው።'),
  ('7364f792-25d5-57e1-ab31-48bc14901592', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 7, 7, 'እነሆም፥ ዘመዶች ሁሉ በባሪያህ ላይ ተነሡ፤ ስለ ገደለው ስለ ወንድሙ ነፍስ እንገድለው ዘንድ ወንድሙን የገደለውን አውጪ አሉኝ፤ እንዲሁም ደግሞ ለባሌ ስምና ዘር በምድር ላይ እንዳይቀር ወራሹን የቀረውን መብራቴን ያጠፋሉ፤”'),
  ('bdb5714a-11e5-54da-a09c-0dc05631c8cd', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 8, 8, 'ንጉሡም ሴቲቱን፥ “ወደ ቤትሽ በሰላም ሂጂ፤ እኔም ስለ አንቺ አዝዛለሁ” አላት።'),
  ('08efe221-d72d-5157-accf-2f154e966778', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 9, 9, 'የቴቁሔዪቱም ሴት ንጉሡን፥ “ጌታዬ ንጉሥ ሆይ፥ ኀጢአቱ በእኔና በአባቴ ቤት ላይ ይሁን፤ ንጉሡና ዙፋኑ ንጹሕ ይሁን” አለችው።'),
  ('121f9dbf-cd81-531f-aa2a-2be349d1a778', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 10, 10, 'ንጉሡም፥ “የሚናገርሽ ማን ነው? አምጪልኝ፤ ከዚያም በኋላ ደግሞ አይነካሽም” አለ።'),
  ('4c330e58-ad9b-5acc-a4a6-4d9414b58982', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 11, 11, 'ያችም ሴት፥ “ለመግደል ባለ ደሞች እንዳይበዙ፤ ልጄንም እንዳይገድሉብኝ ንጉሥ ፈጣሪው እግዚአብሔርን ያስብ” አለች። እርሱም፥ “የልጅሽስ አንዲት የራሱ ጠጕር በምድር ላይ እንዳትወድቅ ሕያው እግዚአብሔርን” አላት።'),
  ('859cf092-e514-58e7-aea1-271b7db9069a', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 12, 12, 'ሴቲቱም፥ “እኔ አገልጋይህ ለጌታዬ ለንጉሥ አንድ ቃል ልናገር” አለች፤ እርሱም፥ “ተናገሪ” አላት።'),
  ('f7cc3e1e-2e78-5619-afc7-f37cb660a021', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 13, 13, 'ሴቲቱም አለች፥ “በእግዚአብሔር ሕዝብ ላይ እንዲህ ያለ ነገር ስለምን አሰብህ? ወይስ ንጉሥ ያሳደደውን ስላላስመለሰ እንደ በደል ከንጉሥ አፍ ይህ ቃል ወጥቶአልን?'),
  ('45b8f5ee-16fb-572b-a91b-5091a2aab043', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 14, 14, 'ሞትን እንሞታለንና፥ በምድርም ላይ እንደ ፈሰሰና እንደማይመለስ ውኃ እንሆናለንና፥ እግዚአብሔርም ነፍስን ይወስዳል። የተጣለውንም ከእርሱ ያርቅ ዘንድ ያስባል።'),
  ('a35fb3b5-bffb-5ac7-af2f-26ed1d35f04f', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 15, 15, 'አሁንም ሕዝቡ ስለሚያዩኝ ይህን ነገር ለጌታዬ ለንጉሥ እነግረው ዘንድ መጥቻለሁ፤ እኔም አገልጋይህ፦ የእኔን የአገልጋዩን ልመና ንጉሡ ያደርግልኝ እንደ ሆነ ለጌታዬ ለንጉሥ ልናገር፤'),
  ('c9583e66-3090-5f45-a3cc-053c302b1bba', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 16, 16, 'እኔንና ልጄን ከእግዚአብሔር ርስት ያርቀን ዘንድ ከሚሻ ሰው እጅ ያድን ዘንድ ንጉሡ አገልጋዩን ይሰማል አልሁ።”'),
  ('a0fc3e95-508d-58f6-aedd-2c4c244c983a', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 17, 17, 'ያችም ሴት አለች፥ “መልካሙንና ክፉውን ነገር ለመስማት ንጉሡ ጌታዬ እንደ መሥዋዕትና እንደ እግዚአብሔር መልአክ ነውና የጌታዬ የንጉሡ ቃል እንደዚሁ ነው፤ አምላክህም እግዚአብሔር ከአንተ ጋር ይሁን።”'),
  ('aba2a354-2ae8-5f30-a1ed-f95c2558f714', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 18, 18, 'ንጉሡም ለሴቲቱ መልሶ፥ “የምጠይቅሽን ነገር አትሰውሪኝ” አላት። ሴቲቱም፥ “ጌታዬ ንጉሥ ይናገር” አለች።'),
  ('40aef767-233e-5701-acd3-c7c7b4925f13', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 19, 19, 'ንጉሡም፥ “በዚህ ሁሉ ነገር የኢዮአብ እጅ ከአንቺ ጋር አለን?” አላት። ሴቲቱም ንጉሡን አለችው፥ “ጌታዬ ንጉሥ ሆይ፥ በሕያው ነፍስህ እምላለሁ! ጌታዬ ንጉሥ ከተናገረው ነገር ሁሉ ወደ ቀኝም ወደ ግራም ሊል የሚችል የለም፤ አገልጋይህ ኢዮአብ አዝዞኛል፤ ይህንም ቃል ሁሉ በአገልጋይህ አፍ አደረገው።'),
  ('bd639211-7657-5841-a488-616a59b1d0bf', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 20, 20, 'ይህን ነገር እናገር ዘንድ እንድመጣ ይህን ምክር ያደረገ አገልጋይህ ኢዮአብ ነው። ጌታዬ ግን በዚህ ዓለም የሚደረገውን ሁሉ ታውቅ ዘንድ እንደ መልአከ እግዚአብሔር ጥበብ ጥበበኛ ነህ፤”'),
  ('5d9260c5-8679-5ee0-ac2c-948a3cfbd533', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 21, 21, 'ንጉሡም ኢዮአብን፥ “እነሆ፥ ይህን ነገር አድርጌአለሁ፤ ሂድና ብላቴናውን አቤሴሎምን መልሰው” አለው።'),
  ('d7d25335-5452-5294-abd8-173027ea684d', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 22, 22, 'ኢዮአብም በምድር ላይ በግንባሩ ወድቆ ሰገደለት፤ ንጉሡንም አመሰገነ፤ ኢዮአብም፥ “ጌታዬ ንጉሥ ሆይ፥ የአገልጋይህን ነገር አድርገሃልና በዐይንህ ፊት ሞገስን እንዳገኘ አገልጋይህ ዛሬ ዐወቀ” አለ።'),
  ('21e2ed67-a242-5ad8-a240-91049aed2176', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 23, 23, 'ኢዮአብም ተነሥቶ ወደ ጌድሶር ሄደ፤ አቤሴሎምንም ወደ ኢየሩሳሌም አመጣው።'),
  ('f6818dd8-9766-5fbb-af76-281410ea1f1a', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 24, 24, 'ንጉሡም፥ “ወደ ቤቱ ይሂድ እንጂ ፊቴን እንዳያይ” አለ፤ አቤሴሎምም ወደ ቤቱ ተመለሰ፤ የንጉሡንም ፊት አላየም።'),
  ('7e52d777-756a-5a11-a8f4-9440acd2b71b', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 25, 25, 'በእስራኤል ሁሉ ዘንድ እንደ አቤሴሎም በውበቱ ያማረ ሰው አልነበረም፤ ከእግሩ እስከ ራሱ ድረስ ነውር አልነበረበትም።'),
  ('48888a2b-5ff9-5bb8-a605-97a1b098038c', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 26, 26, 'ቀድሞ በመጀመሪያ ዘመን ጠጕሩ ይከብደው ነበርና በዓመት አንድ ጊዜ ይቈረጠው ነበር፤ ሲቈረጥም የራሱ ጠጕር በንጉሥ ሚዛን ሁለት መቶ ሰቅል ያህል ይመዝን ነበር።'),
  ('3ee88ee5-7994-5fab-a7d5-ec9704074d9d', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 27, 27, 'ለአቤሴሎምም ሦስት ወንዶች ልጆችና አንዲት ሴት ልጅ ተወለዱለት። የሴቲቱ ልጅም ስም ትዕማር ይባላል። ያችውም ሴት መልከ መልካም ነበረች፤ እርሷም የሰሎሞን ልጅ የሮብአም ሚስት ሆና አቢያን ወለደችለት።'),
  ('82945abf-0f88-5cc0-a348-b13258a8077d', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 28, 28, 'አቤሴሎምም በኢየሩሳሌም ሁለት ዓመት ሙሉ ተቀመጠ፤ የንጉሡንም ፊት አላየም።'),
  ('80e0ee94-fa76-57d9-a6d8-382d8fe030ef', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 29, 29, 'አቤሴሎምም ወደ ንጉሡ ይልከው ዘንድ ወደ ኢዮአብ ላከ፤ ወደ እርሱም ሊመጣ አልወደደም፤ ሁለተኛም ላከበት፤ ሊመጣ ግን አልወደደም።'),
  ('08a0f53e-564b-5e6c-a495-649e0d525773', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 30, 30, 'አቤሴሎምም ብላቴኖቹን፥ “በእርሻዬ አጠገብ ያለችውን የኢዮአብን እርሻ እዩ፤ በዚያም ገብስ አለው፤ ሄዳችሁ በእሳት አቃጥሉት” አላቸው። የአቤሴሎምም ብላቴኖች እርሻውን አቃጠሉት። የኢዮአብም አሽከሮች ልብሶቻቸውን ቀድደው ተመልሰው፥ “የአቤሴሎም አሽከሮች እርሻህን በእሳት አቃጠሉት” ብለው ነገሩት።'),
  ('99c5a867-6cf8-58ad-a435-40dfa6962979', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 31, 31, 'ኢዮአብም ተነሥቶ ወደ አቤሴሎም ወደ ቤቱ መጣና፥ “ብላቴኖችህ እርሻዬን ስለምን አቃጠሉት?” አለው።'),
  ('be17d5e3-ecc0-5338-aa9d-1eca506815d4', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 32, 32, 'አቤሴሎምም ኢዮአብን፥ “ከጌድሶር ለምን መጣሁ? በዚያም ተቀምጬ ቢሆን ይሻለኝ ነበር ብለህ እንድትነግረው ወደ ንጉሥ እልክህ ዘንድ ወደ እኔ ና ብዬ ወደ አንተ ላክሁ፤ አሁንም የንጉሡን ፊት አላየሁም፤ ኀጢአት ቢኖርብኝ ይግደለኝ” አለው።'),
  ('3b9d01c8-1eae-5fd7-a9cb-526fe3e11ab4', '285d8f18-2627-598b-a3e4-4ff87b5ad582', '25590f6a-859d-56c0-ab54-779967b7c51f', 33, 33, 'ኢዮአብም ወደ ንጉሥ መጥቶ ነገረው፤ አቤሴሎምንም ጠራው፥ ወደ ንጉሡም ገብቶ ሰገደለት፤ በንጉሡም ፊት ወደ ምድር በግንባሩ ወደቀ፤ ንጉሡም አቤሴሎምን ሳመው።'),
  ('4ba5c983-3bec-564e-aa1b-f7278ed9f2cf', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 1, 1, 'ከዚህም በኋላ አቤሴሎም ሰረገላና ፈረሶች፥ በፊቱም የሚሮጡ አምሳ ሰዎች አዘጋጀ።'),
  ('f2f1073a-8790-587d-a6d8-ed14bd94761c', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 2, 2, 'አቤሴሎምም በማለዳ ተነሥቶ በበሩ ጎዳና ይቆም ነበር፤ አቤሴሎምም ከንጉሥ ለማስፈረድ ጉዳይ የነበረውን ሁሉ ወደ እርሱ እየጠራ፥ “አንተ ከወዴት ከተማ ነህ?” ብሎ ይጠይቅ ነበር። እርሱም፥ “እኔ አገልጋይህ ከእስራኤል ወገን ከአንዲቱ ነኝ” ይለው ነበር።'),
  ('2377c65c-5c38-5cb5-a56b-955d6ba320a3', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 3, 3, 'አቤሴሎምም፥ “ነገርህ መልካም ነው፤ ቀላልም ነው፤ ነገር ግን ከንጉሥ ዘንድ የሚሰማህ የለም” ይለው ነበር።'),
  ('1f1c6891-9fe7-5ba2-afb0-d4396b610b64', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 4, 4, 'አቤሴሎምም፥ “ነገርና ክርክር ያለው ሁሉ ወደ እኔ ይመጣ ዘንድ፥ ቅንም ፍርድ እፈርድለት ዘንድ በሀገር ላይ ፈራጅ አድርጎ ማን በሾመኝ?” ይል ነበር።'),
  ('c05d1ea9-a821-5414-a809-43aad61a05b5', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 5, 5, 'ሰውም እጅ ለመንሣት ወደ እርሱ በቀረበ ጊዜ እጁን ዘርግቶ አቅፎ ይስመው ነበር።'),
  ('019ee2ef-9154-5c96-ac55-6c15923c60b6', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 6, 6, 'በንጉሡ ዘንድ ሊፋረዱ ለሚመጡ ለእስራኤል ሁሉ አቤሴሎም እንዲህ ያደርግ ነበር፤ አቤሴሎምም የእስራኤልን ሰዎች ልብ ማረከ።'),
  ('4b87f16e-6de1-5276-abdb-4f550d8f4808', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 7, 7, 'እንዲህም ሆነ፤ ከአራት ዓመት በኋላ አቤሴሎም አባቱን፥ “ለእግዚአብሔር የተሳልሁትን ስእለት በኬብሮን አደርግ ዘንድ ልሂድ።'),
  ('1d3c58b5-b721-5ad6-af6d-57680e87e1f8', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 8, 8, 'እኔ አገልጋይህ በሶርያ ጌድሶር ሳለሁ፦ እግዚአብሔር ወደ ኢየሩሳሌም ቢመልሰኝ ለእግዚአብሔር መሥዋዕት አቀርባለሁ ብዬ ስእለት ተስዬ ነበርና” አለው።'),
  ('8d1ced7b-1257-5fed-a19b-45981a7d2e24', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 9, 9, 'ንጉሡም፥ “በሰላም ሂድ” አለው፤ ተነሥቶም ወደ ኬብሮን ሄደ።'),
  ('a4d9d5c5-666b-51ad-a83d-5386bdc33695', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 10, 10, 'አቤሴሎምም፥ “የመለከት ድምፅ በሰማችሁ ጊዜ፥ አቤሴሎም በኬብሮን ነገሠ” በሉ የሚሉ ጕበኞችን ወደ እስራኤል ነገድ ሁሉ ላከ።'),
  ('dd1a2956-7475-53b7-a072-41845f20fda6', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 11, 11, 'የተጠሩትም ሁለት መቶ ሰዎች ከአቤሴሎም ጋር ከኢየሩሳሌም ሄዱ፤ እነርሱም በየዋህነት ሄዱ፤ ነገሩንም ሁሉ ከቶ አያውቁም ነበር።'),
  ('f89474b7-0a36-5304-adff-9e2098236dbc', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'd21385b0-9556-503f-a0b6-e31b1639d7be', 12, 12, 'አቤሴሎምም መሥዋዕት በሚሠዋበት ጊዜ የዳዊት አማካሪ ወደ ነበረው ጌሎናዊው አኪጦፌል ወደ ከተማው ጊሎ ላከ። ሴራውም ጽኑ ሆነ፤ ከአቤሴሎምም ጋር ያለው ሕዝብ እጅግ በዛ።'),
  ('a9dd5ce1-15bf-50a8-a358-c2abf2c5f6e7', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 1, 13, 'የእስራኤልም ሰዎች ልብ ወደ አቤሴሎም ተመልሶአል የሚል መልእክተኛ ወደ ዳዊት ሄደ።'),
  ('3b7ade05-a659-5d41-aff3-1b7751f33649', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 2, 14, 'ዳዊትም ከእርሱ ጋር በኢየሩሳሌም ያሉትን አገልጋዮቹን ሁሉ፥ “ተነሡ እንሽሽ፤ ከአቤሴሎም እጅ የምንድንበት የለንምና፤ ፈጥኖ እንዳይዘን፥ ክፉም እንዳያመጣብን፤ ከተማዪቱንም በሰልፍ ስለት እንዳይመታ ፈጥናችሁ እንሂድ” አላቸው።'),
  ('a7c6dbce-bafc-56fd-a531-621cfb1f28db', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 3, 15, 'የንጉሡም ብላቴኖች ንጉሡን፥ “እነሆ፥ ጌታችን ንጉሥ የመረጠውን ሁሉ እኛ አገልጋዮችህ እናደርጋለን” አሉት።'),
  ('50ffd6e4-2677-5451-a4b0-aade320f9101', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 4, 16, 'ንጉሡና ከእርሱም በኋላ ቤተ ሰቡ ሁሉ በእግራቸው ወጡ፤ ንጉሡም ቁባቶቹ የነበሩ ዐሥሩን ሴቶች ቤቱን ይጠብቁ ዘንድ ተወ።'),
  ('e39f303b-06ea-5b9c-a271-927a2069bf09', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 5, 17, 'ንጉሡና ሕዝቡ ሁሉ በእግር ወጡ፤ በሩቅም ቦታ ቆሙ።'),
  ('3c2cbee0-3c66-5ace-a500-6e4f0cc8b43b', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 6, 18, 'ብላቴኖቹም ሁሉ ተከተሉት፤ ኬልቲያውያንና ፌልታውያንም ሁሉ በምድረ በዳ በወይራ ሥር ቆሙ። ሕዝቡም ሁሉ ከእርሱ ጋር ይሄዱ ነበር። ከእርሱ ጋር ያሉ ሰዎችም ሁሉ ስድስት መቶ ነበሩ። ከእርሱ ጋር ፌልታውያንና ኬልቲያውያን፥ በእግራቸው ከጌት የመጡ ስድስት መቶ ጌታውያንም ነበሩ። በንጉሡም ፊት ይሄዱ ነበር።'),
  ('3175cc0a-d50f-55fb-afaa-3a8bd8408dc8', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 7, 19, 'ንጉሡም ጌታዊውን ኤቲን፥ “ከእኛ ጋር ለምን መጣህ? አንተ ከስፍራህ የመጣህ ስደተኛና እንግዳ ነህና ተመለስ፤ ከንጉሡም ጋር ተቀመጥ፤'),
  ('298560b2-5757-5f3b-aab0-faae1d567bde', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 8, 20, 'የመጣኸው ትናንት ነው፤ ዛሬ ከእኛ ጋር ላዙርህን? እኔ ወደምሄድበት እሄዳለሁ፤ አንተ ግን ተመለስ፤ ወንድሞችህንም ከአንተ ጋር መልሳቸው፤ እግዚአብሔርም ምሕረቱንና እውነቱን ያድርግልህ” አለው።'),
  ('c24f51eb-40ef-51b4-a004-262816c72c39', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 9, 21, 'ኤቲም ለንጉሡ መልሶ፥ “ሕያው እግዚአብሔርን! በጌታዬም በንጉሡ ሕይወት እምላለሁ! ጌታዬ ባለበት ስፍራ ሁሉ፥ በሞትም ቢሆን በሕይወትም፥ በዚያ ደግሞ እኔ አገልጋይህ እሆናለሁ” አለው።'),
  ('ee55b604-23e8-57ae-af45-b119d7ca9390', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 10, 22, 'ንጉሡም ኤቲን፥ “ና ከእኔ ጋር ተሻገር” አለው፤ ጌታዊው ኤቲና ንጉሡም፥ አገልጋዮቹም፥ ከእርሱም ጋር የነበሩት ሕዝቡ ሁሉ ተሻገሩ።'),
  ('45e3ab16-b184-5aef-a6e7-e65f04f3812b', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 11, 23, 'ሀገሪቱም ሁላ በታላቅ ድምፅ አለቀሰች። ሕዝቡም ሁሉ በቄድሮን ወንዝ ተሻገሩ፤ ንጉሡም ደግሞ የቄድሮንን ወንዝ ተሻገረ፤ ንጉሡና ሕዝቡም ሁሉ ወደ ምድረ በዳ በሚወስደው መንገድ ተሻገሩ።'),
  ('12c1a691-b3a4-5ff3-af06-a30b65221f34', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 12, 24, 'እነሆም፥ ደግሞ፥ ሳዶቅና ከእርሱም ጋር ሌዋውያን ሁሉ የእግዚአብሔርን ቃል ኪዳን ታቦት አመጡ፤ የእግዚአብሔርንም ታቦት አስቀመጡ፤ ሕዝቡም ሁሉ ከከተማዪቱ ፈጽሞ እስኪያልፉ ድረስ አብያታር ወጣ።'),
  ('4d417923-f3c8-5121-a52b-5146722cc696', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 13, 25, 'ንጉሡም ሳዶቅን፥ “የእግዚአብሔርን ታቦት ወደ ከተማ መልስ፤ በእግዚአብሔር ዐይን ሞገስ አግኝቼ እንደ ሆንሁ፥ መልሶ እርሷንና ክብሯን ያሳየኛል፤'),
  ('fb855358-0e07-5ae2-aef4-5823d972c80a', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 14, 26, 'ነገር ግን አልወድድህም ቢለኝ፥ እነሆኝ በፊቱ ደስ የሚያሰኘውን ያድርግብኝ” አለው።'),
  ('54166e66-787d-5de9-a5a4-e9442eb75d9a', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 15, 27, 'ንጉሡም ደግሞ ካህኑን ሳዶቅን፥ “እነሆ፥ አንተና ልጅህ አኪማኦስ፥ የአብያታርም ልጅ ዮናታን፥ ሁለቱ ልጆቻችሁ ከእናንተ ጋር በሰላም ወደ ከተማ ተመለሱ።'),
  ('07c8c9a4-60e4-5797-ae96-f0ba8f36a114', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 16, 28, 'እዩ፤ እኔም እነሆ፥ ከእናንተ ዘንድ ወሬ እስኪመጣልኝ ድረስ በምድረ በዳው ውስጥ በሜዳው እቈያለሁ” አለው።'),
  ('1ec5475e-f268-5272-a7d3-39908c5082a2', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 17, 29, 'ሳዶቅና አብያታርም የእግዚአብሔርን ታቦት ወደ ኢየሩሳሌም መለሷት፤ በዚያም ተቀመጡ።'),
  ('4d9ed0cd-e77c-5d5a-abe5-eb921ad45497', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 18, 30, 'ዳዊትም ወደ ደብረ ዘይት ዐቀበት ወጣ፤ ሲወጣም ያለቅስ ነበር፤ ራሱንም ተከናንቦ ነበር፤ ያለጫማም ይሄድ ነበር፤ ከእርሱም ጋር የነበሩት ሕዝብ ሁሉ ተከናንበው ነበር፤ እያለቀሱም ይወጡ ነበር።'),
  ('644463bf-4c2f-5ec1-af95-dbf27c1ea0cd', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 19, 31, 'አኪጦፌል ከአቤሴሎም ጋር በሴራ አንድ ነው ብለው ለዳዊት ነገሩት፤ ዳዊትም፥ “አቤቱ የአኪጦፌልን ምክር ለውጥ” አለ።'),
  ('3f3f5e87-ff5a-5ff6-a6f7-a9769698c9f5', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 20, 32, 'ዳዊትም ለእግዚአብሔር ወደ ሰገደበት ወደ ተራራው ራስ መጣ፤ ወዳጁ ኵሲም ልብሱን ቀደደ፤ በራሱም ላይ ትቢያ ነስንሶ ሊገናኘው መጣ።'),
  ('bb6698f4-a9ae-5a3b-a8d1-0eaf9ca866dd', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 21, 33, 'ዳዊትም አለው፥ “ከእኔ ጋር ብትሻገር ሸክም ትሆንብኛለህ፤'),
  ('afe3ad30-4f4e-56c9-a44c-2c1a470b0505', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 22, 34, 'ወደ ከተማ ግን ተመልሰህ ለአቤሴሎም፦ ወንድሞችህ፥ ንጉሡም መጡ። እነሆ፥ በኋላዬ ናቸው። ንጉሥ ሆይ፥ አገልጋይህ ነኝ፤ አስቀድሞ ለአባትህ አገልጋይ ነበርሁ፥ እንዲሁ አሁንም ለአንተ አገልጋይ ነኝ፥ ተወኝ ልኑር ብትለው የአኪጦፌልን ምክር ትለውጥልኛለህ።'),
  ('57d03459-c50d-591c-a37e-0533ec09810c', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 23, 35, 'እነሆ፥ ካህናቱ ሳዶቅና አብያታርም በዚያ ከአንተ ጋር ናቸው። ከንጉሡ ቤትም የምትሰማውን ነገር ሁሉ ለካህናቱ ለሳዶቅና ለአብያታር ንገራቸው።'),
  ('691b8a9e-bd3b-51e1-abbb-00fa7b47e54e', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 24, 36, 'እነሆ፥ የሳዶቅ ልጅ አኪማኦስና የአብያታር ልጅ ዮናታን፥ ልጆቻቸው በዚያ ከእነርሱ ጋር አሉ፤ የምትሰሙትን ሁሉ በእነርሱ እጅ ላኩልኝ።”'),
  ('ccf1bb2d-4b16-5049-af46-e02d61608faf', '6acac62a-03f4-525f-a2f6-d322d8b581de', 'a2b01656-8d8e-55ba-a1a2-31f3c7cc2b47', 25, 37, 'የዳዊትም ወዳጅ ኩሲ ወደ ከተማ መጣ፤ አቤሴሎምም ደግሞ ወደ ኢየሩሳሌም ገባ።'),
  ('74712e58-97eb-59db-a612-383f72eed5bb', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '3a3d92ff-45a4-582d-a0af-86c4f1a03abf', 1, 1, 'ዳዊትም ከተራራው ራስ ጥቂት እልፍ አለ። እነሆም፥ የሜምፌቡስቴ አገልጋይ ሲባ ሁለት መቶ እንጀራ፥ አንድ መቶም ዘለላ ዘቢብ፥ አንድ መቶም ተምር፥ አንድ አቁማዳም ወይን ጠጅ የተጫኑ ሁለት አህዮች እየነዳ ተገናኘው።'),
  ('9ea6ff0a-e837-5ab0-afb8-a85c75f6cc60', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '3a3d92ff-45a4-582d-a0af-86c4f1a03abf', 2, 2, 'ንጉሡም ሲባን፥ “ይህ ለአንተ ምንድን ነው?” አለው። ሲባም፥ “አህዮቹ የንጉሥ ቤተ ሰቦች ይቀመጡባቸው ዘንድ፥ እንጀራውና ተምሩም ብላቴኖቹ ይበሉት ዘንድ፥ የወይን ጠጁም በበረሃ የሚደክሙት ይጠጡት ዘንድ ነው” አለ።'),
  ('fc959a8b-8574-5ced-a66c-baec1475343a', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '3a3d92ff-45a4-582d-a0af-86c4f1a03abf', 3, 3, 'ንጉሡም፥ “የጌታህ ልጅ ወዴት ነው?” አለ። ሲባም ንጉሡን፥ “እነሆ፥ የእስራኤል ቤት ዛሬ የአባቴን መንግሥት ይመልስልኛል ብሎ በኢየሩሳሌም ተቀምጦአል” አለው።'),
  ('0bff0f6e-3687-5cbb-ad1d-684171af8d49', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '3a3d92ff-45a4-582d-a0af-86c4f1a03abf', 4, 4, 'ንጉሡም ሲባን፥ “እነሆ፥ ለሜምፌቡስቴ የነበረው ሁሉ ለአንተ ይሁን” አለው። ሲባም ሰግዶ፥ “ጌታዬ ንጉሥ ሆይ፥ በፊትህ ሞገስን ላግኝ” አለ።'),
  ('145cad6b-57d3-5f0a-a9a2-20e23f3a0003', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 1, 5, 'ንጉሡ ዳዊትም ወደ በውሪም መጣ፤ እነሆም፥ ሳሚ የሚባል የጌራ ልጅ ከሳኦል ቤተ ዘመድ የሆነ አንድ ሰው ከዚያ ወጣ፤ እየሄደም ይረግመው ነበር።'),
  ('313b04f0-34b2-5410-ab69-0e5dd755b9d0', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 2, 6, 'ወደ ዳዊትና ወደ ንጉሡ ወደ ዳዊት አገልጋዮችም ድንጋይ ይወረውር ነበር፤ በንጉሡም ቀኝና ግራ ሕዝቡ ሁሉና ኀያላኑ ሁሉ ነበሩ።'),
  ('4c15cfd0-696d-5ec2-a2a7-65f7e0c34c63', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 3, 7, 'ሳሚም ሲረግመው እንዲህ ይል ነበር፥ “ውጣ! አንተ የደም ሰውና ዐመፀኛ ሰው ሂድ! ሂድ!'),
  ('582db81c-1c71-510f-a166-29deb4b09b06', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 4, 8, 'በፋንታው ነግሠሃልና እግዚአብሔር የሳኦልን ቤት ደም ሁሉ መለሰብህ፤ እግዚአብሔርም መንግሥትህን ለልጅህ ለአቤሴሎም እጅ አሳልፎ ሰጥቶታል፤ እነሆም፥ አንተ የደም ሰው ነህና በመከራ ተይዘሃል።”'),
  ('e0e0ec28-5fd8-53d7-a362-ffbd7b18700f', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 5, 9, 'የሶርህያ ልጅ አቢሳም ንጉሡን አለው፥ “ይህ የሞተ ውሻ ጌታዬን ንጉሡን ስለምን ይረግማል? ልሻገርና ራሱን ልቍረጠው፤”'),
  ('434b815c-dad8-5821-a12b-7fb8550a7ba9', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 6, 10, 'ንጉሡም፥ “እናንተ የሶርህያ ልጆች! በእኔና በእናንተ መካከል ምን አለኝ? እግዚአብሔር ዳዊትን ርገመው ብሎ አዝዞታልና ይርገመኝ፤ ለምንስ እንዲህ ታደርጋለህ? የሚለው ማን ነው?” አለ።'),
  ('f54c9ac0-f798-50b1-a0a1-129366c0442d', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 7, 11, 'ዳዊትም አቢሳንና አገልጋዮቹን ሁሉ፥ “እነሆ፥ ከወገቤ የወጣው ልጄ ነፍሴን ይሻል፤ ይልቁንስ ይህ የኢያሚን ልጅ እንዴት ነዋ? እግዚአብሔር አዝዞታልና ተዉት፥ ይርገመኝ።'),
  ('95683bb7-71df-5b34-a9be-524966f17f97', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 8, 12, 'ምናልባት መከራዬን አይቶ ስለ ርግማኑ በዚህ ቀን መልካም ይመልስልኛል” አላቸው።'),
  ('d3f5f602-9119-552b-a753-9c562fc06716', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 9, 13, 'ዳዊትና ሰዎቹም በመንገድ ይሄዱ ነበር፤ ሳሚም በተራራው አጠገብ በአቅራቢያው ይሄድ ነበር፤ ሲሄድም ይረግመው፥ ድንጋይም ይወረውርበት ነበር፤ ትቢያም ይበትንበት ነበር።'),
  ('db3952c8-e598-5223-a00f-cf5292c8dfbe', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '05a654c4-200d-51f1-af83-2904f33fd960', 10, 14, 'ንጉሡና ከእርሱም ጋር የነበረው ሕዝብ ሁሉ ደረሱ፤ ደክመውም ነበር፤ በዚያም ዐረፉ።'),
  ('657821c0-7413-5175-a89f-13072bdde113', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '4dbb76f1-dd69-5933-ad63-a43542fc272e', 1, 15, 'አቤሴሎምና የእስራኤል ሕዝብ ሁሉ፥ አኪጦፌልም ከእርሱ ጋር ወደ ኢየሩሳሌም መጡ።'),
  ('655ec2df-ea36-5c40-a125-223650a4c5ee', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '4dbb76f1-dd69-5933-ad63-a43542fc272e', 2, 16, 'የዳዊትም ወዳጅ ኩሲ ወደ አቤሴሎም በመጣ ጊዜ ኩሲ አቤሴሎምን፥ “ንጉሥ ሆይ! ሽህ ዓመት ያንግሥህ” አለው።'),
  ('c225ba89-c694-5f3a-a496-064aab997429', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '4dbb76f1-dd69-5933-ad63-a43542fc272e', 3, 17, 'አቤሴሎምም ኩሲን፥ “ስለ ወዳጅህ ያደረግኸው ቸርነት ይህ ነውን? ከወዳጅህ ጋር ያልሄድህ ስለ ምንድን ነው?” አለው።'),
  ('20603418-fb87-5f71-a3fa-c231460e5db7', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '4dbb76f1-dd69-5933-ad63-a43542fc272e', 4, 18, 'ኩሲም አቤሴሎምን፥ “እንዲህ አይደለም፤ እግዚአብሔር፥ ይህም ሕዝብ፥ የእስራኤልም ሰዎች ሁሉ ለመረጡት ለእርሱ እሆናለሁ፤ ከእርሱም ጋር እኖራለሁ” አለው።'),
  ('4188e572-ba25-50ce-a820-45e3213e8b23', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '4dbb76f1-dd69-5933-ad63-a43542fc272e', 5, 19, '“ዳግምም የማገለግል ለማን ነው? በንጉሥ ልጅ ፊት አይደለምን? በአባትህ ፊት እንዳገለገልሁ እንዲሁ በአንተ ፊት እሆናለሁ” አለው።'),
  ('ebd2a7fc-7ea1-5d14-a979-c80746a642ed', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '4dbb76f1-dd69-5933-ad63-a43542fc272e', 6, 20, 'አቤሴሎምም አኪጦፌልን፦ ምን እንደምናደርግ ምከሩ አለው።'),
  ('e867a86c-556d-5077-a216-6f6dc2939a72', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '4dbb76f1-dd69-5933-ad63-a43542fc272e', 7, 21, 'አኪጦፌልም አቤሴሎምን፥ “ቤት ሊጠብቁ ወደ ተዋቸው ወደ አባትህ ቁባቶች ግባ፤ እስራኤልም ሁሉ አባትህን እንዳሳፈርኸው ይሰማሉ፤ ከአንተም ጋር ያሉት ሁሉ እጃቸው ይበረታል” አለው።'),
  ('aafbcc62-47dc-5a41-a9fa-fe43805e5687', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '4dbb76f1-dd69-5933-ad63-a43542fc272e', 8, 22, 'ለአቤሴሎምም በሰገነት ላይ ድንኳን ተከሉለት፤ አቤሴሎምም በእስራኤል ሁሉ ፊት ወደ አባቱ ቁባቶች ገባ።'),
  ('a1db8be4-2f07-5182-aa82-d37596072495', '13b666d6-d722-5ec7-a7d9-1a0835a622f5', '4dbb76f1-dd69-5933-ad63-a43542fc272e', 9, 23, 'በእነዚያ በመጀመሪያ ወራት የመከራት የአኪጦፌል ምክር የእግዚአብሔርን ቃል እንደ መጠየቅ ነበረች፤ የአኪጦፌልም ምክር ሁሉ ከዳዊትና ከአቤሴሎም ጋር እንዲሁ ነበረች።'),
  ('00b8a904-34dd-5fcc-a84e-19ae8c740cdd', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 1, 1, 'አኪጦፌልም አቤሴሎምን አለው፥ “ዐሥራ ሁለት ሺህ ሰዎች ልምረጥና በዚህች ሌሊት ተነሥቼ ዳዊትን ላሳድድ።'),
  ('2cc7e89a-9d9e-5377-a9ec-905516380488', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 2, 2, 'ደክሞና እጁ ዝሎ ሳለ እወድቅበታለሁ፤ አስፈራውማለሁ፤ ከእርሱም ጋር ያለው ሕዝብ ሁሉ ይሸሻል፤ ንጉሡንም ብቻውን እገድለዋለሁ፤'),
  ('4d47d1e5-74f6-5d48-a4d6-66e1cdd8d1c5', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 3, 3, 'ሙሽራ ወደ ባልዋ እንደምትመለስ ሕዝቡን ሁሉ ወደ አንተ እመልሰዋለሁ፤ የአንድ ሰው ሰውነትን ብቻ ትሻለህና፤ ለሕዝቡ ሁሉ ግን ሰላም ይሆናል፤”'),
  ('eac58dac-7a65-5366-a114-82b646a91187', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 4, 4, 'ነገሩም በአቤሴሎም ፊትና በእስራኤል ሽማግሌዎች ፊት ደስ አሰኘ።'),
  ('f8f465ee-c886-5cc1-a7a2-cd0ab0f9971e', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 5, 5, 'አቤሴሎምም፥ “አርካዊውን ኩሲን ጥሩት፤ ደግሞም እርሱ የሚለውን እንስማ” አለ።'),
  ('f6cb1921-0b0f-5ab5-a14b-6015ddaf7424', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 6, 6, 'ኩሲም ወደ አቤሴሎም በመጣ ጊዜ አቤሴሎም፥ “አኪጦፌል ያለው ይህ ነው፤ ነገሩን እናደርገው ዘንድ ይገባልን? ባይሆን ግን አንተ ንገረን” ብሎ ተናገረው።'),
  ('92bd4147-ac45-5b38-a9ac-070eab9cec7c', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 7, 7, 'ኩሲም አቤሴሎምን አለው፥ “አኪጦፌል በዚህ ጊዜ የመከራት ምክር መልካም አይደለችም። ይችውም አንዲት ናት።”'),
  ('7ca3f38f-14cf-55b1-a12a-a0f004ddc578', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 8, 8, 'ኩሲ ደግሞ አለ፥ “በሜዳ እንዳለች አራስ ድብና እንደ ተኳር የዱር እሪያ በልባቸው መራሮችና ኀያላን መሆናቸውን አባትህንና ሰዎቹን ታውቃለህ፤ አባትህ አርበኛ ነው፤ ሕዝቡንም አያሰናብትም።'),
  ('52af6f7a-bb9f-5c89-af53-3742534db59f', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 9, 9, 'በተራራው ላይ፥ ያም ባይሆን በአንድ ቦታ ተሰውሮአልና ከእነርሱ ፊተኞቹ ቢወድቁ የሚሰማው ሁሉ አቤሴሎምን የተከተለ ሕዝብ ተመታ ይላል።'),
  ('12c708bf-664e-52b1-ade0-20fc8cab4a10', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 10, 10, 'እርሱ ኀይለኛ ሰው ነውና፥ ልቡም እንደ አንበሳ ልብ ፈጽሞ ይናደዳልና፤ እስራኤልም ሁሉ አባትህ ጽኑዕ፥ ከእርሱም ጋር ያሉት ስዎች ኀያላን እንደ ሆኑ ያውቃሉ።'),
  ('25c10f1e-1966-500d-a094-e1ecb91516bb', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 11, 11, 'እኔ እንዲህ እመክርሃለሁ፤ ከዳን እስከ ቤርሳቤህ ያሉ እስራኤል ሁሉ ብዛታቸው እንደ ባሕር አሸዋ ሆኖ ወደ አንተ ይሰብሰቡ፤ አንተም በመካከላቸው ትሄዳለህ።'),
  ('4abdf723-b172-5833-a031-0014b843a6b3', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 12, 12, 'እርሱንም ወደምናገኝበት ወደ አንድ ስፍራ እንደርስበታለን፤ ጠልም በምድር ላይ እንደሚወድቅ እንወርድበታለን፤ እርሱንና ከእርሱም ጋር ያሉ ሰዎችን ሁሉ አንድ ስንኳ አናስቀርም።'),
  ('4525511a-8904-5765-a322-99be55db836f', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 13, 13, 'ወደ ከተማም ቢገባ እስራኤል ሁሉ ወደዚያች ከተማ ገመድ ይወስዳሉ፤ እኛም አንድ ድንጋይ እንኳን እስከማይገኝባት ድረስ ወደ ወንዙ ውስጥ እንስባታለን።”'),
  ('ed0917ff-6644-58b8-a46f-51a6afd3f88c', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '2ffae202-e38c-5812-a7cb-33f039ff6bd7', 14, 14, 'አቤሴሎምና የእስራኤልም ሰዎች ሁሉ “የአርካዊው የኩሲ ምክር ከአኪጢፌል ምክር ይሻላል” አሉ። እግዚአብሔርም በአቤሴሎም ላይ ክፉ ያመጣ ዘንድ እግዚአብሔር መልካሚቱን የአኪጦፌልን ምክር እንዲበትን አዘዘ።'),
  ('bb3c1b49-8909-517d-a14f-79e838671686', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 1, 15, 'አርካዊው ኩሲም ለካህናቱ ለሳዶቅና ለአብያታር፥ “አኪጦፌል ለአቤሴሎምና ለእስራኤል ሽማግሌዎች እንዲህና እንዲህ መክሮአል፤ እኔ ግን እንዲህና እንዲያ መክሬአለሁ።'),
  ('1243f4bc-b822-544a-ac45-0d329ecadbfd', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 2, 16, 'አሁን እንግዲህ ንጉሡና ከእርሱ ጋር ያለው ሕዝብ ሁሉ እንዳይዋጡ፥ ሳትዘገይ ዮርዳኖስን ተሻገር እንጂ በዚህች ሌሊት በምድረ በዳ ውስጥ በሜዳው አትደር ብለው ለዳዊት ይነግሩት ዘንድ ፈጥናችሁ ላኩ” አላቸው።'),
  ('f3cae876-4061-59b7-a046-bb4d61824ff4', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 3, 17, 'ዮናታንና አኪማሆስም በሮጌል ምንጭ አጠገብ ቆመው ሳለ አንዲት ብላቴና ሄዳ ነገረቻቸው፤ ወደ ከተማ መግባት አልተቻላቸውም ነበርና፤ እነርሱም ሄደው ለንጉሡ ለዳዊት ነገሩት።'),
  ('465f8d9f-b8ac-5c11-a686-632e2cb719b5', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 4, 18, 'አንድ ብላቴናም አይቶ ለአቤሴሎም ነገረው፤ እነርሱ ግን ፈጥነው ሄዱ፤ ወደ ባውሪምም ወደ አንድ ሰው ቤት መጡ፤ በግቢውም ውስጥ ጕድጓድ ነበረው፤ ወደዚያም ውስጥ ወረዱ፤'),
  ('0e6b714c-ae7c-5c23-ac77-2b2f849d05ad', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 5, 19, 'ሴቲቱም ዳውጃ ወስዳ በጕድጓዱ አፍ ላይ ዘረጋችበት፤ የተፈተገ እህልም በላዩ አሰጣችበት፤ ያወቃቸውም የለም።'),
  ('e912ec78-d4de-52b7-a5cd-7f9831103755', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 6, 20, 'የአቤሴሎምም አገልጋዮች ወደ ሴቲቱ ወደ ቤት መጥተው፥ “አኪማሆስና ዮናታን የት አሉ?” አሉ፤ ሴቲቱም፥ “ፈፋውን ተሻግረው ሄዱ፤ ጥቂትም ቀደሙአችሁ” አለቻቸው። እነርሱም ፈልገው አጡአቸው፤ ወደ ኢየሩሳሌምም ተመለሱ።'),
  ('59a2475c-45f6-5a7d-a049-255b2d0d044f', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 7, 21, 'ከሄዱም በኋላ እነርሱ ከጕድጓዱ ወጥተው ሄዱ፤ ለንጉሡም ለዳዊት ነገሩት፤ ዳዊትንም፥ “አኪጦፌል በእናንተ ላይ እንዲህ መክሮአልና ተነሡ፤ ፈጥናችሁም ውኃውን ተሻገሩ” አሉት።'),
  ('5953293d-d975-53d1-a417-f48e20622b92', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 8, 22, 'ዳዊትና ከእርሱም ጋር የነበሩት ሁሉ ተነሥተው ዮርዳኖስን ተሻገሩ፤ እስኪነጋም ድረስ ዮርዳኖስን ሳይሻገር አንድ ሰው እንኳን አልቀረም።'),
  ('b96c0ae0-9fc3-5eb8-affa-afb2fd79f201', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 9, 23, 'አኪጦፌልም ምክሩ እንዳልሠራ ባየ ጊዜ አህያውን ጫነ፤ ተነሥቶም ወደ ቤቱ ወደ ከተማው ሄደ፤ ቤቱንም አደራጅቶ በገዛ እጁ ታንቆ ሞተ፤ በአባቱም መቃብር ተቀበረ።'),
  ('7881cbfa-4923-52e9-a548-e70ef9d4cc35', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 10, 24, 'ዳዊትም ወደ ምናሄም መጣ፤ አቤሴሎምም፥ ከእርሱ ጋር የእስራኤል ሰዎች ሁሉ ዮርዳኖስን ተሻገሩ።'),
  ('c6087435-b950-5ae1-a731-d1ae531a7a14', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 11, 25, 'አቤሴሎምም በሠራዊቱ ላይ በኢዮአብ ስፍራ አሜሳይን ሾመ፤ አሜሳይም የኢዮአብን እናት የሶርህያን እኅት የነዓሶንን ልጅ አቢግያን የአገባው የኢይዝራኤላዊው የዮቶር ልጅ ነበር።'),
  ('6eb359f6-9a47-5d68-acbc-57a5d44172af', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 12, 26, 'እስራኤልና አቤሴሎምም በገለዓድ ምድር ሰፈሩ።'),
  ('4d9a84ee-f51b-59df-af12-e5a3b237950e', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 13, 27, 'ዳዊትም ወደ ምናሄም በመጣ ጊዜ በአሞን ልጆች ሀገር በአራቦት የነበረ የነዓሶን ልጅ ኡኤሴብ፥ የሎዶባርም ሰው የአሜሄል ልጅ ማኪር፥ የሮጌሌምም ሰው ገለዓዳዊው ቤርዜሊ፥'),
  ('221d2bc3-d2a4-5bd8-ab24-9b13d1ffec00', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 14, 28, 'ዐሥር አልጋዎችና ምንጣፎች፥ ዐሥርም ጋኖችና ፊቀኖች፥ የስንዴና የገብስ ዱቄት፥ ስልቅ አተርና ምስር፥'),
  ('7ab80d26-9fff-580d-a5c8-4cb70e192902', '4d00c55b-41cd-5df1-a308-8b45d67990d0', '01592d62-20fd-5b45-a0eb-967f7ba92436', 15, 29, 'ማርና ቅቤ፥ በግና ላም ይበሉ ዘንድ ለዳዊትና ከእርሱ ጋር ላሉ ሰዎች አመጡ። ሕዝቡ በምድረ በዳ ተርበውና ተጠምተው ደክመው ነበርና።'),
  ('2bbb397c-208e-5e8c-ab96-4bb093d0a6ee', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 1, 1, 'ዳዊትም ከእርሱ ጋር የነበሩትን ሕዝብ ቈጠረ፤ የሻለቆችንና የመቶ አለቆችንም በላያቸው ሾመ።'),
  ('020c516a-b05d-5a92-abe2-1d717830e7d4', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 2, 2, 'ዳዊትም ሕዝቡን ከኢዮአብ እጅ በታች ሢሶውን፥ ከኢዮአብም ወንድም ከሶርህያ ልጅ ከአቢሳ እጅ በታች ሢሶውን፥ ከጌት ሰውም ከኤቲ እጅ በታች ሢሶውን ላከ። ዳዊትም ሕዝቡን፥ “እኔ ደግሞ ከእናንተ ጋር እወጣለሁ” አላቸው።'),
  ('72272f4a-8d2e-5cd1-ac5f-f3dec329458c', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 3, 3, 'እነርሱ ግን “አንተ ከእኛ ከሁላችን ይልቅ እንደ ዐሥር ሽህ ሠራዊት ስለሆንህ ብንሸሽ ልባቸው አይከተለንምና፥ እኩሌታችንም ብንሞት ልባቸው አይከተለንምና አትውጣ፤ አሁንም መርዳትን ትረዳን ዘንድ በከተማ ብትኖርልን ይሻለናል” አሉት።'),
  ('698817ae-da7c-56b2-a81e-54313c23d8f2', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 4, 4, 'ንጉሡም፥ “በፊታችሁ መልካም የሚመስላችሁን አደርጋለሁ” አላቸው። ንጉሡም በበሩ አጠገብ ቆመ፤ ሕዝቡም ሁሉ መቶ በመቶ፥ ሺህ በሺህ እየሆኑ ወጡ።'),
  ('a7daf7a2-18a1-5c9b-a0fc-f8cb5e21df8c', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 5, 5, 'ንጉሡም ኢዮአብንና አቢሳን ኤቲንም፥ “ለብላቴናው ለአቤሴሎም ስለ እኔ ራሩለት” ብሎ አዘዛቸው። ንጉሡም ስለ አቤሴሎም አለቆቹን ሁሉ ሲያዝዝ ሕዝቡ ሁሉ ሰሙ።'),
  ('c8481ccd-20be-5ea9-a583-6a3390ba8608', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 6, 6, 'ሕዝቡም ሁሉ በእስራኤል ላይ ወደ በረሓ ወጡ፤ በኤፍሬምም በረሓ ተዋጓቸው።'),
  ('f6b5af8c-04fc-50bb-a7c0-5284b41c1c55', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 7, 7, 'በዚያም የእስራኤል ሕዝብ በዳዊት አገልጋዮች ፊት ወደቁ፤ በዚያም ቀን ታላቅ ውጊያ በዚያ ሆነ፤ ሃያ ሺህ ሰዎችም ሞቱ።'),
  ('1a6df8d1-d4da-5cf6-a5f8-c0766810f4e2', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 8, 8, 'ከዚያም ጦሩ በሀገሩ ሁሉ ፊት ተበተነ፤ በዚያም ቀን በሰይፍ ከተገደሉት ሕዝብ ይልቅ በበረሓ የሞቱ ይበዛሉ።'),
  ('ec044d36-1a1b-50f1-a25a-1f54a242c228', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 9, 9, 'አቤሴሎምም ከዳዊት አገልጋዮች ጋር ተገናኘ፤ አቤሴሎምም በበቅሎ ተቀምጦ ነበር፤ በቅሎውም ብዙ ቅርንጫፍ ባለው በታላቅ ዛፍ በታች ገባ፤ ራሱም በዛፉ ተያዘ፤ በሰማይና በምድርም መካከል ተንጠለጠለ፤ ተቀምጦበትም የነበረው በቅሎ በበታቹ አለፈ።'),
  ('92221819-a51b-5a60-af7e-311f6948aa10', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 10, 10, 'አንድ ሰውም አይቶ፥ “እነሆ፥ አቤሴሎም በዛፍ ላይ ተንጠልጥሎ አየሁ” ብሎ ለኢዮአብ ነገረው።'),
  ('30aa84c8-24ff-56f2-ae94-c515e665c236', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 11, 11, 'ኢዮአብም ለነገረው ሰው፥ “እነሆ፥ ካየኸው ለምን በምድር ላይ አልገደልኸውም? ዐሥር ብርና አንድ ድግ እሰጥህ ነበር” አለው።'),
  ('d9d27d6a-48b4-5250-aa49-f5706f189083', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 12, 12, 'ሰውየውም ኢዮአብን፥ “ንጉሡ አንተንና አቢሳን፥ ኤቲንም፦ ብላቴናውን አቤሴሎምን ጠብቁ ብሎ ሲያዝ እኛ በጆሮአችን ሰምተናልና ሺህ ሰቅል ብር በእጄ ላይ ብትመዝን እጄን በንጉሡ ልጅ ላይ አልዘረጋም ነበር።'),
  ('403a9c6f-275c-55ad-a6a1-32c7626233cd', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 13, 13, 'እኔም በሰውነቱ ላይ ክፉ ነገር ባደርግ ነገሩ በንጉሡ ዘንድ ባልተሰወረም ነበር፤ አንተም በተነሣህብኝ ነበር” አለው።'),
  ('03dc71b8-f9eb-58b6-a0b9-c8ee9fd7042d', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 14, 14, 'ኢዮአብም፥ “እኔ ከአንተ ጋር እንዲህ እዘገይ ዘንድ አልችልም” ብሎ ሦስት ጦሮች በእጁ ወሰደ፤ አቤሴሎምም ገና በዛፍ ላይ ተንጠልጥሎ ሕያው ሳለ በልቡ ላይ ተከላቸው።'),
  ('6facd2ca-1089-5520-a68d-23519d3e05f6', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 15, 15, 'ዐሥሩም የኢዮአብ ጋሻ ጃግሬዎች ከበቡት፤ አቤሴሎምንም መትተው ገደሉት።'),
  ('4a30069a-fdd1-5868-a506-62149894a937', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 16, 16, 'ኢዮአብም ሕዝቡን ስለ ራራላቸው መለከት አስነፋ፤ ሕዝቡም እስራኤልን ተከትለው እንዳያሳድዱአቸው መለሳቸው።'),
  ('7199daa2-2cf9-54de-a402-4968fad99366', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 17, 17, 'አቤሴሎምንም ወስዶ በበረሓ ባለ በታላቅ ገደል ውስጥ ጣለው፤ እጅግም ታላቅ የሆነ የድንጋይ ክምር ከመረበት፤ እስራኤልም ሁሉ ሸሽተው ወደ ድንኳናቸው ገቡ።'),
  ('e4c5443f-e513-53e0-a0c6-4d406698a967', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '8bb906a8-eb82-516a-a6c4-dfbfb5d00269', 18, 18, 'አቤሴሎምም በሕይወቱ ሳለ፥ “ለስሜ መታሰቢያ የሚሆን ልጅ የለኝም” ብሎ ሐውልት ወስዶ በንጉሥ ሸለቆ ውስጥ ለራሱ በስሙ አቁሞ ነበር፤ ያችም ሐውልት እስከ ዛሬ ድረስ “እደ አቤሴሎም” ተብላ ትጠራለች።'),
  ('e4f1bf52-e7af-5afb-ae76-360391578e3e', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 1, 19, 'የሳዶቅ ልጅ አኪማሖስ ግን፥ “እግዚአብሔር ከጠላቶቹ እጅ እንደ ፈረደለት ፈጥኜ ሄጄ ለንጉሥ የምሥራች ልንገርን?” አለ።'),
  ('fee26a01-261b-5473-a766-b518b4c3b46e', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 2, 20, 'ኢዮአብም፥ “አንተ በዚች ቀን የምሥራች የምትናገር ሰው አይደለህም፤ ወሬውን በሌላ ቀን ትናገራለህ፤ በዚች ቀን ግን የንጉሡ ልጅ እንደ ሞተ ወሬ አትናገርም” አለው።'),
  ('05875f5f-39ad-5c2c-ade7-e47d24c15dfb', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 3, 21, 'ኢዮአብም ኩሲን፥ “ሂድ፤ ያየኸውንም ሁሉ ለንጉሥ ንገር” አለው። ኩሲም ለኢዮአብ ሰግዶ ወጣ።'),
  ('9d85fb02-6766-5f0f-a223-645ed9c6b31f', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 4, 22, 'ዳግመኛም የሳዶቅ ልጅ አኪማሖስ ኢዮአብን፥ “የሆነ ሆኖ ኩሲን ተከትዬ፥ እባክህ ልሩጥ” አለው። ኢዮአብም፥ “ልጄ ሆይ፥ ለምን ትሮጣለህ? ተመለስ፤ ብትሄድ ይች ወሬ ለጥቅም አትሆንህምና” አለ።'),
  ('a4fe44d8-9178-5510-a4ae-1ded58a37117', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 5, 23, 'እርሱም፥ “እኔ ብሮጥ ምን ይገድዳል?” አለ። እርሱም፥ “ሩጥ” አለው። አኪማሖስም በሰርጥ ጎዳና በኩል ሮጠ፤ ኩሲንም ቀደመው።'),
  ('d67f647a-168c-5bb0-a3f6-3560f94b3e8e', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 6, 24, 'ዳዊትም በሁለት በር መካከል ተቀምጦ ነበር፤ ዘበኛውም በቅጥሩ ላይ ወዳለው ወደ በሩ ሰገነት ወጣ፤ ዐይኑንም አቅንቶ ብቻውን የሚሮጥ ሰው አየ።'),
  ('f640b0b4-d039-531a-a1a8-46fa78efd836', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 7, 25, 'ዘበኛውም ለንጉሡ ሊነግረው ጮኸ። ንጉሡም፥ “ብቻውን እንደ ሆነ በአፉ ወሬ ይኖራል” አለ። እርሱም ፈጥኖ ቀረበ።'),
  ('3a2d6b85-f203-5fd9-a908-0bf9b3e38a29', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 8, 26, 'ዘበኛውም ሌላ ሰው ሲሮጥ አየ፤ ዘበኛውም ለደጅ ጠባቂው ጮኾ፥ “እነሆ፥ ብቻውን የሚሮጥ ሌላ ሰው አየሁ” አለ። ንጉሡም፥ “እርሱ ደግሞ ወሬ ይዞ ይሆናል” አለ።'),
  ('089f908a-45a8-5d5a-af01-5cbd0f55fcb5', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 9, 27, 'ዘበኛውም፥ “የፊተኛው ሩጫ እንደ ሳዶቅ ልጅ እንደ አኪማሖስ ሩጫ ይመስላል” አለ፤ “ንጉሡም፦ እርሱ መልካም ሰው ነው፤ መልካምም ወሬ ያመጣል” አለ።'),
  ('9f2e6cc3-55e3-57ee-a9f6-c8f522ee657c', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 10, 28, 'አኪማሖስም ጮኾ ንጉሡን፥ “ሰላም ለአንተ ይሁን!” አለው። በንጉሡም ፊት በምድር ላይ በግንባሩ ሰግዶ፥ “በንጉሡ በጌታዬ ላይ እጃቸውን ያነሡትን ሰዎች አሳልፎ የሰጠ አምላክህ እግዚአብሔር ይመስገን” አለ።'),
  ('9d499152-f726-5abe-a2bb-3825c372ec59', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 11, 29, 'ንጉሡም፥ “ብላቴናው አቤሴሎም ደኅና ነውን?” አለ። አኪማሖስም፥ “ኢዮአብ እኔን ባሪያህንና የንጉሡን ባሪያ በላከ ጊዜ ብዙ ሰዎችን አይቻለሁ፤ ምን እንደ ሆነ ግን አላወቅሁም” ብሎ መለሰለት።'),
  ('8e6044a9-f38c-5861-ab37-dc31d35da6ff', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 12, 30, 'ንጉሡም፥ “ፈቀቅ ብለህ ቁም” አለ፤ እርሱም ፈቀቅ ብሎ ቆመ።'),
  ('682d7305-0081-50bf-a725-56730e0855ec', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 13, 31, 'እነሆም፥ ኩሲ መጣ፤ ኩሲም፥ “እግዚአብሔር በላይህ የተነሡትን ሁሉ ዛሬ እንደ ተበቀለልህ ለጌታዬ ለንጉሡ ወሬ አምጥቻለሁ” አለ።'),
  ('25a71967-028c-5a31-a080-77046058924a', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 14, 32, 'ንጉሡም ኩሲን፥ “ብላቴናው አቤሴሎም ደኅና ነውን?” አለው። ኩሲም፥ “የጌታዬ የንጉሡ ጠላቶች፥ በክፉም የተነሡብህ ሁሉ እንደዚያ ብላቴና ይሁኑ” ብሎ መለሰለት።'),
  ('d24e91be-6254-5af3-ab69-1ac021ad8606', 'b4e2740f-2d19-57b8-ad11-387851fb34e3', '60e598e1-6bfe-575c-a608-481b8b8560a5', 15, 33, 'ንጉሡም እጅግ ደነገጠ፤ በበሩም ላይ ወዳለችው ሰገነት ወጥቶ አለቀሰ፤ ሲሄድም፥ “ልጄ አቤሴሎም ሆይ፥ ልጄ፥ ልጄ አቤሴሎም ሆይ፥ በአንተ ፋንታ እኔ እንድሞት ቤዛህም እንድሆን ማን ባደረገኝ፥ ልጄ አቤሴሎም፥ ልጄ ሆይ፥” ይል ነበር።'),
  ('8cd89a4a-c991-5fb1-ac00-1e388ecb3443', '83f23ff3-0bca-55ea-a828-da67b0c541cc', '245d40d9-2a6b-5169-ae7c-fc10df37cbd9', 1, 1, 'ለኢዮአብ፥ “ንጉሡ ስለ አቤሴሎም ያዝናል፤ ያለቅሳልም” ብለው ነገሩት።'),
  ('0c8647a5-0002-589b-a463-4dfd707c3c03', '83f23ff3-0bca-55ea-a828-da67b0c541cc', '245d40d9-2a6b-5169-ae7c-fc10df37cbd9', 2, 2, 'በዚያም ቀን፥ “ንጉሡ ስለ ልጁ አዘነ” ሲባል ሕዝቡ ሰምቶአልና በዚያው ቀን ሕይወት በሕዝቡ ሁሉ ዘንድ ወደ ኀዘን ተለወጠ።'),
  ('e02d9618-7294-5550-ab3d-13325aefb964', '83f23ff3-0bca-55ea-a828-da67b0c541cc', '245d40d9-2a6b-5169-ae7c-fc10df37cbd9', 3, 3, 'ከሰልፍ በሸሸ ጊዜ ያፈረ ሕዝብ ተሰርቆ እንደሚገባ በዚያ ቀን ሕዝቡ ተሰርቀው ወደ ከተማ ገቡ።'),
  ('f24efada-a4ed-5ff3-acf1-4743fde377e4', '83f23ff3-0bca-55ea-a828-da67b0c541cc', '245d40d9-2a6b-5169-ae7c-fc10df37cbd9', 4, 4, 'ንጉሡም ፊቱን ሸፈነ፤ ንጉሡም በታላቅ ድምፅ፥ “ልጄ አቤሴሎም፥ አቤሴሎም፥ ልጄ” እያለ ይጮህ ነበር።'),
  ('efdcdada-8bf9-569b-a3f9-6ff56b800873', '83f23ff3-0bca-55ea-a828-da67b0c541cc', '245d40d9-2a6b-5169-ae7c-fc10df37cbd9', 5, 5, 'ኢዮአብም ወደ ንጉሡ ወደ ቤት ገብቶ እንዲህ አለ፥ “ዛሬ ነፍስህንና የወንዶችንና የሴቶች ልጆችህን ነፍስ፥ የሚስቶችህንና የቁባቶችህን ነፍስ ያዳኑትን የአገልጋዮችህን ሁሉ ፊት በዚች ቀን አሳፍረሃል።'),
  ('eefe625b-8f55-54d7-aeb4-6abdc2f6e9b8', '83f23ff3-0bca-55ea-a828-da67b0c541cc', '245d40d9-2a6b-5169-ae7c-fc10df37cbd9', 6, 6, 'አንተ የሚጠሉህን ትወድዳለህ፤ የሚወድዱህንም ትጠላለህ፤ አለቆችህና አገልጋዮችህ እንደማይጠቅሙህ እንደምታስብ ዛሬ ገልጠሃልና፤ አቤሴሎምም ድኖ ቢሆን ዛሬ እኛ ሁላችን እንሞት እንደ ነበር አውቃለሁ። ይህ በፊትህ ላንተ ቀና ነበረና።'),
  ('9abc17da-edc2-5a10-a3ab-1de77a61c181', '83f23ff3-0bca-55ea-a828-da67b0c541cc', '245d40d9-2a6b-5169-ae7c-fc10df37cbd9', 7, 7, 'አሁንም ተነሥተህ ወጥተህ ለአገልጋዮችህ በልባቸው የሚገባ ነገር ንገራቸው። ዛሬ ወደ እነርሱ ካልወጣህ በዚች ሌሊት አንድ ሰው ስንኳ ከአንተ ጋር የሚያድር እንዳይኖር በእግዚአብሔር እምላለሁ፤ ከሕፃንነትህ ጀምሮ እስከዚች ቀን ድረስ ካገኘህ መከራ ሁሉ ዛሬ የምታገኝህ መከራ እንድትከፋብህ እንግዲህ አንተ ለራስህ ዕወቅ” አለው።'),
  ('06ca03ab-642f-5f30-a300-7ae7234b77c3', '83f23ff3-0bca-55ea-a828-da67b0c541cc', '245d40d9-2a6b-5169-ae7c-fc10df37cbd9', 8, 8, 'ንጉሡም ተነሥቶ በበሩ ተቀመጠ፤ ሕዝቡም ሁሉ ንጉሡ በበሩ ተቀምጧል ብለው ተናገሩ፤ ሕዝቡም ሁሉ በበሩ ወደ ንጉሡ ፊት ወጡ። እስራኤልም እያንዳንዱ ወደ ድንኳኑ ሸሽቶ ገብቶ ነበር።'),
  ('a71a9e83-2c1b-530e-a302-7c24bbd1aa37', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 1, 9, 'ከመላው ነገደ እስራኤል የተሰበሰቡ ሕዝብ፥ “ንጉሡ ዳዊት ከጠላቶቻችን እጅ ታድጎናል፥ ከፍልስጥኤማውያንም እጅ አድኖናል፤ አሁንም ስለ አቤሴሎም ከሀገሩና ከመንግሥቱ ሸሸ።'),
  ('606ffb1f-eba1-5ff3-a6bb-ed911d047c4f', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 2, 10, 'በላያችን ላይ የቀባነው አቤሴሎምም በጦርነት ሞቶአል፤ አሁንም ንጉሡን ለመመለስ ስለምን ዝም ትላላችሁ?” አሉ፤ የእስራኤልም ቃል ወደ ንጉሥ ደረሰ።'),
  ('a7f70302-ef08-5af8-a221-b26f5874f5d8', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 3, 11, 'ንጉሡ ዳዊትም ለካህናቱ ለሳዶቅና ለአብያታር ልኮ እንዲህ አላቸው፥ “ለይሁዳ ሽማግሌዎች እንዲህ ብላችሁ ተናገሩአቸው፦ የእስራኤል ሁሉ ነገር ወደ ንጉሡ ደርሶአልና ንጉሡን ወደ ቤቱ ከመመለስ ስለምን ዘገያችሁ?'),
  ('7e6b0c90-aa03-50e4-aeb9-18cf49da5245', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 4, 12, 'እናንተ ወንድሞች፥ የአጥንቴ ፍላጭና የሥጋዬ ቍራጭ ናችሁ፤ እናንተ ንጉሡን ወደ ቤቱ ከመመለስ ስለምን ዘገያችሁ?'),
  ('82880513-0b9d-5690-a54d-0fa8bc2729f5', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 5, 13, 'ለአሚሳይም፦ አንተ የአጥንቴ ፍላጭና የሥጋዬ ቍራጭ አይደለህምን? በዘመንህም ሁሉ በኢዮአብ ፋንታ በፊቴ የሠራዊት አለቃ ሳትሆን ብትቀር ዛሬ እግዚአብሔር ይህን ያድርግብኝ፤ ይህንም ይጨምርብኝ በሉት።”'),
  ('f2ed4c9e-5ae7-5721-a8c9-67b3b89be71f', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 6, 14, 'የይሁዳንም ሰዎች ሁሉ ልብ እንደ አንድ ሰው ልብ አድርጎ አዘነበለ፤ ወደ ንጉሡም፥ “አንተና ብላቴኖችህ፥ አገልጋዮችህም ሁሉ ተመለሱ” ብለው ላኩበት።'),
  ('b1892feb-b287-5ca8-a4b8-bc4c2531aba0', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 7, 15, 'ንጉሡም ተመልሶ እስከ ዮርዳኖስ ድረስ መጣ። የይሁዳ ሰዎችም ንጉሡን ሊቀበሉ፥ ንጉሡንም ዮርዳኖስን ሊያሻግሩ ወደ ጌልገላ መጡ።'),
  ('540401e9-6335-5fee-a70d-597fc3bf57c6', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 8, 16, 'ከባውሪም ሀገር የነበረው የኢያሚን ልጅ የጌራ ልጅ ሳሚም ከይሁዳ ሰዎች ጋር ንጉሥ ዳዊትን ሊቀበል ፈጥኖ ወረደ።'),
  ('76a189da-07fa-5b38-adcc-7b73fd80afa4', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 9, 17, 'ከእርሱም ጋራ ከብንያም ወገን የሆኑ ሺህ ሰዎች ነበሩ፤ የሳኦልም ቤት አገልጋይ ሲባ ከእርሱም ጋር ዐሥራ አምስቱ ልጆቹና ሃያው አገልጋዮቹ ነበሩ፤ በንጉሡም ፊት በቀጥታ ወደ ዮርዳኖስ ሄዱ።'),
  ('e6fbcbc4-6a49-562e-a68e-f68c2f8984c9', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd62ffa17-9f5a-5a45-aaae-063ef4beb798', 10, 18, 'ንጉሡንም የማሻገር ሥራ ሠሩ። የንጉሡንም ቤተ ሰብእ ያነሡ ዘንድ፥ በፊቱም የቀና ሥራን ይሠሩ ዘንድ ወደ ማዶ ተሻገሩ። ንጉሡም ዮርዳኖስን ከተሻገረ በኋላ የጌራ ልጅ ሳሚ በንጉሡ ፊት፦ በግንባሩ ወደቀ።'),
  ('92d0372e-a9d7-56d2-a022-fab46a52db32', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd0dd8a72-3a07-56ec-ab27-ec9ca585ecac', 1, 19, 'እርሱም ንጉሡን አለው፥ “ጌታዬ! ኀጢአቴን አትቍጠርብኝ፤ ጌታዬ ንጉሡ ከኢየሩሳሌም በወጣህ ቀን ባሪያህ የበደልሁህን አታስብብኝ፤ ጌታዬ ንጉሡም በልብህ አታኑርብኝ።'),
  ('a9d7eee4-55fe-5458-a751-77cc9bde4d5b', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd0dd8a72-3a07-56ec-ab27-ec9ca585ecac', 2, 20, 'እኔ አገልጋይህ በደለኛ እንደ ሆንሁ አውቄአለሁና እነሆ፥ ከዮሴፍ ቤት ሁሉ አስቀድሜ ዛሬ መጣሁ፤ ጌታዬንም ንጉሡን ልቀበል ወረድሁ።”'),
  ('0594b23a-c588-5a15-afc2-2c3e359bf424', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd0dd8a72-3a07-56ec-ab27-ec9ca585ecac', 3, 21, 'የሶርህያ ልጅ አቢሳ ግን፥ “ሳሚ እግዚአብሔር የቀባውን ሰድቦአልና እንግዲህ ሞት የተገባው አይደለምን?” ብሎ መለሰ።'),
  ('8c2e5fa6-c3e7-5549-a039-6e79f5803810', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd0dd8a72-3a07-56ec-ab27-ec9ca585ecac', 4, 22, 'ዳዊትም፥ “እናንተ የሶርህያ ልጆች! ዛሬ ታስቱኝ ዘንድ በእኔና በእናንተ መካከል ምን አለኝ? ዛሬስ ከእስራኤል የሚሞት አንድ ሰው የለም። ዛሬስ በእስራኤል ላይ እንደ ነገሥሁ አላውቅምን?”'),
  ('62f8b9aa-33bf-5972-ac01-33b5c82a13aa', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'd0dd8a72-3a07-56ec-ab27-ec9ca585ecac', 5, 23, 'ንጉሡም ሳሚን፥ “አትሞትም” አለው። ንጉሡም ማለለት።'),
  ('a8abbe90-8fea-5de4-aa77-2704e519834c', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 1, 24, 'የሳኦልም የልጅ ልጅ ሜምፌቡስቴ ንጉሡን ሊቀበል ወረደ፤ ንጉሡም ከሄደበት ቀን ጀምሮ በሰላም እስከ ተመለሰበት ቀን ድረስ እግሩን አላነጻም፤ ጥፍሩንም አልቈረጠም፤ ጢሙንም አልላጨም፤ ልብሱንም አላጠበም ነበር።'),
  ('23794baf-589f-5601-a958-4263b021c401', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 2, 25, 'ከዚህም በኋላ ንጉሡን ሊቀበለው ከኢየሩሳሌም በመጣ ጊዜ ንጉሡ፥ “ሜምፌቡስቴ፥ ከእኔ ጋር ስለምን አልወጣህም?” አለው።'),
  ('93825aaa-70b0-5868-a1fe-d746c5959070', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 3, 26, 'ሜምፌቡስቴም አለ፥ “ጌታዬ፥ ንጉሥ፥ አገልጋዬ አታለለኝ፥ እኔ ባሪያህ አንካሳ ነኝና፦ ከንጉሡ ጋር እሄድ ዘንድ አህያዬን ጫንልኝ፤ እኔም እቀመጥበታለሁ አልሁት።'),
  ('7a9610b4-7572-508e-a4eb-e348affbe3f5', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 4, 27, 'እርሱም በእኔ በባሪያህ ላይ ክፉ አደረገ፤ አንተ ጌታዬ ንጉሥ ግን እንደ እግዚአብሔር መልአክ ነህ፤ በፊትህም ደስ ያሰኘህን አድርግ።'),
  ('95e02637-73ba-5d77-abf9-05d2827757e6', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 5, 28, 'የአባቴ ቤት ሁሉ በጌታዬ በንጉሥ ዘንድ ሞት የሚገባቸው ነበሩ፤ አንተ ግን እኔን ባሪያህን በገበታህ በሚበሉ መካከል አስቀመጥኸኝ፤ ለንጉሥ ደግሞ ለመናገር ምን መብት አለኝ?”'),
  ('9a554ee0-a5a9-5431-a7f2-2340fac75eed', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 6, 29, 'ንጉሡም፥ “ነገርህን ለምን ታበዛለህ? አንተና ሲባ የሳኦልን እርሻውን ትካፈሉ ዘንድ ብያለሁ” አለው።'),
  ('7ca8e034-471e-57ac-a86d-60d590e388c3', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 7, 30, 'ሜምፌቡስቴም ንጉሡን፥ “ጌታዬ ንጉሡ በደኅና ወደ ቤቱ ከተመለሰ እርሱ ሁሉን ይውሰደው” አለው።'),
  ('8fdd9c17-127e-5181-a2d7-e512c8b8b288', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 8, 31, 'ገለዓዳዊውም ቤርዜሊ ከሮግሊም ወረደ፤ በዮርዳኖስም ሊሸኘው ከንጉሡ ጋር ዮርዳኖስን ተሻገረ።'),
  ('607c9a1e-a215-5578-ae87-82ef4f1598f9', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 9, 32, 'ቤርዜሊም እጅግ ያረጀ የሰማንያ ዓመት ሽማግሌ ነበረ፤ እጅግም ትልቅ ሰው ነበረና ንጉሡ በመናሄም ሳለ ይቀልበው ነበር።'),
  ('f30bd0ee-81ef-56a3-a2f5-04069a6ba017', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 10, 33, 'ንጉሡም ቤርዜሊን፥ “አንተ ከእኔ ጋር ዮርዳኖስን ትሻገራለህ፤ በኢየሩሳሌምም ያረጀ ሰውነትህን ከእኔ ጋር እጦረዋለሁ” አለው።'),
  ('8855922d-caed-5d1a-a685-2fa9e27c1ca4', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 11, 34, 'ቤርዜሊም ንጉሡን አለው፥ “ከንጉሡ ጋር ወደ ኢየሩሳሌም እወጣ ዘንድ ከሕይወቴ ዘመን ምን ያህል ቀረኝ?'),
  ('d861b957-e721-545d-a6db-80fcdf4d5a2f', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 12, 35, 'ዛሬ የሰማንያ ዓመት ሽማግሌ ነኝ፥ መልካሙንና ክፉውን መለየት እችላለሁን? እኔ ባሪያህ የምበላውንና የምጠጣውን ጣዕሙን መለየት እችላለሁን? የወንዱንና የሴቲቱን ዘፈን ድምፅ መስማትስ እችላለሁን? እኔ ባሪያህ በጌታዬ በንጉሡ ላይ ለምን እከብድብሃለሁ?'),
  ('4b437065-7ec0-5884-a536-845646a4e3d8', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 13, 36, 'እኔ ባሪያህ ዮርዳኖስን ተሻግሬ ከንጉሡ ጋር ጥቂት ልሄድ ነበር፤ ንጉሡ እንዲህ ያለ ወረታ ለምን ይመልስልኛል?'),
  ('3cb5be45-7bc7-5527-adc6-3e8e60420ceb', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 14, 37, 'እኔ ባሪያህ ተመልሼ በከተማዬ በአባቴና በእናቴ መቃብር አጠገብ እባክህ! ልሙት፤ ነገር ግን ባሪያህ ከመዓም ከጌታዬ ከንጉሡ ጋር ይሻገር፤ በዐይኖችህ ፊት ደስ የሚያሰኝህንም ለእርሱ አድርግ።”')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c41b6a45-7e34-56bf-a1b3-c6cde298331f', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 15, 38, 'ንጉሡም፥ “ከመዓም ከእኔ ጋር ይሻገር፤ በፊቴ ደስ የሚያሰኘኝንም አደርግለታለሁ፤ አንተም ከእኔ የምትሻውን ነገር ሁሉ አደርግልሃለሁ” አለው።'),
  ('d027b8eb-9f48-585a-a8ef-e4faac0807a7', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 16, 39, 'ሕዝቡም ሁሉ ዮርዳኖስን ተሻገሩ፤ ንጉሡም ዮርዳኖስን ተሻገረ፤ ንጉሡም ቤርዜሊን አቅፎ ሳመው፤ መረቀውም፤ ወደ ስፍራውም ተመለሰ።'),
  ('de072346-0d00-5ece-abbd-47aa7183a1fb', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 17, 40, 'ንጉሡም ወደ ጌልገላ ተሻገረ፤ ከመዓምም ከእርሱ ጋር ተሻገረ፤ የይሁዳም ሕዝብ ሁሉ፥ ደግሞም የእስራኤል ሕዝብ እኩሌታ ከንጉሡ ጋር ተሻገሩ።'),
  ('0d029ad9-22e1-5cc5-abfd-ac9bf96cf0b5', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 18, 41, 'እነሆም፥ የእስራኤል ሰዎች ሁሉ ወደ ንጉሡ መጡ፤ ንጉሡንም፥ “ወንድሞቻችን የይሁዳ ሰዎች ለምን ሰረቁህ? ንጉሡንም ቤተ ሰቡንም ዮርዳኖስን አሻገሩ። የዳዊትም ሰዎች ሁሉ ከእርሱ ጋር ነበሩ” አሉት።'),
  ('0ef787ab-b04b-514d-a483-36d0e30879b2', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 19, 42, 'የይሁዳም ሰዎች ሁሉ ለእስራኤል ሰዎች መልሰው፥ “ንጉሡ ለእኛ ቅርባችን ነው፤ ስለምን በዚህ ነገር ትቈጣላችሁ? በውኑ ከንጉሡ አንዳች በልተናልን? ወይስ እርሱ በረከት ሰጥቶናልን? ወይስ ጭፍራ አድርጎ ሾመንን?” አሉ።'),
  ('6dfda688-01b5-5ea1-a185-8a8d9146e0f3', '83f23ff3-0bca-55ea-a828-da67b0c541cc', 'f2b7369b-8784-566f-a7d4-4751f0875c52', 20, 43, 'የእስራኤልም ሰዎች ለይሁዳ ሰዎች መልሰው፥ “በንጉሡ ዘንድ ለእኛ ዐሥር ክፍል አለን፤ ከእናንተም እኛ እንቀድማለን፤ እኛም በኵር ነን፤ ለዳዊትም ከእናንተ እኛ እንቀርባለን፤ ስለምን ናቃችሁን? ንጉሡንስ እንመልሰው ዘንድ ከእናንተ የእኛ ቃል አይቀድምምን?” አሏቸው። የይሁዳም ሰዎች ቃል ከእስራኤል ሰዎች ቃል ይልቅ ጠነከረ።'),
  ('d70f6d67-43e3-5003-a7ec-b7da2877bf80', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 1, 1, 'በዚያም አንድ ብንያማዊ የቢኮሪ ልጅ ስሙ ሳቡሄ የሚባል የዐመፅ ልጅ የሆነ ሰው ነበረ፤ እርሱም፥ “ከዳዊት ዘንድ እድል ፋንታ የለንም፦ ከእሴይም ልጅ ዘንድ ርስት የለንም፤ እስራኤል ሆይ፥ እያንዳንድህ ወደ ድንኳንህ ተመለስ” ብሎ መለከት ነፋ።'),
  ('3dbe3481-bd4e-54f7-a56b-804b8df06ed4', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 2, 2, 'የእስራኤልም ሰዎች ሁሉ ከዳዊት ተለይተው የቢኮሪ ልጅ ሳቡሄን ተከትለው ሄዱ፤ የይሁዳ ሰዎች ግን ከዮርዳኖስ ጀምረው ኢየሩሳሌም እስኪደርሱ ንጉሣቸውን ተከተሉ።'),
  ('0f82a902-3b04-5795-adc7-f3615f8e620a', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 3, 3, 'ዳዊትም ወደ ኢየሩሳሌም ወደ ቤቱ መጣ፤ ንጉሡም ቤቱን ሊጠብቁ የተዋቸውን ዐሥሩን ቁባቶች ወስዶ ለጠባቂ ሰጣቸው፤ ቀለብም ሰጣቸው፤ ነገር ግን ወደ እነርሱ አልገባም፤ በቤትም ተዘግተው እስኪሞቱ ድረስ መበለቶች ሆነው ተቀመጡ።'),
  ('d7ebaf21-9041-5f7a-a565-ff90e9d23fef', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 4, 4, 'ንጉሡም አሜሳይን፥ “የይሁዳን ሰዎች ሁሉ በሦስት ቀን ውስጥ ጥራልኝ፤ አንተም አብረህ በዚህ ሁን” አለው።'),
  ('37647dcc-5243-5f34-af4c-0c9acdf0602b', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 5, 5, 'አሜሳይም የይሁዳን ሰዎች ሁሉ ይጠራ ዘንድ ሄደ፤ ነገር ግን ዳዊት የቀጠረውን ቀን አሳልፎ ዘገየ።'),
  ('dca44ad2-88b1-51a6-ab41-fdfc94eb19d7', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 6, 6, 'ዳዊትም አቢሳን፥ “አሁን አቤሴሎም ከአደረገብን ይልቅ የከፋ የሚያደርግብን የቢኮሪ ልጅ ሳቡሄ ነው፤ እርሱ የተመሸጉትን ከተሞች አግኝቶ ከዐይናችን እንዳይሰወር፥ አንተ የጌታህን ብላቴኖች ወስደህ አሳድደው” አለው።'),
  ('c0da396e-8f6a-5a98-a1e3-507a66a89def', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 7, 7, 'አቢሳና የኢዮአብ ሰዎች ከሊታውያንም፥ ፈሊታውያንም፥ ኀያላኑም ሁሉ ወጥተው ተከተሉት፤ ከኢየሩሳሌምም ወጥተው የቢኮሪ ልጅ ሳቡሄን አሳደዱት።'),
  ('b53c2e52-ba8b-5a11-ac67-3ebec37fc9e8', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 8, 8, 'በገባዖንም ወዳለው ወደ ታላቁ ድንጋይ በደረሱ ጊዜ አሜሳይ በፊታቸው መጣ፤ ኢዮአብም የሰልፍ ልብስ ለብሶ ነበር፤ በላዩም መታጠቂያ ነበረ፤ በወገቡም ላይ ሰገባ ያለው ሰይፍ ታጥቆ ነበር፤ እርሱም ሲራመድ ሰይፉ ወደቀ።'),
  ('63f54e3d-f816-59b4-acab-c43fa8453727', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 9, 9, 'ኢዮአብም አሜሳይን፥ “ወንድሜ ሆይ፥ ደኅና ነህን?” አለው፤ ኢዮአብም አሜሳይን የሚስም መስሎ በቀኝ እጁ ጢሙን ያዘው።'),
  ('f71f70b4-3de1-56d1-ac1a-c438523f967b', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 10, 10, 'አሜሳይ ግን በኢዮአብ እጅ ከነበረው ሰይፍ አልተጠነቀቀም ነበር፤ ኢዮአብም ሆዱን ወጋው፤ አንጀቱንም በምድር ላይ ዘረገፈው፤ ሁለተኛም አልወጋውም፤ ሞተም። ኢዮአብና ወንድሙ አቢሳም የቢኮሪን ልጅ ሳቡሄን አሳደዱ።'),
  ('83ad829e-304d-5a16-a950-1727fee41843', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 11, 11, 'ከኢዮአብም ብላቴኖች አንዱ በአሜሳይ ሬሳ አጠገብ ቆሞ፥ “ኢዮአብ የሚፈልገው ምንድን ነው? የዳዊትም የሆኑ ኢዮአብን የሚከተሉ እነማን ናቸው?” አለ።'),
  ('91fdd0d5-ea97-58fa-a0f9-9a2c9cdc7f3f', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 12, 12, 'አሜሳይም በደም ተነክሮ በመንገድ መካከል ወድቆ ነበር፤ ያም ሰው ወደ እርሱ የሚመጣ ሁሉ ሲቆም አይቶአልና ሕዝቡ ሁሉ እንደ ቆመ ባየ ጊዜ አሜሳይን ከመንገድ ላይ ወደ እርሻ ውስጥ ፈቀቅ አደረገው፤ በልብስም ከደነው።'),
  ('cd455409-e4df-5437-a910-c5dfa159bef8', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 13, 13, 'ከመንገድም ፈጥኖ ራቅ ባለ ጊዜ የእስራኤል ሰው ሁሉ የቢኮሪን ልጅ ሳቡሄን ለማሳደድ ኢዮአብን ተከትሎ ያልፍ ነበር።'),
  ('4d344134-969c-5307-a08e-db45dbcaea8a', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 14, 14, 'እርሱ ግን ከእስራኤል ነገድ ሁሉ ወደ አቤል፥ ወደ ቤተማካም ሁሉ አለፈ፤ በካሪ ያሉ ሰዎችም ሁሉ ደግሞ ተሰብስበው ተከተሉት።'),
  ('2bfd75f4-49bd-5c99-a31b-c071fbfc41bc', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 15, 15, 'በቤተ ማካና በአቤልም መጥተው ከበቡት፤ በከተማዪቱም ላይ እስከ ቅጥርዋ ድረስ የአፈርን ድልድል ደለደሉ፤ እነርሱም ከአጥሩ ቀጥሎ ቆሙ፤ ቅጥሩንም ያፈርሱ ዘንድ ከኢዮአብ ጋር የነበሩ ሕዝብ ሁሉ ተስማሙ።'),
  ('c5fe3660-e26a-52fb-af78-6f0d395397c8', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 16, 16, 'ከቅጥሩም አንዲት ብልሃተኛ ሴት፥ “ስሙ፥ ስሙ፥ ኢዮአብንም፦ እነግርህ ዘንድ ወደዚህ ቅረብ በሉት” ስትል ጮኸች። ወደ እርስዋም ቀረበ፤'),
  ('da1289c2-233c-5a2e-ac75-56d45060ee25', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 17, 17, 'ሴቲቱም፥ “ኢዮአብ አንተ ነህን?” አለችው። እርሱም፥ “እኔ ነኝ” ብሎ መለሰላት። እርስዋም፥ “የባሪያህን ቃል ስማ” አለችው። ኢዮአብም፥ “እሰማለሁ” አላት።'),
  ('d019a6aa-1c30-5f79-aac2-437927a95bc2', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 18, 18, 'እርስዋም እንዲህ አለች፥ “የቀደሙ ሰዎች በእስራኤል ዘንድ አማኞች በሚያስቡት ነገር ተሳስተው እንደ ሆነ በአቤልና በዳን በእውነት ይጠይቁ ይባል ነበር፤ በርግጥም በዚህ ዐይነት ነገር ከተሳሳቱ በአቤል ይጠይቁ ነበር።'),
  ('c0525184-9db7-58fd-aa3e-1d92943c0153', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 19, 19, 'በእስራኤል ኀያላን ዘንድ ሰላምን ከሚወድዱት አንድዋ ነኝ፤ አንተ ግን በእስራኤል ያለችውን ከተማና እናት ከተማን ለማፍረስ ትሻለህ፤ ስለምንስ የእግዚአብሔርን ርስት ታጠፋለህ?”'),
  ('5c735e64-19df-50ef-a972-86a37b125c5e', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 20, 20, 'ኢዮአብም መልሶ፥ “ይህ ማፍረስና ማጥፋት ከእኔ ይራቅ፤'),
  ('2b6ae276-aa18-52ef-a7a0-dc476b09b748', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 21, 21, 'ነገሩ እንዲህ አይደለም፤ ከተራራማው ከኤፍሬም ሀገር የሚሆን የቢኮሪ ልጅ ሳቡሄ የሚባል አንድ ሰው ግን በንጉሡ በዳዊት ላይ እጁን አነሣ፤ እርሱን ብቻውን ስጡኝ፤ እኔም ከከተማዪቱ እርቃለሁ” አላት። ሴቲቱም ኢዮአብን፥ “እነሆ፥ ራሱ ከቅጥር ላይ ይጣልልሃል” አለችው።'),
  ('2ba34c00-0ad8-57b9-aa5c-726921108314', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', '1e0de4e1-93ac-5673-aa0f-242cc9ffbb32', 22, 22, 'ያቺም ሴት ወደ ሕዝቡ ሁሉ ገብታ ለከተማው ሕዝብ ሁሉ በብልሀት ነገረቻቸው፤ የቢኮሪን ልጅ የሳቡሄን ራስ ቈርጠው ሰጡአት፤ ወደ ኢዮአብም ጣለችው። ኢዮአብም መለከቱን ነፋ፤ ሰውም ሁሉ ከከተማዪቱ ርቆ እያንዳንዱ ወደ ድንኳኑ ሄደ። ኢዮአብም ወደ ንጉሡ ወደ ኢየሩሳሌም ተመለሰ።'),
  ('c0a2beb7-94fa-5cd8-a7ea-1463bc9fef71', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', 'b640b1e5-25f3-51c1-a17b-3696753a087e', 1, 23, 'ኢዮአብም በእስራኤል ሠራዊት ሁሉ ላይ አለቃ ነበረ፤ የዮዳሄም ልጅ በናያስ በከሊታውያንና በፈሊታውያን ላይ አለቃ ነበረ፤'),
  ('505500b3-8194-51e3-a3fa-919b36831ff0', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', 'b640b1e5-25f3-51c1-a17b-3696753a087e', 2, 24, 'አዶኔራምም ግብር አስገባሪ ነበረ፤ የአኪሎትም ልጅ ኢዮሳፍጥ ታሪክ ጸሓፊ ነበረ፤'),
  ('f500f66b-8fbe-59f3-a589-7b7a7d2052b0', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', 'b640b1e5-25f3-51c1-a17b-3696753a087e', 3, 25, 'ሱሳም ጸሓፊ ነበረ፤ ሳዶቅና አብያታርም ካህናት ነበሩ፤'),
  ('6f78964c-abab-524e-a6b5-1d2b436710da', 'd1d88a47-f2ea-58be-afcc-9d9c1f4e0e28', 'b640b1e5-25f3-51c1-a17b-3696753a087e', 4, 26, 'የኢያዕር ሰው ኢራስም ለዳዊት ካህን ነበረ።'),
  ('f48c2774-947d-5fcd-a7a4-b0a7acd2d2e3', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 1, 1, 'በዳዊትም ዘመን ሦስት ዓመት ያህል በተከታታይ ራብ ሆነ፤ ዳዊትም የእግዚአብሔርን ቃል ጠየቀ። እግዚአብሔርም አለ፥ “የገባዖንን ሰዎች ስለ ገደለ በሳኦልና በቤቱ ላይ ደም አለበት፥”'),
  ('1aa08ab6-a28f-5777-a53c-87daee782f94', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 2, 2, 'ንጉሡ ዳዊትም የገባዖንን ሰዎች ጠራ፤ የገባዖን ሰዎችም ከአሞራውያን የተረፉ ነበሩ እንጂ ከእስራኤል ልጆች ወገን አልነበሩም፤ የእስራኤልም ልጆች ምለውላቸው ነበር፤ ሳኦል ግን ለእስራኤል ልጆችና ለይሁዳ ስለ ቀና ሊገድላቸው ወድዶ ነበር።'),
  ('e6d36559-5f2f-5270-a113-97d36d0b0b76', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 3, 3, 'ዳዊትም የገባዖንን ሰዎች፥ “የእግዚአብሔርን ርስት ትባርኩ ዘንድ ምን ላድርግላችሁ? ማስተስረያውስ ምንድን ነው?” አላቸው።'),
  ('6941d05c-0602-51e2-adc1-be7ed894ad20', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 4, 4, 'የገባዖን ሰዎችም፥ “ከሳኦልና ከቤቱ ወርቅ ወይም ብር አንፈልግም፤ ከእስራኤልም ወገን እኛ የምንገድለው የለም” አሉት።'),
  ('c83af26d-33f0-5af1-a5f1-588143165d4c', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 5, 5, 'እርሱም፥ “ምን ትላላችሁ? ተናገሩ፤ እኔም አደርግላችኋለሁ” አላቸው፤ እነርሱም ለንጉሡ አሉት፥ “በእኛ ላይ ክፉ ያደረገውን፥ ያሳደደንንና ሊያጠፋን ያሰበውን ሰው እናጥፋው፤ እርሱም በእስራኤል ዳርቻ እንዳይቆም እናደርገዋለን።'),
  ('efe5417d-d844-5f42-a870-47e896257d8a', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 6, 6, 'ከልጆቹ ሰባት ሰዎች ስጠንና ከእግዚአብሔር በተመረጠው በሳኦል ሀገር በገባዖን ለእግዚአብሔር እንሠቅላቸዋለን።” ንጉሡም፥ “እሰጣችኋለሁ” አለ።'),
  ('7944307e-1c6b-593b-a2c8-8e5e0759cdb7', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 7, 7, 'ንጉሡም በእነርሱ መካከል፥ በዳዊትና በሳኦል ልጅ በዮናታን መካከል ስለ ነበረው ስለ እግዚአብሔር መሐላ የሳኦልን ልጅ የዮናታንን ልጅ ሜምፌቡስቴን ራራለት።'),
  ('c480840a-2554-52f1-a320-361b07118257', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 8, 8, 'ንጉሡም ለሳኦል የወለደቻቸውን የኢዮሄልን ልጅ የሩጻፋን ሁለቱን ልጆች ሄርሞንስቴንና ሜምፌቡስቴን፥ ለመሓላታዊውም ለቤርዜሊ ልጅ ለኤስድራ የወለደቻቸውን የሳኦልን ልጅ የሜሮብን አምስቱን ልጆች ወሰደ፤'),
  ('500fca14-dda2-5ff7-a33f-4419359f1673', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 9, 9, 'በገባዖንም ሰዎች እጅ አሳልፎ ሰጣቸው፤ በእግዚአብሔርም ፊት በተራራው ላይ ሰቀሏቸው። ሰባቱም በአንድነት ወደቁ፤ እህል በሚታጨድበትም ወራት በገብሱ መከር መጀመሪያ ተገደሉ።'),
  ('6945d7bb-2c6e-5eac-a371-7b296e6a00fa', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 10, 10, 'የኢዮሔል ልጅ ሩጻፋም ማቅ ወስዳ ከመከር ወራት ጀምሮ ዝናብ ከሰማይ እስኪዘንብ ድረስ በድንጋይ ላይ ዘረጋችው፤ በቀንም የሰማይ ወፎች፥ በሌሊትም የዱር አራዊት ያርፉባቸው ዘንድ አልተወችም።'),
  ('f4433a7d-229a-5ada-ac97-a45caceb3ad6', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 11, 11, 'የሳኦልም ዕቅብት የኢዮሔል ልጅ ሩጻፋ ያደረገችውን ለዳዊት ነገሩት።'),
  ('f2674777-95d1-5423-ab13-91c8e267c4f6', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 12, 12, 'ዳዊትም ሄደ፤ ሳአልንም በጌላቡሄ በገደሉት ጊዜ ፍልስጥኤማውያን ከሰቀሉአቸው ስፍራ ከቤትሳን አደባባይ ከሰረቁት ከኢያቤስ ገለዓድ ሰዎች የሳኦልን አጥንትና የልጁን የዮናታንን አጥንት ወሰደ።'),
  ('d67cb01f-031a-5711-a991-05d9b3bd2d1a', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 13, 13, 'ከዚያም የሳኦልን አጥንትና የልጁን የዮናታንን አጥንት አመጣ፤ የተሰቀሉትንም ሰዎች አጥንት ሰበሰቡ።'),
  ('464aa7f8-1045-5619-a0d2-b822c89a2a8d', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '3a6d95e2-1712-5b68-af6b-3dfd8829dac9', 14, 14, 'የሳኦልን አጥንትና የልጁን የዮናታንን አጥንት፥ የተሰቀሉትንም ሰዎች አጥንት በብንያም በአባቱ በቂስ መቃብር አጠገብ ቀበሩአቸው፤ ንጉሡም ያዘዘውን ሁሉ አደረጉ። ከዚያም በኋላ እግዚአብሔር ምድርን ሰማት።'),
  ('24f4180b-80b1-58c1-a318-d84900289772', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '169da7bf-3cc3-55ac-a813-bb6c62ca8a14', 1, 15, 'በፍልስጥኤማውያንና በእስራኤልም መካከል ደግሞ ጦርነት ሆነ፤ ዳዊትም፥ ከእርሱም ጋር አገልጋዮቹ ወረዱ፤ ከፍልስጥኤማውያንም ጋር ተዋጉ፤ ዳዊትም ደከመ።'),
  ('da82baef-973d-51b5-af02-795540c8a331', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '169da7bf-3cc3-55ac-a813-bb6c62ca8a14', 2, 16, 'ከራፋይም ወገን የነበረው ኤስቢ መጣ፤ የጦሩም ሚዛን ክብደት ሦስት መቶ ሰቅል ናስ ነበር። አዲስ የጦር መሣሪያም ታጥቆ ነበር፤ ዳዊትንም ሊገድለው ፈለገ።'),
  ('df7c5781-a39d-590f-ab60-56f0384f0958', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '169da7bf-3cc3-55ac-a813-bb6c62ca8a14', 3, 17, 'የሶርህያም ልጅ አቢሳ አዳነው፤ ፍልስጥኤማዊውንም ወግቶ ገደለው። ያንጊዜም የዳዊት ሰዎች፥ “አንተ የእስራኤል መብራት እንዳትጠፋ ከእንግዲህ ወዲህ ከእኛ ጋር ለሰልፍ አትወጣም” ብለው ማሉለት።'),
  ('6730ac72-71af-5ca8-add6-7d1e7244c00a', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '169da7bf-3cc3-55ac-a813-bb6c62ca8a14', 4, 18, 'ከዚህም በኋላ እንደ ገና በጎብ ላይ ከፍልስጥኤማውያን ጋር ጦርነት ሆነ፤ ያን ጊዜም አስጣጦታዊው ሴቤኮይ ከራፋይም ወገን የሆነውን ሳፍን ገደለው።'),
  ('7255b422-c766-59c4-abb2-5e53ba5dbdff', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '169da7bf-3cc3-55ac-a813-bb6c62ca8a14', 5, 19, 'ደግሞም በሮም ከፍልስጥኤማውያን ጋር ጦርነት ሆነ፤ የቤተልሔማዊውም የዓሬኦርጌም ልጅ ኤልያናን የጦሩ የቦ እንደ ሸማኔ መጠቅለያ የነበረውን የጌት ሰው ጎዶልያን ገደለው።'),
  ('20abf278-c7ed-5078-a335-5fc7afb062c5', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '169da7bf-3cc3-55ac-a813-bb6c62ca8a14', 6, 20, 'ደግሞም በጌት ላይ ጦርነት ሆነ፤ በዚያም በእጁና በእግሩ ስድስት ስድስትሁላሁሉ ሃያ አራት ጣቶች የነበሩት አንድ ረዥም ሰው ነበረ፤ እርሱ ደግሞ ከራፋይም የተወለደ ነበረ።'),
  ('ff5921af-5939-507d-a61e-891413928426', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '169da7bf-3cc3-55ac-a813-bb6c62ca8a14', 7, 21, 'እስራኤልንም በተገዳደረ ጊዜ የዳዊት ወንድም የሴማይ ልጅ ዮናታን ገደለው።'),
  ('dd18bbf9-76a8-5629-a10f-5c799b43047f', 'b6d2d98e-0fd0-5481-acd7-0b67e5f92a86', '169da7bf-3cc3-55ac-a813-bb6c62ca8a14', 8, 22, 'እነዚያም አራቱ በጌት ውስጥ ከረዐይት የተወለዱ የራፋይም ወገኖች ነበሩ፤ በዳዊትም እጅ በአገልጋዮቹም እጅ ወደቁ።'),
  ('28d00524-f551-5dd7-a760-db599b77df70', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 1, 1, 'ዳዊትም እግዚአብሔር ከሳኦል እጅና ከጠላቶቹ ሁሉ እጅ ባዳነው ቀን የዚህን መዝሙር ቃል ለእግዚአብሔር ተናገረ።'),
  ('8d86c636-189a-5500-a69e-6633801340de', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 2, 2, 'እንዲህም አለ፥ “እግዚአብሔር ዓለቴ፥ አምባዬም፥ መድኀኒቴም ነው፤'),
  ('420b19ea-a996-5f5f-a14d-d335d725f496', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 3, 3, 'እግዚአብሔር ጠባቂዬ ነው፤ በእርሱም እታመናለሁ፤'),
  ('1f15f0ed-da8c-5895-ac57-a9712044adda', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 4, 4, 'ምስጋና የሚገባውን እግዚአብሔርን እጠራለሁ፤'),
  ('c111cfc7-1852-549a-a30e-03a5fc1a16b0', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 5, 5, 'የሞት ጭንቅ ያዘኝ፤'),
  ('91cd5e14-f57b-51c8-a529-d3145175f179', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 6, 6, 'የሞት ጣር ከበበኝ፤'),
  ('ec4bb768-eb74-598e-aa25-568d296dd1af', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 7, 7, 'በጨነቀኝ ጊዜ እግዚአብሔርን ጠራሁት፤'),
  ('6a486a85-4ad8-5461-a7ab-a58b4219c05f', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 8, 8, 'ምድርም ተንቀጠቀጠች፤ ተናወጠችም፤'),
  ('c5a4c2e2-632e-5822-aa48-0d83afb86c35', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 9, 9, 'ከቍጣው ጢስ ወጣ፤'),
  ('1f7ddffe-483b-5ade-a6e8-6578d2b05f75', '47682b38-860f-5837-af8b-c176d86ecbad', 'f62a5499-d6fe-5102-af39-5d7d6e5feae5', 10, 10, 'ሰማዮችን አዘነበለ፤ ወረደም፤'),
