  ('b710a653-ecf0-55be-ae2f-c1b8614ca21f', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 1, 8, 'የዳዊት ኀያላን ስም ይህ ነው። የሦስተኛው ክፍል አለቃ የሆነ ከነዓናዊው ኢያቡስቴ ነበረ፤ ጎራዴውን መዝዞ ስምንት መቶ ያህል ጭፍሮችን በአንድ ጊዜ የገደለ አሶናዊው አዲኖን ነበረ።'),
  ('57c20e05-991b-5c3e-a1f8-6dd01f55d029', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 2, 9, 'ከእርሱም በኋላ የዳዊት የአጎቱ ልጅ የዱዲ ልጅ ኤልያናን ነበረ፤ ለሰልፍ የተሰበሰቡትን ፍልስጥኤማውያንን በተገዳደሩ ጊዜ ከዳዊት ጋር ከነበሩ ከሦስቱ ኀያላን አንዱ እርሱ ነበረ፤ የእስራኤልም ሰዎች ተመለሱ።'),
  ('d72d7271-702b-5e56-a509-dc6198519f7d', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 3, 10, 'የእስራኤልም ሰዎች በጮኹ ጊዜ እርሱ ተነሥቶ እጁ እስከሚደክምና ከሰይፉ ጋር እስኪጣበቅ ድረስ ፍልስጥኤማውያንን መታ፤ በዚያም ቀን እግዚአብሔር ታላቅ መድኀኒት አደረገ፤ ሕዝቡም ከእርሱ በኋላ የሞቱትን ለመግፈፍ ብቻ ተመለሱ።'),
  ('a062e11b-60d9-5379-a5a8-3b8cbb6e0428', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 4, 11, 'ከእርሱም በኋላ የአሮዳዊው የአጌ ልጅ ሴሜይ ነበረ። ፍልስጥኤማውያንም በቴሪያ ተሰበሰቡ። በዚያም ምስር የሞላበት የእርሻ ክፍል ነበር፤ ሕዝቡም ከፍልስጥኤማውያን ፊት ሸሹ።'),
  ('45fabd91-aab2-548a-aef8-a83f5af86ce3', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 5, 12, 'እርሱ ግን በእርሻው መካከል ቆሞ ጠበቀ፤ ፍልስጥኤማውያንንም ገደለ፤ እግዚአብሔርም ታላቅ መድኀኒት አደረገ።'),
  ('6dbeded5-f832-551f-a7ab-96dc2e79be75', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 6, 13, 'ከሠላሳውም አለቆች ሦስቱ ወርደው ወደ ቃሶን ወደ ዳዊት ወደ አዶላም ዋሻ መጡ፤ የፍልስጥኤማውያንም ጭፍራ በራፋይም ሸለቆ ሰፍሮ ነበር።'),
  ('345abdbb-b8b6-5d6c-a144-e2c952999c53', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 7, 14, 'በዚያ ጊዜም ዳዊት በምሽጉ ውስጥ ነበረ፤ የፍልስጥኤማውያንም ጭፍራ በዚያ ጊዜ በቤተ ልሔም ነበረ።'),
  ('c762b098-200b-58e4-ab72-a59c4bb62f0d', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 8, 15, 'ዳዊትም፥ “በበሩ አጠገብ ካለችው ከቤተ ልሔም ምንጭ ውኃ ማን ባጠጣኝ?” ብሎ ተመኘ። ያንጊዜም የፍልስጥኤማውያን ኀይል በቤተ ልሔም ነበረ።'),
  ('820e1ab4-c247-55a4-a3ba-cdb69810e654', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 9, 16, 'ሦስቱም ኀያላን የፍልስጥኤማውያንን ሠራዊት ሰንጥቀው ሄዱ፤ በበሩም አጠገብ ካለችው ከቤተ ልሔም ምንጭ ውኃ ቀዱ፤ ይዘውም ለዳዊት አመጡለት፤ እርሱ ግን ሊጠጣ አልወደደም፤ ነገር ግን ለእግዚአብሔር አፈሰሰው።'),
  ('a7ffae83-6b8f-5e59-a178-0fcee81af32c', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 10, 17, '“አቤቱ፥ ይህን አደርግ ዘንድ ከእኔ ይራቅ፤ ነፍሳቸውን ሰጥተው የሄዱ ሰዎች ደም አይደለምን?” ብሎ ይጠጣ ዘንድ አልወደደም። ሦስቱ ኀያላንም ያደረጉት ይህ ነው።'),
  ('dcda2035-0a44-5542-a54a-0212d1c46f52', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 11, 18, 'የሶርህያም ልጅ የኢዮአብ ወንድም አቢሳ የሦስቱ አለቃ ነበር። እርሱም ጦሩን በሦስቱ መቶ ላይ አንሥቶ ገደላቸው፤ ስሙም በሦስቱ ዘንድ ተጠርቶ ነበር።'),
  ('e11639c2-5358-52e0-a02b-4ca1609712c3', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 12, 19, 'እርሱም ከሦስቱ ይልቅ የከበረ ነበር፤ አለቃቸውም ሆነ፤ ነገር ግን ወደ ሦስቱ አልደረሰም።'),
  ('78519ea0-b357-5f69-a3cc-95c83b514ef3', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 13, 20, 'በቀበስሄል የነበረው ታላቅ ሥራ ያደረገው የዮዳሄ ልጅ በናያስ የሞዓባዊውን የአርኤልን ሁለት ልጆች ገደለ፤ በአመዳዩም ወራት ወርዶ በጕድጓድ ውስጥ አንበሳ ገደለ።'),
  ('6a99eeab-57e3-5989-a799-72305b7c9b79', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 14, 21, 'እርሱም ልዩ የሆነውን ግብፃዊ ሰው ገደለ፤ ግብፃዊውም በእጁ ዛቢያው እንደ ድልድይ ዕንጨት የሆነ ጦር ነበረው፤ በናያስ ግን በትር ይዞ ወደ እርሱ ወረደ፤ ከግብፃዊውም እጅ ጦሩን ነጥቆ በገዛ ጦሩ ገደለው።'),
  ('2656bf0a-8ecf-5fc8-a335-c8d6b4ea78a1', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 15, 22, 'የዮዳሄ ልጅ በናያስ ያደረገው ይህ ነው፤ ስሙም በሦስቱ ኀያላን ተጠርቶ ነበር።'),
  ('5ffd2f10-0627-5724-a8c2-557e6b2903bb', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 16, 23, 'ከሦስቱም ይልቅ የከበረ ነበረ፤ ነገር ግን ወደ ሦስቱ አልደረሰም። ዳዊትም ትእዛዝ አስከባሪ አድርጎ ሾመው።'),
  ('dfb743eb-7f96-59c5-a009-301fcc6fbf2f', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 17, 24, 'የዳዊት ኀያላንም ስማቸው ይህ ነው። የኢዮአብ ወንድም አሣሄል በሠላሳው መካከል ነበረ፤ የቤተ ልሔም ሰው የአጎቱ የዱዲ ልጅ ኤልያናን፥'),
  ('3d4fa3cd-44ab-5116-ace5-52951a819dca', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 18, 25, 'አሮዳዊው ሴሜይ፥ ሔሮዳዊው አልያቃ፥'),
  ('d1d64240-68dd-58ed-adc1-2f1de948f5d8', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 19, 26, 'ፈልጣዊው ሴሌ፥ የቴቁሓዊው የኤስካ ልጅ ዔራስ፥'),
  ('a4e2d960-4d57-544e-a9f5-9aef12993ba6', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 20, 27, 'ከአስቲጡ ልጆች ወገን የሚሆን አናቶታዊው አብዔዜር፥'),
  ('c9f2103f-35e9-567a-ac1e-b51e0ca7ae51', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 21, 28, 'የኤሎንያ ሰው ኤላን፥ የፋጤ ሰው ናኤሬት፥'),
  ('090cb7d6-6122-512e-a370-9e57cf4ca772', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 22, 29, 'የአንጢፋ ሰው የቦአና ልጅ ሔሌብ፥ ከብንያም ወገን ከጌብዓ የረባይ ልጅ ኢታይ፥'),
  ('e5c92698-561e-55bf-a696-b91f77b497cd', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 23, 30, 'ኤፍራታዊው በናያስ፥ የአብሪስ ሰው አሶም፥'),
  ('801205db-54d5-537a-a731-ffca9679413e', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 24, 31, 'ዓረባዊው አቤዔልቦን፥ አልሞናዊው ኤማሱኖስ፥'),
  ('4c49d2cf-c3f4-541e-a401-8b0c3eb36854', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 25, 32, 'አሴሌቦናዊው ኤልያሕባ፥ የአሶን ልጅ ዮናታን፥'),
  ('cacf6c1f-53ea-5a8a-af9c-4d457357600a', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 26, 33, 'አሮዳዊው ሳምናን፥ የሓተራዊው የሶሬ ልጅ አምናን፥'),
  ('88aefafe-a972-58d7-a3d9-620f83c76f7a', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 27, 34, 'የመካኪ ልጅ የአሶብ ልጅ ኤላፍላት፥ የጊሎናዊው የአኪጦፌል ልጅ ኤልያብ፥'),
  ('7a1862e4-41fe-51bf-a761-f3b8eaee0404', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 28, 35, 'ቀርሜሎሳዊው አሰሬ፥ አረባዊው ኤፌዎ፥'),
  ('28f61237-118d-5e34-a070-5f6afc73c462', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 29, 36, 'የናታን ልጅ ኤአኪ፥ ከገዓድ ልጆች ወገን ማሶባ፥'),
  ('952aa0a7-10d0-5c87-a3bc-0f54ce5c7892', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 30, 37, 'አሞናዊው ኤልዩ፥ የሶርህያ ልጅ የኢዮአብ ጋሻ ጃግሬ ቤሮታዊው ጌሎሬ፥'),
  ('19b969fd-b824-573a-a4d3-403f3060c5c8', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 31, 38, 'ኤተራዊው ዒራስ፥ ኢታናዊው ጋሬብ፥'),
  ('7ece9435-b96b-5185-a145-a77e4c44e910', '9434391c-fbf3-50cd-af0b-40f04cc24f47', 'c0b157e7-2e8d-524e-a306-1a2e800a66f7', 32, 39, 'ኬጤያዊው ኦርዮ፤ ሁሉም በሁሉ ሠላሳ ሰባት ናቸው።'),
  ('1eb946d6-acd3-51d9-a567-4dd27f21e063', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 1, 1, 'ደግሞም የእግዚአብሔር ቍጣ በእስራኤል ላይ ነደደ፤ ዳዊትንም፥ “ሂድ፤ እስራኤልንና ይሁዳን ቍጠር” ብሎ በላያቸው አስነሣው።'),
  ('6b8a1350-49c5-59b9-a951-c1239893aa5c', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 2, 2, 'ንጉሡም ከእርሱ ጋር የነበረውን የሠራዊት አለቃ ኢዮአብን፥ “የሕዝቡን ድምር አውቅ ዘንድ ከዳን ጀምሮ እስከ ቤርሳቤህ ድረስ ሂድ፤ ሕዝቡንም ቍጠራቸው” አለው።'),
  ('ae5b74be-9cbc-5614-a6b2-21c91d11074a', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 3, 3, 'ኢዮአብም ንጉሡን፥ “የጌታዬ የንጉሡ ዐይን እያየ አምላክህ እግዚአብሔር ዛሬ ካለው ሕዝብ መጠን በላይ መቶ እጥፍ ይጨምርበት፤ ጌታዬ ንጉሡ ግን ይህን ነገር ለምን ይፈልጋል?” አለው።'),
  ('b156d361-6ca1-5612-abf3-9790dc05e7f3', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 4, 4, 'ነገር ግን የንጉሡ ቃል በኢዮአብና በሠራዊቱ አለቆች ላይ አሸነፈ። ኢዮአብና የሠራዊቱ አለቆችም የእስራኤልን ሕዝብ ይቈጥሩ ዘንድ ከንጉሥ ዘንድ ወጡ።'),
  ('68321ca9-2945-5901-aac3-ee67191afa9d', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 5, 5, 'ዮርዳኖስንም ተሻገሩ፤ በጋድ ሸለቆ መካከል ባለችውም በኢያዜር ከተማ ቀኝ በኩል በአሮዔር ላይ ሰፈሩ።'),
  ('40ea90fe-37dd-5492-a870-2114ecc22660', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 6, 6, 'ወደ ገለዓድም አዳሳይ ወደምትባል ወደ ተባሶን ሀገርም መጡ፤ ወደ ዳኒዳንና ወደ ኡዳንም ደረሱ፤ ወደ ሲዶናም ዞሩ፤'),
  ('c6713636-2e8a-525b-a372-1b3d041116ac', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 7, 7, 'ወደ ጤሮስም ምሽግ ወደ ኤዌዎናውያን፥ ወደ ከነዓናውያንም ከተሞች ሁሉ መጡ፤ በይሁዳም ደቡብ በኩል በቤርሳቤህ ወጡ።'),
  ('510b64fa-03ed-5ced-ac38-c4f9cdcb70e6', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 8, 8, 'በሀገሪቱም ሁሉ ላይ ተመላልሰው ከዘጠኝ ወርና ከሃያ ቀን በኋላ ወደ ኢየሩሳሌም ተመለሱ።'),
  ('8a0c227a-3895-5908-a09b-5d49abdfc3e5', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 9, 9, 'ኢዮአብም የሕዝቡን ቍጥር ድምር ለንጉሡ ሰጠ፤ በእስራኤልም ሰይፍ የሚመዝዙ ስምንት መቶ ሺህ ጽኑዓን ሰዎች ነበሩ፤ የይሁዳም ተዋጊዎች ሰዎች አምስት መቶ ሺህ ነበሩ።'),
  ('a551f204-33fc-5b78-a4fe-fc896756c383', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 10, 10, 'ሕዝቡንም ከቈጠረ በኋላ ዳዊትን ልቡ መታው፤ ዳዊትም እግዚአብሔርን፥ “ባደረግሁት ነገር እጅግ በድያለሁ፤ አሁን ግን አቤቱ! ታላቅ ስንፍና አድርጌአለሁና የባሪያህን ኀጢአት ታርቅ ዘንድ እለምንሃለሁ” አለው።'),
  ('965bd619-5c1d-5f98-ac20-8e275563ca7d', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 11, 11, 'ዳዊትም ማልዶ በተነሣ ጊዜ፥ የእግዚአብሔር ቃል ወደ ዳዊት ባለ ራእይ ወደ ነቢዩ ወደ ጋድ እንዲህ ሲል መጣ፦'),
  ('32a4bb9e-6401-5e83-af07-a8c900b61f8a', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 12, 12, '“ሂድና ለዳዊት እንዲህ ብለህ ንገረው፦ እግዚአብሔር እንዲህ ይላል፦ ሦስት ነገሮችን በፊትህ አኖራለሁ፤ አደርግብህ ዘንድ ከእነርሱ አንዱን ምረጥ።”'),
  ('96676aac-d7a0-5a0d-a0af-8463a6143a4b', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 13, 13, 'ጋድም ወደ ዳዊት መጥቶ፥ “የሦስት ዓመት ራብ በሀገርህ ላይ ይምጣብህን? ወይስ ጠላቶችህ እያሳደዱህ ሦስት ወር ከእነርሱ ትሸሽን? ወይስ የሦስት ቀን ቸነፈር በሀገርህ ላይ ይሁን? የሚሻልህን ምረጥ። አሁንም ለላከኝ ምን መልስ እንደምሰጥ አስብና መርምር” ብሎ ነገረው።'),
  ('4928c07e-8170-510c-abb8-321cd376a90d', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 14, 14, 'ዳዊትም ጋድን፥ “በሁሉም እጅግ ተጨንቄአለሁ፤ በሰው እጅ ከምወድቅ ይልቅ ምሕረቱ ብዙ ነውና በእግዚአብሔር እጅ መውደቅ ይሻለኛል” አለው።'),
  ('d7970c3a-01da-5852-a5b3-7f24e6f1e5da', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 15, 15, 'ዳዊትም ቸነፈሩን መረጠ፤ የስንዴም መከር ወራት በሆነ ጊዜ ጌታ ከጥዋት እስከ ቀትር ቸነፈርን በእስራኤል ላይ ላከ። ቸነፈሩም በሕዝቡ መካከል ጀመረ፤ ከሕዝቡም ከዳን እስከ ቤርሳቤህ ሰባ ሺህ ሰው ሞተ።'),
  ('1272ea8d-2cd3-5bd4-ab74-23264c850eac', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 16, 16, 'የእግዚአብሔርም መልአክ ኢየሩሳሌምን ያጠፋት ዘንድ እጁን ዘረጋ፤ እግዚአብሔርም ከክፉው ነገር ይቅር አላት፤ ሕዝቡንም የሚያጠፋውን መልአክ፥ “እንግዲህ በቃህ፤ እጅህን መልስ” አለው። የእግዚአብሔርም መልአክ በኢያቡሳዊው በኦርና አውድማ አጠገብ ቆሞ ነበረ።'),
  ('35d8b792-ebdb-5b5e-af1f-52c796070a7c', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 17, 17, 'ዳዊትም ሕዝቡን የሚመታውን መልአክ ባየ ጊዜ እግዚአብሔርን፥ “እነሆ፥ እኔ በድያለሁ፤ ክፉም ሥራ እኔ አድርጌአለሁ፤ እነዚህ በጎች ግን ምን አደረጉ? እጅህ በእኔና በአባቴ ቤት ላይ ትሆን ዘንድ እለምንሃለሁ” ብሎ ተናገረው።'),
  ('83db1a68-d561-5c6a-a9b7-295d238530da', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 18, 18, 'በዚያም ቀን ጋድ ወደ ዳዊት መጥቶ፥ “ውጣ፤ በኢያቡሳዊው በኦርና አውድማ ለእግዚአብሔር መሠዊያ ሥራ” አለው።'),
  ('31a46a79-fe1c-5951-a857-80ad6a3d38bf', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 19, 19, 'ዳዊትም እግዚአብሔር እንዳዘዘው እንደ ጋድ ነገር ወጣ።'),
  ('25c1c102-5cd5-5e6d-a73b-99fabf28f151', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 20, 20, 'ኦርናም ሲመለከት ንጉሡና ብላቴናዎቹ ወደ እርሱ ሲመጡ አየ፤ ኦርናም ወጥቶ በንጉሡ ፊት በምድር ላይ በግንባሩ ሰገደ።'),
  ('8cb79a83-bcf2-592f-a830-af0240207f9f', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 21, 21, 'ኦርናም፥ “ጌታዬን ንጉሡን ወደ አገልጋዩ ያመጣው ምክንያት ምንድን ነው?” አለ። ዳዊትም፥ “መቅሠፍቱ ከሕዝቡ ላይ ይከለከል ዘንድ አውድማውን ከአንተ ገዝቼ ለእግዚአብሔር መሠዊያ ልሠራ ነው” አለው።'),
  ('779f4e0b-3044-5956-aabb-040662b1d7e9', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 22, 22, 'ኦርናም ዳዊትን፥ “ጌታዬ ንጉሡ በፊቱ ደስ ያሰኘውን ወስዶ ያቅርብ፤ እነሆም፥ ለሚቃጠል መሥዋዕት በሬዎች፥ ለሚቃጠልም እንጨት የአውድማ ዕቃና የበሬ ዕቃ አለ።'),
  ('f2cfb68c-d68f-554d-acc1-7777e3eb2482', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 23, 23, 'ንጉሥ ሆይ፥ ኦርና ይህን ሁሉ ለንጉሡ ይሰጣል” አለው፤ ኦርናም ንጉሡን፥ “አምላክህ እግዚአብሔር ይባርክህ” አለው።'),
  ('c7e0784d-5383-51dd-a8d5-4efa7ad8f033', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 24, 24, 'ንጉሡም ኦርናን፥ “እንዲህ አይደለም፤ ነገር ግን በዋጋ ከአንተ እገዛለሁ፤ ለአምላኬም ለእግዚአብሔር የሚቃጠል መሥዋዕት ያለ ዋጋ አላቀርብም” አለው። ዳዊትም አውድማውንና በሬዎቹን በአምሳ ሰቅል ብር ገዛ።'),
  ('c8c6e567-0076-540e-a2b5-076b5d161c16', 'd2ba4017-f2bd-5960-a8b8-b3b31363b45c', 'fec20e99-8307-5785-a91f-9bd9b73b967f', 25, 25, 'በዚያም ዳዊት ለእግዚአብሔር መሠዊያ ሠራ፤ የሚቃጠልና የሰላም መሥዋዕትንም አቀረበ። ሰሎሞንም በኋላ ዘመን በመሠዊያው ላይ ጨመረ፤ ያንጊዜ አነስተኛ ነበርና። እግዚአብሔርም ስለ ሀገሪቱ የተለመነውን ሰማ፤ መቅሠፍቱም ከእስራኤል ተከለከለ።'),
  ('d52ff6f7-cc45-5e15-a754-eea39d00e5f4', '1684439a-b96b-5602-a268-576f965c09ea', '8c848d93-5c0e-5299-a1b1-9db786aa92a7', 1, 1, 'ንጉሡ ዳዊትም አረጀ፤ ዘመኑም አለፈ፤ ልብስም ይደርቡለት ነበር፤ ነገር ግን አይሞቀውም ነበር።'),
  ('696ad6c9-10be-5cc2-a78c-7319e6cb466a', '1684439a-b96b-5602-a268-576f965c09ea', '8c848d93-5c0e-5299-a1b1-9db786aa92a7', 2, 2, 'የዳዊት አሽከሮችም፥ “ለጌታችን ለንጉሡ ድንግል ልጅ ትፈለግለት፤ በንጉሡም ፊት ቆማ ታገልግለው፥ በጌታችንም በንጉሡ ብብት ተኝታ ትቀፈው፤ ታሙቀውም” አሉ።'),
  ('9c8acbdf-8c06-533e-a221-5a4505f23216', '1684439a-b96b-5602-a268-576f965c09ea', '8c848d93-5c0e-5299-a1b1-9db786aa92a7', 3, 3, 'በእስራኤልም ሀገር ሁሉ የተዋበች ቆንጆ ፈለጉ፤ ሱነማዪቱን አቢሳንም አገኙ፤ ወደ ንጉሡም ወሰዱአት።'),
  ('35bd0d36-9d66-524f-ab7d-1cd475d78b74', '1684439a-b96b-5602-a268-576f965c09ea', '8c848d93-5c0e-5299-a1b1-9db786aa92a7', 4, 4, 'ቆንጆዪቱም እጅግ ውብ ነበረች፤ ንጉሡንም ታቅፈውና ታገለግለው ነበር፤ ንጉሡ ግን አያውቃትም ነበር።'),
  ('6dfbd45a-9c38-5873-af50-8d48a03c7bff', '1684439a-b96b-5602-a268-576f965c09ea', '8707f130-e9c3-5c69-a304-62f526c27a01', 1, 5, 'የአጊትም ልጅ አዶንያስ፥ “ንጉሥ እሆናለሁ” ብሎ ተነሣ፤ ሰረገሎችንና ፈረሰኞችን በፊቱም የሚሮጡ አምሳ ሰዎችን አዘጋጀ።'),
  ('f358120e-f498-5e48-a172-47214b9ab8e0', '1684439a-b96b-5602-a268-576f965c09ea', '8707f130-e9c3-5c69-a304-62f526c27a01', 2, 6, 'አባቱም፥ “ከቶ ለምን እንዲህ ታደርጋለህ?” ብሎ አልከለከለውም ነበር፤ እርሱም ደግሞ መልኩ እጅግ ያማረ ሰው ነበረ፤ እርሱንም ከአቤሴሎም በኋላ ወልዶት ነበር።'),
  ('73ef483e-cf1e-5aeb-ad36-a6414b4c9141', '1684439a-b96b-5602-a268-576f965c09ea', '8707f130-e9c3-5c69-a304-62f526c27a01', 3, 7, 'ሴራውም ከሶርህያ ልጅ ከኢዮአብና ከካህኑ ከአብያታር ጋር ነበረ፤ እነርሱም አዶንያስን ተከትለው ይረዱት ነበር።'),
  ('1263b116-4ca0-5180-af4a-9d5cd0e5f237', '1684439a-b96b-5602-a268-576f965c09ea', '8707f130-e9c3-5c69-a304-62f526c27a01', 4, 8, 'ነገር ግን ካህኑ ሳዶቅና የዮዳሄ ልጅ በናያስ ነቢዩም ናታን፥ ሳሚም፥ ሬሲም፥ የዳዊትም ኀያላን አዶንያስን አልተከተሉም ነበር።'),
  ('865e104b-11a0-58fa-a369-a8799275e80e', '1684439a-b96b-5602-a268-576f965c09ea', '8707f130-e9c3-5c69-a304-62f526c27a01', 5, 9, 'አዶንያስም በጎችንና በሬዎችን፥ ጠቦቶችንም በሮጌል ምንጭ አጠገብ ባለችው በዞሔሌት ድንጋይ ዘንድ ሠዋ፤ የንጉሡንም ልጆች ወንድሞቹን ሁሉ፥ የንጉሡንም አገልጋዮች፥ የይሁዳንም ኀያላን ሁሉ ጠራ።'),
  ('3496894e-bcec-50ae-add1-4f57ffddb3bd', '1684439a-b96b-5602-a268-576f965c09ea', '8707f130-e9c3-5c69-a304-62f526c27a01', 6, 10, 'ነገር ግን ነቢዩን ናታንን፥ በናያስንም፥ ኀያላኑንም፥ ወንድሙንም ሰሎሞንን አልጠራም።'),
  ('efb287a6-7671-5193-a782-5cd720716ae6', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 1, 11, 'ናታንም የሰሎሞንን እናት ቤርሳቤህን እንዲህ ብሎ ተናገራት፥ “ጌታችን ዳዊት ሳያውቅ የአጊት ልጅ አዶንያስ እንደ ነገሠ አልሰማሽምን?'),
  ('c813fbcd-c9e4-51fd-acbe-be6a4649b547', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 2, 12, 'አሁንም ነዪ፤ የልጅሽን የሰሎሞንን ነፍስና የአንቺን ነፍስ እንድታድኚ እመክርሻለሁ።'),
  ('85f7aa85-e55d-558b-aa93-5515e5e65a06', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 3, 13, 'ሄደሽ ወደ ንጉሡ ወደ ዳዊት ግቢና፦ ጌታዬ ንጉሥ ሆይ፥ ለእኔ ለአገልጋይህ፦ ልጅሽ ሰሎሞን ከእኔ በኋላ ይነግሣል፤ በዙፋኔም ይቀመጣል ብለህ አልማልህልኝምን? ስለምንስ አዶንያስ ይነግሣል? በዪው።'),
  ('d0a28917-f3a8-563a-a149-730d60cd250a', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 4, 14, 'እነሆ፥ አንቺ በዚያ ለንጉሥ ስትነግሪ እኔ ከአንቺ በኋላ እገባለሁ፤ ቃልሽንም አጸናለሁ።”'),
  ('a0564957-99cf-54a4-a9cb-c136ef1f54bb', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 5, 15, 'ቤርሳቤህም ወደ ንጉሡ ወደ እልፍኝ ገባች፤ ንጉሡም እጅግ ሸምግሎ ነበር፤ ሱነማዪቱም አቢሳ ንጉሡን ታገለግለው ነበር።'),
  ('7041964c-dc6c-5d29-a59c-79778c49d5b7', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 6, 16, 'ቤርሳቤህም አጎንብሳ ለንጉሡ ሰገደች፤ ንጉሡም፥ “ምን ሆንሽ?” አላት።'),
  ('3409c057-4913-5c4f-a3c7-8332a3f70fe7', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 7, 17, 'እርስዋም አለችው፥ “ጌታዬ ንጉሥ ሆይ፥ አንተ ለአገልጋይህ፦ ልጅሽ ሰሎሞን ከእኔ በኋላ ይነግሣል፤ በዙፋኔም ይቀመጣል ብለህ በአምላክህ ምለህልኝ አልነበረምን?'),
  ('655f86cf-67df-5ce4-a201-3b43ed74aaf0', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 8, 18, 'አሁንም፥ እነሆ፥ አዶንያስ መንገሡ ነው፤ አንተም ጌታዬ ንጉሥ ይህን አታውቅም፤'),
  ('29d1c28d-67b9-5207-ac3e-99f926bb2131', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 9, 19, 'እርሱም ብዙ በሬዎችንና ጠቦቶችን፥ በጎችንም ሠውቶአል፤ የንጉሡንም ልጆች ሁሉ፥ ካህኑንም አብያታርን፥ የሠራዊቱንም አለቃ ኢዮአብን ጠርቶአል፤ ባሪያህን ሰሎሞንን ግን አልጠራውም።'),
  ('cbbea945-ea97-5e36-ab01-1f126e60973a', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 10, 20, 'አሁንም ጌታዬ ንጉሥ ሆይ፥ ከአንተ በኋላ በጌታዬ በንጉሥ ዙፋን ላይ የሚቀመጠውን ትነግራቸው ዘንድ የእስራኤል ሁሉ ዐይን ይመለከትሃል።'),
  ('f18febd2-5222-588e-a804-8cbc3bf8fd75', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 11, 21, 'ይህ ባይሆን፥ ጌታዬ ንጉሥ ከአባቶችህ ጋር ባንቀላፋህ ጊዜ እኔና ልጄ ሰሎሞን እንደ ኀጢአተኞች እንቈጠራለን።”'),
  ('a0bd3672-c9ff-56b1-afe8-ce25365d80e5', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 12, 22, 'እነሆም፥ እርስዋ ከንጉሡ ጋር ስትነጋገር ነቢዩ ናታን መጣ፤'),
  ('fb87016d-dcc2-5485-adb8-a6ae82757a11', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 13, 23, 'ለንጉሡም፥ “እነሆ፥ ነቢዩ ናታን መጥቶአል” ብለው ነገሩት፤ እርሱም ወደ ንጉሡ ፊት በገባ ጊዜ በግንባሩ በምድር ላይ ተደፍቶ ለንጉሡ እጅ ነሣ።'),
  ('78a660b0-9d76-5ad8-af38-35c08060f0ef', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 14, 24, 'ነቢዩ ናታንም አለ፥ “ጌታዬ ንጉሥ ሆይ፦ አንተ ከእኔ በኋላ አዶንያስ ይነግሣል፥ በዙፋኔ ላይም ይቀመጣል ብለሃልን?'),
  ('b7155811-0ca7-5c27-a31d-9c69460f620e', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 15, 25, 'እርሱ ዛሬ ወርዶ ብዙ በሬዎችንና ጠቦቶችን፥ በጎችንም ሠውቶአል፤ የንጉሡንም ልጆች ሁሉ፥ የሠራዊቱን አለቃ ኢዮአብን፥ ካህኑንም አብያታርን ጠርቶአል፤ እነሆም፥ በፊቱ እየበሉና እየጠጡ፦ አዶንያስ ሺህ ዓመት ይንገሥ ይላሉ።'),
  ('5cd68d01-6558-5e5e-a1ad-f06be17c0c34', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 16, 26, 'ነገር ግን እኔን አገልጋይህን፥ ካህኑንም ሳዶቅን፥ የዮዳሄንም ልጅ በናያስን፥ አገልጋይህንም ሰሎሞንን አልጠራም።'),
  ('f89382b4-2969-56f2-a0bb-aaffe48e0943', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 17, 27, 'በውኑ ይህ ነገር ከጌታዬ ከንጉሡ የተደረገ ነገር ነውን? ለአገልጋይህም ከአንተ በኋላ በጌታዬ በንጉሡ ዙፋን ላይ የሚቀመጠውን ለምን አልነገርኸውም?”'),
  ('270b8117-e58d-51f2-a211-ecf041ba6580', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 18, 28, 'ንጉሡም ዳዊት፥ “ቤርሳቤህን ጥሩልኝ” ብሎ መለሰ። ወደ ንጉሡም ገባች፤ በንጉሡም ፊት ቆመች።'),
  ('53673414-edc8-5dd9-aeff-de83bcfe3b9b', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 19, 29, 'ንጉሡም እንዲህ ብሎ ማለ፥ “ነፍሴን ከመከራ ሁሉ ያዳነኝ ሕያው እግዚአብሔርን!'),
  ('222cadd5-b537-597e-a6b9-c89a796e7a9d', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 20, 30, 'በእውነት፦ ልጅሽ ሰሎሞን ከእኔ በኋላ ይነግሣል፤ በእኔም ፋንታ በዙፋኔ ላይ ይቀመጣል ብዬ በእስራኤል አምላክ በእግዚአብሔር እንደ ማልሁልሽ፥ እንዲሁ ዛሬ በእውነት አደርጋለሁ።”'),
  ('1846b20d-5f19-51cf-a099-68a151bcd831', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 21, 31, 'ቤርሳቤህም በግንባርዋ በምድር ላይ ተደፍታ ለንጉሡ ሰገደችና፥ “ጌታዬ ንጉሥ ዳዊት ለዘለዓለም በሕይወት ይኑር” አለች።'),
  ('62a4722d-b24d-5e3d-a9a9-7cc0c20b4577', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 22, 32, 'ንጉሡም ዳዊት፥ “ካህኑን ሳዶቅንና ነቢዩ ናታንን የዮዳሄንም ልጅ በናያስን ጥሩልኝ” አለ።'),
  ('d92d968f-237e-5183-a456-25f9cf085503', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 23, 33, 'ወደ ንጉሡም ገቡ። ንጉሡም አላቸው፥ “የጌታችሁን አገልጋዮች ይዛችሁ ሂዱ፥ ልጄንም ሰሎሞንን በበቅሎዬ ላይ አስቀምጡት፥ ወደ ግዮንም አውርዱት፤'),
  ('297145d4-51a3-52eb-ade9-5f09cd677a5b', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 24, 34, 'በዚያም ካህኑ ሳዶቅና ነቢዩ ናታን በእስራኤል ላይ ቀብተው ያንግሡት፤ መለከትም ነፍታችሁ፦ ሰሎሞን ሺህ ዓመት ይንገሥ በሉ።'),
  ('7ae3c546-d9d2-5d66-a4ee-b2a518edb5cf', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 25, 35, 'በኋላውም ተከትላችሁ ውጡ፤ እርሱም መጥቶ በዙፋኔ ላይ ይቀመጥ፤ በእኔም ፋንታ ይንገሥ፤ በእስራኤልና በይሁዳም ላይ ይነግሥ ዘንድ አዝዣለሁ።”'),
  ('0bfe0268-b382-5a70-ae5a-727b82cc1e8e', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 26, 36, 'የዮዳሄም ልጅ በናያስ መልሶ ለንጉሡ አለ፥ “እንዲሁ ይሁን፤ የጌታዬም የንጉሥ አምላክ እግዚአብሔር ይህን ያጽና።'),
  ('a725215f-09f5-503a-a7a2-86b88560123b', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 27, 37, 'እግዚአብሔር ከጌታዬ ከንጉሥ ጋር እንደ ነበረ እንዲሁ ከሰሎሞን ጋር ይሁን፤ ዙፋኑንም ከጌታዬ ከንጉሡ ከዳዊት ዙፋን የበለጠ ያድርግ።”'),
  ('d0d7c93e-d68c-5762-ae57-acdf107bd20c', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 28, 38, 'ካህኑም ሳዶቅና ነቢዩ ናታን የዮዳሄም ልጅ በናያስ ከሊታውያንና ፈሊታውያንም ወረዱ፤ ሰሎሞንንም በንጉሡ በዳዊት በቅሎ ላይ አስቀምጠው ወደ ግዮን ወሰዱት።'),
  ('20b3b545-6fb2-5b88-a3f2-86794c51a6c3', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 29, 39, 'ካህኑም ሳዶቅ ከድንኳኑ የዘይቱን ቀንድ ወስዶ ሰሎሞንን ቀባ፤ መለከትም ነፋ፤ ሕዝቡም ሁሉ፥ “ሰሎሞን ሺህ ዓመት ይንገሥ” አሉ።'),
  ('6be13026-b47e-524a-a3ab-14e4c2a689ff', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 30, 40, 'ሕዝቡም ሁሉ እርሱን ተከትለው ወጡ፤ ከበሮንና መሰንቆንም መቱ፥ በታላቅም ደስታ ደስ አላቸው፤ ከጩኸታቸውም የተነሣ ምድር ተናወጠች።'),
  ('fdc55abf-771f-5fd2-a473-0d36ec5bbc8c', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 31, 41, 'አዶንያስና እርሱም የጠራቸው ሁሉ መብሉና መጠጡ ተፈጽሞ ሳለ ሰሙ፤ ኢዮአብም የመለከት ድምፅ በሰማ ጊዜ፥ “ይህ በከተማ የምሰማው ድምፅ ምንድን ነው?” አለ።'),
  ('d67e1d62-a329-5164-a691-b3721b54b5bf', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 32, 42, 'እርሱም ይህን ሲናገር የካህኑ የአብያታር ልጅ ዮናታን መጣ፤ አዶንያስም፥ “አንተ ኀያል ሰው ነህና፥ መልካምም ታወራልናለህና ግባ” አለው።'),
  ('a502a1d5-9157-534a-aa57-1480c9a65cfb', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 33, 43, 'ዮናታንም ለአዶንያስ እንዲህ ብሎ መለሰ፥ “በእውነት ጌታችን ንጉሥ ዳዊት ሰሎሞንን አነገሠው።'),
  ('8c39cc98-490f-59dc-aad1-8ed1aa6f2170', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 34, 44, 'ንጉሡም ከእርሱ ጋር ካህኑን ሳዶቅንና ነቢዩን ናታንን፥ የዮዳሄንም ልጅ በናያስን፥ ከሊታውያንንና ፈሊታውያንንም ላከ፤ በንጉሡም በቅሎ ላይ አስቀመጡት።'),
  ('a93fc597-49d8-545e-aa21-aac148578e3a', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 35, 45, 'ካህኑም ሳዶቅና ነቢዩ ናታን ቀብተው በግዮን አነገሡት፤ ከዚያም ደስ ብሎአቸው ወጡ፤ ከተማዪቱም አስተጋባች፤ የሰማችሁትም ድምፅ ይህ ነው።'),
  ('c964b096-aab9-5cae-a94e-ea77e1021df2', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 36, 46, 'ሰሎሞንም በመንግሥቱ ዙፋን ላይ ተቀምጦአል።'),
  ('6f3e1fb7-fde3-5968-a2c5-e883e4a8f74b', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 37, 47, 'የንጉሡም አገልጋዮች ገብተው፦ ‘እግዚአብሔር የሰሎሞንን ስም ከስምህ ይልቅ መልካም ያድርግ፤ ዙፋኑንም ከዙፋንህ የበለጠ ያድርግ’ ብለው ጌታቸውን ንጉሡ ዳዊትን መረቁ፤” ንጉሡም በአልጋው ላይ ሆኖ ሰገደ።'),
  ('5218a5f6-6bdd-5f61-a724-6b3aa5402984', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 38, 48, 'ንጉሡም፥ “ዐይኔ እያየ ዛሬ በዙፋኔ ላይ የሚቀመጠውን ዘር የሰጠኝ የእስራኤል አምላክ እግዚአብሔር ይመስገን” አለ።'),
  ('9500c754-268f-5f99-a84e-ff8b753eae64', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 39, 49, 'አዶንያስም የጠራቸው ሁሉ ፈሩ፤ ተነሥተውም እያንዳንዳቸው በየመንገዳቸው ሄዱ።'),
  ('c1eddae8-5543-51f9-a273-24a97e5069c9', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 40, 50, 'አዶንያስም ከሰሎሞን ፊት የተነሣ ፈራ፤ ተነሥቶም ሄደ፤ የመሠዊያውንም ቀንድ ያዘ።'),
  ('4deaf0df-dc74-5e83-aa56-8277873966e2', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 41, 51, 'ለሰሎሞንም፥ “እነሆ፥ አዶንያስ ንጉሡን ሰሎሞንን ፈርቶ፦ ንጉሡ ሰሎሞን አገልጋዩን በሰይፍ እንዳይገድለኝ ዛሬ ይማልልኝ ብሎ የመሠዊያውን ቀንድ ይዞአል” አሉት።'),
  ('4573c55d-9c85-5b96-a1c3-eb634a5e2397', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 42, 52, 'ሰሎሞንም፥ “እርሱ አካሄዱን ያሳመረ እንደ ሆነ ከእርሱ አንዲት ጠጕር እንኳ በምድር ላይ አትወድቅም፤ ነገር ግን ክፋት የተገኘበት እንደ ሆነ ይሞታል” አለ።'),
  ('036f08f9-e470-5397-aaea-005bbcdeca9a', '1684439a-b96b-5602-a268-576f965c09ea', '1bd33758-7e23-5cb5-a8dd-b659571b78e3', 43, 53, 'ንጉሡ ሰሎሞንም ላከ፤ ከመሠዊያውም አወረዱት፤ መጥቶም ለንጉሡ ለሰሎሞን ሰገደ፤ ሰሎሞንም፥ “ወደ ቤትህ ሂድ” አለው።'),
  ('6a1480ad-d7b6-568a-aee5-208a983fec2f', '8d611285-d310-506b-afee-153d25b9630b', '971bd2ad-d049-5a05-a3ac-8430df0c0d1a', 1, 1, 'ዳዊትም የሚሞትበት ወራት ደረሰ፤ ልጁንም ሰሎሞንን እንዲህ ሲል አዘዘው፦'),
  ('2510c3fa-b989-52e0-a5a3-f324c09695d6', '8d611285-d310-506b-afee-153d25b9630b', '971bd2ad-d049-5a05-a3ac-8430df0c0d1a', 2, 2, '“እኔ የምድሩን መንገድ ሁሉ እሄዳለሁ፤ በርታ ሰውም ሁን፤'),
  ('657e55d4-7556-5cec-a838-4c0d14c552bb', '8d611285-d310-506b-afee-153d25b9630b', '971bd2ad-d049-5a05-a3ac-8430df0c0d1a', 3, 3, 'እንደማዝዝህ የምታደርገውን ሁሉ ታውቅ ዘንድ፥ በሙሴ ሕግ የተጻፈውን ሥርዐቱንና ትእዛዛቱን፥ ፍርዱንና ምስክሩንም ትጠብቅ ዘንድ በመንገዱም ትሄድ ዘንድ፥ የአምላክህን የእግዚአብሔርን ትእዛዝ ጠብቅ።'),
  ('068b023a-7b2b-5e1f-a50b-af7c797f0bac', '8d611285-d310-506b-afee-153d25b9630b', '971bd2ad-d049-5a05-a3ac-8430df0c0d1a', 4, 4, 'ይኸውም እግዚአብሔር ስለ እኔ፦ ‘ልጆችህ መንገዳቸውን ቢጠብቁ፥ በፊቴም በፍጹም ልባቸውና በፍጹም ነፍሳቸው በእውነት ቢሄዱ ከእስራኤል ዙፋን ሰው አይጠፋም’ ብሎ የተናገረውን ቃል ያጸና ዘንድ ነው።'),
  ('af089f7f-d69c-5714-a9de-3445a677e4bd', '8d611285-d310-506b-afee-153d25b9630b', '971bd2ad-d049-5a05-a3ac-8430df0c0d1a', 5, 5, 'አንተም ደግሞ የሶርህያ ልጅ ኢዮአብ፥ ሁለቱን የእስራኤል ሠራዊት አለቆች የኔር ልጅ አበኔርን የኢያቴርንም ልጅ አሜሳይን ገድሎ፥ በእኔ ላይ ያደረገውን ታውቃለህ፤ የጦርነትንም ደም በሰላም አፈሰሰ፤ በወገቡም ባለው ድግና በእግሩም ባለው ጫማ ንጹሕ ደም አኖረ።'),
  ('c8d7fa50-7c3d-5c89-a6f8-ecf3708c8209', '8d611285-d310-506b-afee-153d25b9630b', '971bd2ad-d049-5a05-a3ac-8430df0c0d1a', 6, 6, 'አንተም እንደ ጥበብህ አድርግ፤ ሽበቱንም በሰላም ወደ መቃብር አታውርደው።'),
  ('210c401d-b9ba-5a9a-a87b-5bc945c6b26f', '8d611285-d310-506b-afee-153d25b9630b', '971bd2ad-d049-5a05-a3ac-8430df0c0d1a', 7, 7, 'ከወንድምህ ከአቤሴሎም ፊት በሸሸሁ ጊዜ ቀርበውኛልና ለገለዓዳዊው ለቤርዜሊ ልጆች ቸርነትን አድርግላቸው። በማዕድህም ከሚበሉት መካከል ይሁኑ።'),
  ('5a978b7f-dc4f-5837-aca0-e893e9a65fc7', '8d611285-d310-506b-afee-153d25b9630b', '971bd2ad-d049-5a05-a3ac-8430df0c0d1a', 8, 8, 'የባውሬም ሀገር ሰው የብንያማዊው የጌራ ልጅ ሳሚ እነሆ! በአንተ ዘንድ ነው፤ እኔም ወደ መሃናይም በሄድሁ ጊዜ ብርቱ ርግማን ረገመኝ፤ ከዚያም በኋላ ዮርዳኖስን በተሻገርሁ ጊዜ ሊቀበለኝ ወረደ፤ እኔም፦ ‘በሰይፍ አልገድልህም’ ብዬ በእግዚአብሔር ምየለታለሁ።'),
  ('b89d9da7-a6b2-5a09-a113-f69a7d3788a7', '8d611285-d310-506b-afee-153d25b9630b', '971bd2ad-d049-5a05-a3ac-8430df0c0d1a', 9, 9, 'አንተ ግን ጥበበኛ ሰው ነህና ንጹሕ አታድርገው፤ የምታደርግበትንም አንተ ታውቃለህ፤ ሽበቱንም በደም ወደ መቃብር አውርደው” አለው።'),
  ('dcdfb920-ad51-5ff0-ae63-ef877001d3bb', '8d611285-d310-506b-afee-153d25b9630b', '2ef37053-a910-52a0-a2e3-416bbd4c25e7', 1, 10, 'ዳዊትም ከአባቶቹ ጋር አንቀላፋ፤ በዳዊትም ከተማ ተቀበረ።'),
  ('ae250c67-a4ef-5a5f-a22c-0c0971bdb8bd', '8d611285-d310-506b-afee-153d25b9630b', '2ef37053-a910-52a0-a2e3-416bbd4c25e7', 2, 11, 'ዳዊትም በእስራኤል ላይ የነገሠበት ዘመን አርባ ዓመት ነበረ። በኬብሮን ሰባት ዓመት፥ በኢየሩሳሌምም ሠላሳ ሦስት ዓመት ነገሠ።'),
  ('d98983d1-44f4-5e17-af54-fb12b42092fa', '8d611285-d310-506b-afee-153d25b9630b', '2ef37053-a910-52a0-a2e3-416bbd4c25e7', 3, 12, 'ሰሎሞንም በአባቱ በዳዊት ዙፋን ተቀመጠ፤ መንግሥቱም እጅግ ጸና።'),
  ('f32c8ea3-a637-5937-aa21-db37f6473d6c', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 1, 13, 'የአጊት ልጅ አዶንያስም ወደ ሰሎሞን እናት ወደ ቤርሳቤህ መጣ፤ ሰገደላትም፤ እርስዋም፥ “ወደ እኔ መምጣትህ በሰላም ነውን?” አለችው። እርሱም፥ “በሰላም ነው” አለ።'),
  ('64fe73b5-9290-5ab5-a070-ab3a5dba2004', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 2, 14, 'ደግሞም፥ “ከአንቺ ጋር ጉዳይ አለኝ” አለ፤ እርስዋም፥ “ተናገር” አለችው።'),
  ('37e88292-d5c3-5d50-a026-948b21ef7d6a', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 3, 15, 'እርሱም፥ “መንግሥቱ ለእኔ እንደ ነበረ፥ እስራኤልም ሁሉ ንጉሥ እሆን ዘንድ ፊታቸውን ወደ እኔ አድርገው እንደ ነበረ አንቺ ታውቂያለሽ፤ ነገር ግን ከእግዚአብሔር ዘንድ ሆኖለታልና መንግሥት ተመልሳ ለወንድሜ ሆናለች።'),
  ('3da6f22a-a0d7-5cf7-a1d0-18ff0415c921', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 4, 16, 'አሁንም አንዲት ልመና እለምንሻለሁ ፤ ፊትሽንም አትመልሺብኝ” አላት። እርስዋም፥ “ተናገር” አለችው፤'),
  ('b654273d-9ca7-51cd-a85d-445b6962431f', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 5, 17, 'እርሱም፥ “ፊቱን አይመልስብሽምና፥ ሱነማዪቱን አቢሳን ይድርልኝ ዘንድ ለንጉሡ ለሰሎሞን እንድትነግሪው እለምንሻለሁ” አለ።'),
  ('621ecb17-44fc-5247-a8ac-f939e62226e2', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 6, 18, 'ቤርሳቤህም፥ “መልካም ነው፤ ስለ አንተ ለንጉሡ እነግረዋለሁ” አለች።'),
  ('7894d267-b32e-51b3-a6e9-fac9578b7c86', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 7, 19, 'ቤርሳቤህም የአዶንያስን ነገር ትነግረው ዘንድ ወደ ንጉሡ ወደ ሰሎሞን ገባች፤ ንጉሡም ሊቀበላት ተነሣ፤ ሳማትም፤ በዙፋኑም ተቀመጠ፤ ለንጉሡም እናት ወንበር አስመጣላት፤ በቀኙም ተቀመጠች።'),
  ('33133e29-ae3a-519f-a577-c9d7ffbcf8fd', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 8, 20, 'እርስዋም፥ “አንዲት ትንሽ ልመና እለምንሃለሁ፤ ፊትህን አትመልስብኝ” አለች። ንጉሡም፥ “እናቴ ሆይ! ፊቴን አልመልስብሽምና ለምኚ” አላት።'),
  ('d22a7da6-d336-5b25-a310-5de4c58320fe', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 9, 21, 'እርስዋም፥ “ሚስት ትሆነው ዘንድ ለወንድምህ ለአዶንያስ ሱነማዪቱ አቢሳን ይስጡት” አለች።'),
  ('61a5a07c-972a-5e56-a9bc-e05786203ad8', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 10, 22, 'ንጉሡም ሰሎሞን ለእናቱ መልሶ፥ “ሱነማዪቱን አቢሳን ለአዶንያስ ለምን ትለምኚለታለሽ? ታላቅ ወንድሜ ነውና መንግሥትን ደግሞ ለምኚለት፤ ካህኑም አብያታርና የሶርህያ ልጅ የጭፍሮች አለቃ ኢዮአብ ደግሞ ከእርሱ ጋር ናቸው” አላት።'),
  ('7dacbb48-8a8f-567e-a2c0-0341aad3912b', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 11, 23, 'ንጉሡም ሰሎሞን፦ እንዲህ ሲል በእግዚአብሔር ማለ። “አዶንያስ ይህን ቃል በሕይወቱ ላይ እንደ ተናገረ እግዚአብሔር ይህን ያድርግብኝ፤ ይህንም ይጨምርብኝ።'),
  ('5e2e53e4-9a7c-5480-a7e0-38f5be605521', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 12, 24, 'አሁንም ያጸናኝ፥ በአባቴም በዳዊት ዙፋን ላይ ያስቀመጠኝ፥ እንደ ተናገረውም ቤትን የሠራልኝ ሕያው እግዚአብሔርን! ዛሬ አዶንያስ ፈጽሞ ይገደላል።'),
  ('2d9fea85-56c7-5731-aaee-18f4b50c388d', '8d611285-d310-506b-afee-153d25b9630b', 'a406eb6b-2fbe-547a-ae75-d233efcafb04', 13, 25, 'ንጉሡም ሰሎሞን የዮዳሄን ልጅ በናያስን ላከ፤ እርሱም አረደው፤ ያንጊዜም አዶንያስ ሞተ።'),
  ('9619b475-745c-503b-a9f6-a41698d8fb87', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 1, 26, 'ንጉሡም ካህኑን አብያታርን፥ “አንተ ዛሬ የሞት ሰው ነበርህ፤ ነገር ግን የአምላክን የእግዚአብሔርን ታቦት በአባቴ በዳዊት ፊት ስለ ተሸከምህ፥ አባቴም የተቀበለውን መከራ ሁሉ አንተ ስለ ተቀበልህ አልገድልህምና በዓናቶት ወዳለው ወደ እርሻህ ፈጥነህ ሂድ” አለው።'),
  ('e61badb8-3f3f-5619-adc7-0203d3c92103', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 2, 27, 'በሴሎም በዔሊ ቤት ላይ የተናገረው የእግዚአብሔር ቃል ይፈጸም ዘንድ ሰሎሞን አብያታርን ከእግዚአብሔር ክህነት አወጣው።'),
  ('1e8ae34e-209b-5d01-a3cd-b52e96756f21', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 3, 28, 'ለሶርህያ ልጅ ለኢዮአብም ወሬ ደረሰለት፤ ኢዮአብ ከአዶንያስ ጋር ተባብሮ ተከተለው እንጂ ከሰሎሞን ጋር አልተባበረም፤ አልተከተለውምም ነበርና። ኢዮአብም ወደ እግዚአብሔር ድንኳን ሸሽቶ የመሠዊያውን ቀንድ ያዘ።'),
  ('1dafcf47-8ca2-5c12-ab4b-7a4f47b9cb2c', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 4, 29, 'ንጉሡም ሰሎሞን ኢዮአብ ወደ እግዚአብሔር ድንኳን ሸሽቶ የመሠዊያውን ቀንድ እንደ ያዘ ሰማ፤ ንጉሥ ሰሎሞንም ወደ ኢዮአብ እንዲህ ሲል ላከ፤ “በመሠዊያው ቀንድ የተማጠንህ ምን ሆነህ ነው?” ኢዮአብም፥ “ፈርቼሃለሁና በእግዚአብሔር ተማጠንሁ” አለ። ሰሎሞንም የዮዳሄን ልጅ በንያስን ልኮ፥ “ሂድ ግደልና ቅበረው” ብሎ አዘዘው።'),
  ('1be6690f-46e7-5c01-a09a-ed7a4ea7e72a', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 5, 30, 'የዮዳሄ ልጅ በንያስም ወደ ኢዮአብ ወደ እግዚአብሔር ድንኳን መጥቶ፥ “ንጉሡ፦ ውጣ ይልሃል” አለው፤ ኢዮአብም፥ “በዚህ እሞታለሁ እንጂ አልወጣም” አለ። የዮዳሄ ልጅ በንያስም፦ ተመልሶ “ኢዮአብ የተናገረው ቃል፥ የመለሰልኝም እንዲህ ነው” ብሎ ለንጉሡ ነገረው።'),
  ('2660c18f-2aa2-5c35-aac9-725a4c6dd33b', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 6, 31, 'ንጉሡም አለው፥ “ሂድና እንደ ነገረህ አድርግ፤ ገድለህም ቅበረው፤ ኢዮአብም በከንቱ ያፈሰሰውን ደም ከእኔና ከአባቴ ቤት ታርቃለህ።'),
  ('d2920184-8ffc-54a1-a10c-64e46a263d65', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 7, 32, 'አባቴ ዳዊት ሳያውቅ ከእርሱ የሚሻሉትን ሁለቱን ጻድቃን ሰዎች፥ የእስራኤልን ሠራዊት አለቃ የኔርን ልጅ አበኔርን፥ የይሁዳንም ሠራዊት አለቃ የኢያቴርን ልጅ አሜሳይን በሰይፍ ገድሎአልና እግዚአብሔር የዐመፅ ደሙን በራሱ ላይ መለሰ።'),
  ('0a29bad5-0131-5235-aaf4-ee60494a12e3', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 8, 33, 'ደማቸውም በኢዮአብ ራስና በዘሩ ራስ ላይ ለዘለዓለም ይመለስ፤ ለዳዊት ግን ለዘሩና ለቤቱ፥ ለዙፋኑም የእግዚአብሔር ሰላም ለዘለዓለም ይሁን።”'),
  ('218f859a-ea5c-55f9-af75-eab93cc83b97', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 9, 34, 'የዮዳሄም ልጅ በንያስ ወጥቶ ያዘው፤ ገደለውም፤ በምድረ በዳም ባለው በራሱ ቤት ቀበረው።'),
  ('c5cdb333-234c-545a-a16b-fba2ab73f141', '8d611285-d310-506b-afee-153d25b9630b', 'c9defb53-681a-58ce-a710-253767177fa8', 10, 35, 'ንጉሡም በእርሱ ፋንታ የዮዳሄን ልጅ በንያስን የሠራዊቱ አለቃ አድርጎ ሾመ፤ መንግሥቱም በኢየሩሳሌም ጸናች። በአብያታርም ፋንታ ካህኑን ሳዶቅን ሾመ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('be8546ea-24e3-5232-ae24-ca94ed1592fb', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 1, 36, 'ንጉሡም ልኮ ሳሚን አስጠራውና እንዲህ አለው፥ “በኢየሩሳሌም ቤት ሠርተህ ተቀመጥ፤ ወዲህና ወዲያም አትውጣ።'),
  ('0f817ede-a426-54da-a836-6a3ce651f33a', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 2, 37, 'በምትወጣበትና የቄድሮንንም ፈፋ በምትሻገርበት ቀን ፈጽመህ እንደምትሞት ዕወቅ፤ ደምህም በራስህ ላይ ይሆናል።” ያንጊዜም ንጉሡ አማለው።'),
  ('de2bc92f-2135-5fdc-a1fd-6b22850c4e8d', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 3, 38, 'ሳሚም ንጉሡን፥ “ጌታዬ ንጉሥ የተናገርኸው ቃል መልካም ነው፤ አገልጋይህም እንዲሁ ያደርጋል” አለው፤ ሳሚም በኢየሩሳሌም ሦስት ዓመት ተቀመጠ።'),
  ('71c2dfb7-e27c-525a-a3f1-08bc406b5677', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 4, 39, 'ከሦስት ዓመትም በኋላ ከሳሚ አገልጋዮች ሁለቱ ወደ ጌት ንጉሥ ወደ መዓካ ልጅ ወደ አንኩስ ኰበለሉ፤ ለሳሚም፥ “እነሆ፥ አገልጋዮችህ በጌት ናቸው” ብለው ነገሩት።'),
  ('9b598e56-a5d4-5db8-a575-fb5bb5e0b282', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 5, 40, 'ሳሚም ተነሣ፤ አህያውንም ጭኖ አገልጋዮቹን ይሻ ዘንድ ወደ ጌት ወደ አንኩስ ዘንድ ሄደ፤ ሳሚም ሄዶ አገልጋዮቹን ከጌት አመጣ።'),
  ('58436f89-2606-54fc-a723-e032285372f1', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 6, 41, 'ሰሎሞንም ሳሚ ከኢየሩሳሌም ወደ ጌት ሄዶ አገልጋዮቹን እንዳመጣ ሰማ።'),
  ('1efd869d-9a8b-5238-a28a-b1e4e8697996', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 7, 42, 'ንጉሡም ልኮ ሳሚን አስጠራና፥ “ወደ ቀኝ ወይም ወደ ግራ ለመሄድ በምትወጣበት ቀን ፈጽመህ እንድትሞት ዕወቅ ብዬ በእግዚአብሔር አላስማልሁህምን? ወይስ አላስመሰከርሁብህምን?'),
  ('b692331a-003b-5021-a475-f44e958aec85', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 8, 43, 'የእግዚአብሔርን መሐላ፥ እኔም ያዘዝሁትን ትእዛዝ ስለምን አልጠበቅህም?” አለው።'),
  ('46eac7c5-3b2d-56e3-a09f-ea05a7f0cb69', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 9, 44, 'ንጉሡም ደግሞ ሳሚን፥ “አንተ በአባቴ በዳዊት ላይ የሠራኸውን፥ ልብህም ያሰበውን ክፋት ሁሉ ታውቃለህ፤ እግዚአብሔርም ክፋትህን በራስህ ላይ ይመልሳል።'),
  ('e1f9a0ac-53f3-52b7-a81e-12f9716f80b9', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 10, 45, 'ንጉሡ ሰሎሞን ግን የተባረከ ይሆናል፤ የዳዊትም ዙፋን በእግዚአብሔር ፊት ለዘለዓለም ይጸናል” አለው።'),
  ('17f4caad-ac45-57b8-af91-f4b29e4569c8', '8d611285-d310-506b-afee-153d25b9630b', '01651e8b-8799-582f-a143-26a3a428d373', 11, 46, 'ሰሎሞንም የዮዳሄን ልጅ በንያስን አዘዘው፤ ወጥቶም ገደለው። የሰሎሞንም መንግሥት በኢየሩሳሌም ጸና።'),
  ('044692bb-0aba-5113-af23-f8469253f5cc', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 1, 1, 'ሰሎሞንም ለግብፅ ንጉሥ ለፈርዖን አማች ሆነ፤ የፈርዖንንም ልጅ አገባ፤ ቤቱንና የእግዚአብሔርንም ቤት፥ በኢየሩሳሌምም ዙሪያ ያለውን ቅጥር ሠርቶ እስኪፈጽም ድረስ ወደ ዳዊት ከተማ አምጥቶ አስገባት።'),
  ('c386bdb2-95d8-562e-a6ae-c5a22403224e', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 2, 2, 'እስከዚያም ቀን ድረስ ለእግዚአብሔር ቤት አልተሠራም ነበርና ሕዝቡ በኮረብታ ላይ ይሠዉና ያጥኑ ነበር።'),
  ('51ac58aa-fd80-5b25-a86e-885c2d9429f7', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 3, 3, 'ሰሎሞንም እግዚአብሔርን ይወድድ ነበር፤ በአባቱም በዳዊት ሥርዐት ይሄድ ነበር፤ ነገር ግን በኮረብታው ላይ ይሠዋና ያጥን ነበር።'),
  ('e9b5d433-12fb-599f-ab8b-1c68d6abb494', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 4, 4, 'ገባዖን ፈጽማ ትሰፋ ነበርና በዚያ መሥዋዕት ይሠዋ ዘንድ ተነሥቶ ሄደ፤ ሰሎሞንም በዚያ መሠዊያ ላይ በገባዖን አንድ ሺህ የሚቃጠል መሥዋዕት ሠዋ።'),
  ('0835cab1-cb39-5c3a-ae2e-66f09c1e6c5e', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 5, 5, 'እግዚአብሔርም በገባዖን ለሰሎሞን በሌሊት በሕልም ተገለጠለት፤ እግዚአብሔርም ሰሎሞንን፥ “እንድሰጥህ የምትፈልገውን ለምን” አለው።'),
  ('623dc431-5905-573b-a6c5-4e544d085cf6', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 6, 6, 'ሰሎሞንም አለ፥ “እርሱ በፊትህ በእውነትና በጽድቅ፥ በልብም ቅንነት ከአንተ ጋር እንደ ሄደ፥ ከአባቴ ከባሪያህ ከዳዊት ጋር ታላቅ ቸርነት አድርገሃል፤ ዛሬ እንደ ሆነም በዙፋኑ ላይ የሚቀመጥ ልጅ ሰጥተህ ታላቁን ቸርነትህን አቈይተህለታል።'),
  ('69cfd66b-8e7b-5845-a463-adcb30852f40', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 7, 7, 'አሁንም አቤቱ አምላኬ ሆይ፥ እኔን ባሪያህን በአባቴ በዳዊት ፋንታ አንግሠኸኛል፤ እኔም መውጫዬንና መግቢያዬን የማላውቅ ታናሽ ብላቴና ነኝ።'),
  ('6db22b59-2813-54b8-a64d-6b39d63fba21', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 8, 8, 'ባሪያህም ያለው አንተ በመረጥኸው ሕዝብህ፥ ስለ ብዛቱም ይቈጠር ዘንድ በማይቻል በታላቅ ሕዝብ መካከል ነው።'),
  ('579c666f-83c1-5be9-ae52-81b7384a822f', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 9, 9, 'ስለዚህም ሰምቶ በሕዝብህ ላይ መፍረድ ይችል ዘንድ፥ መልካሙንና ክፉውንም ይለይ ዘንድ ለባሪያህ አስተዋይ ልቡና ስጠው፤ አለዚያማ በዚህ በታላቅ ሕዝብ ላይ ይፈርድ ዘንድ ማን ይችላል?”'),
  ('06892bd5-c766-5e02-a0b7-3dbea2fef9db', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 10, 10, 'ሰሎሞንም ይህን ነገር ስለ ለመነ፥ ነገሩ እግዚአብሔርን ደስ አሰኘው።'),
  ('1112d4c7-33c8-5763-a756-7d06f79ac43c', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 11, 11, 'እግዚአብሔርም አለው፥ “ፍርድን ትለይ ዘንድ ለራስህ ማስተዋልን ለመንህ እንጂ ለራስህ ብዙ ዘመናትን፥ ባለጠግነትንም፥ የጠላቶችህንም ነፍስ ሳትለምን ይህን ነገር ለምነሃልና፥'),
  ('f49cb1b8-1b07-52ba-a2f8-5955d2293422', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 12, 12, 'እነሆ፥ እኔ እንደ ቃልህ አድርጌልሃለሁ፤ እነሆም፥ ማንም የሚመስልህ ከአንተ በፊት እንደሌለ፥ ከአንተም በኋላ እንዳይነሣ አድርጌ ጥበበኛና አስተዋይ ልቡና ሰጥቼሃለሁ።'),
  ('bd2cb4da-8cfd-51a9-acf1-590a41779aa6', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 13, 13, 'ደግሞም ከነገሥታት የሚመስልህ ማንም እንዳይኖር ያልለመንኸውን ባለጠግነትና ክብር ሰጥቼሃለሁ።'),
  ('be7357c8-3ed9-543a-aaef-16a0e180b8d0', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 14, 14, 'አባትህም ዳዊት እንደ ሄደ፥ ሥርዐቴንና ትእዛዜን ትጠብቅ ዘንድ በመንገዴ የሄድህ እንደ ሆነ፥ ዘመንህን አበዛልሀለሁ።”'),
  ('0a3ac3c9-d571-516d-abdd-75526800c9ca', '2040e538-8ee5-511a-a141-34122d2a270b', 'c87904d1-14b6-5346-a932-5d0aaee471a6', 15, 15, 'ሰሎሞንም ነቃ፤ እነሆም፥ ሕልም ነበረ፤ ተነሥቶም ወደ ኢየሩሳሌም ሄደ፤ በጽዮንም በእግዚአብሔር ቃል ኪዳን ታቦት ፊት ቆመ፤ የሚቃጠለውንም መሥዋዕት አሳረገ፤ የደኅንነትንም መሥዋዕት አቀረበ፤ ለአገልጋዮቹም ሁሉ ታላቅ ግብዣ አደረገ።'),
  ('b2e97c5f-41e7-542b-a763-366b22efe089', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 1, 16, 'በዚያ ጊዜም ሁለት ጋለሞታዎች ሴቶች ወደ ንጉሡ መጥተው ቆሙ።'),
  ('693bc9d3-2cf9-546b-a3c3-3cc37ae5fc7a', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 2, 17, 'አንደኛዪቱም ሴት አለች፥ “ጌታዬ ሆይ! ስማኝ፥ እኔና ይህች ሴት በአንድ ቤት እንኖራለን፤ በአንድ ቤትም ወለድን።'),
  ('efa414c7-1913-5522-a525-36e1b57b44c0', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 3, 18, 'እኔም በወለድሁ በሦስተኛው ቀን ይህች ሴት ወለደች፤ እኛ በቤት ውስጥ አብረን ነበርን፤ ከሁለታችንም በቀር ማንም በቤት ውስጥ አልነበረም።'),
  ('c33e7d04-5a8b-5ad4-a03a-23cc3af94578', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 4, 19, 'እርስዋም በላዩ ስለ ተኛችበት የዚህች ሴት ልጅ በሌሊት ሞተ።'),
  ('2091b6a1-6103-5f7d-a18e-80d1c20ecd74', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 5, 20, 'እርስዋም በእኩለ ሌሊት ተነሥታ፥ እኔ አገልጋይህ ተኝቼ ሳለሁ፥ ልጄን ከብብቴ ወሰደች፤ በብብቷም አስተኛችው፤ የሞተውንም ልጅዋን በእኔ ብብት አስተኛችው።'),
  ('26db8dfc-41c5-5adc-a00f-615445cf5bfe', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 6, 21, 'ልጄንም አጠባ ዘንድ በማለዳ ብነሣ፥ ያን የሞተውን ልጅ አገኘሁ፤ ነገር ግን ብርሃን በሆነ ጊዜ ተመለከትሁት፤ እነሆም፥ የወለድሁት ልጄ አልነበረም።”'),
  ('1384e3bf-0cde-5c81-ae42-c4a756cc6ef6', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 7, 22, 'ሁለተኛዪቱም ሴት፥ “አይደለም ደኅነኛው የእኔ ልጅ ነው፤ የሞተው የአንቺ ልጅ ነው እንጂ አለች።” እንዲሁም በንጉሡ ፊት ይነጋገሩ ነበር።'),
  ('0f18a27f-3448-5e04-a2fa-6ac2bd7b2efa', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 8, 23, 'በዚያ ጊዜም ንጉሡ፥ “አንቺ፦ ደኅነኛው የእኔ ልጅ ነው፤ የሞተውም የአንቺ ልጅ ነው ትያለሽ፤ አንቺም፦ አይደለም የሞተው የአንቺ ልጅ ነው፤ ደኅነኛውም የእኔ ልጅ ነው ትያለሽ”። አላቸው።'),
  ('8a9b1eda-7841-570d-a020-97fb367cdee5', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 9, 24, 'ንጉሡም፥ “ሰይፍ አምጡልኝ” አለ፤ እነርሱም ወደ ንጉሡ ሰይፍ አመጡ።'),
  ('da8aaa79-bcf7-5703-a36d-32325a538d18', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 10, 25, 'ንጉሡም፥ “ደኅነኛውን ሕፃን ለሁለት ቈርጣችሁ ለአንዲቱ አንዱን ክፍል፥ ለሁለተኛዪቱም ሁለተኛውን ክፍል ስጡ” አለ።'),
  ('bf9af356-4f71-534e-ae6b-4df8a67e49b5', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 11, 26, 'ደኅነኛውም ሕፃን የነበራት ሴት አንጀትዋ ስለ ልጅዋ ታውኳልና፥ “ጌታዬ ሆይ! አይደለም፤ ደኅነኛውን ለእርስዋ ስጣት እንጂ መግደልስ አትግደሉት” ብላ ለንጉሡ ተናገረች። ያችኛዪቱ ግን፥ “አካፍሉን እንጂ ለእኔም ለእርስዋም አይሁን” አለች።'),
  ('8a7b08a6-92b6-56cd-a58a-3fb13d605fd8', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 12, 27, 'ንጉሡም መልሶ እንዲህ አለ፥ “ለእርስዋ ስጧት እንጂ መግደልስ አትግደሉት ላለችው ሴት ስጡአት፤ እናቱ እርስዋ ናትና።”'),
  ('581cf56e-1b1f-55e1-ac10-42ff9ecb2141', '2040e538-8ee5-511a-a141-34122d2a270b', '749967c6-c910-545a-abc9-26e5edd21a63', 13, 28, 'ንጉሡም የፈረደውን ፍርድ እስራኤል ሁሉ ሰሙ፤ ፍርድን ለማድረግ የእግዚአብሔር ጥበብ በእርሱ ላይ እንደ ነበረ አይተዋልና ከንጉሡ ፊት የተነሣ ፈሩ።'),
  ('254c2841-ff7e-50ae-a47e-bc5ed22537ba', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 1, 1, 'ንጉሡም ሰሎሞን በእስራኤል ሁሉ ላይ ነግሦ ነበር።'),
  ('ca5befb6-fdc0-5a63-a593-6e5681e38bf4', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 2, 2, 'የነበሩትም አለቆች እነዚህ ናቸው፥ የሳዶቅ ልጅ ካህኑ ዓዛርያስ፤'),
  ('f01f413c-af19-535f-ab88-55bdcc203da8', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 3, 3, 'ጸሓፊዎቹም የሱባ ልጆች ኤልያብና አኪያ፥ ታሪክ ጸሓፊውም የአሒሉድ ልጅ ኢዮሣፍጥ ነበረ።'),
  ('4d62a7ad-a7d8-5794-a085-07edab404ee9', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 4, 4, 'የዮዳሄም ልጅ በንያስ የሠራዊት አለቃ ነበረ፤ ሳዶቅና አብያታርም ካህናት ነበሩ፤'),
  ('c31facbd-77b3-524f-ae44-e0595805116c', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 5, 5, 'የናታንም ልጅ ኦርኒያ የሹሞች አለቃ ነበረ፤ የናታንም ልጅ ዘባት የንጉሡ አማካሪና ወዳጅ ነበረ፤'),
  ('0606d308-d20b-540b-a44d-663b543950a6', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 6, 6, 'አኪያልም የቤት አዛዥ፥ ኤልያቅም የቤት አዛዦች አለቃ ነበረ፥ የሳፋን ልጅ ኤልያፍም የቤተ ሰብ ሐላፊ፥ የአዶን ልጅ አዶኒራምም ግብር አስገባሪ ነበረ።'),
  ('87bf0f56-60c5-5e8d-a02e-a8e0fbfbd48c', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 7, 7, 'ሰሎሞንም ለንጉሡና ለቤተሰቡ ቀለብ የሚሰጡ በእስራኤል ሁሉ ላይ ዐሥራ ሁለት ሹሞችን ሾመ። ከዓመቱ ውስጥ እያንዳንዱን ወር እያንዳንዳቸው ይቀልቡ ነበር።'),
  ('bb22264f-e337-59c9-ac98-a4636e92c99b', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 8, 8, 'ስማቸውም ይህ ነበረ፤ በተራራማው ሀገር በኤፍሬም የሖር ልጅ ቢዖር፥'),
  ('205e5ca7-1f7f-5eb3-aaa4-dfb49040464b', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 9, 9, 'በማኪስና በሰአልቢን፥ በቤት ሳሚስና በኤሎንቤትሐናን የዴቀር ልጅ፥'),
  ('9530f4b3-8f11-5de0-a648-045e17cfdd34', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 10, 10, 'በአራቦት፥ በሶኮትና በኦፌር ሀገር ሁሉ የሔሴድ ልጅ ነበረ፤'),
  ('52ecc125-47be-5420-aa55-8302bac07b4d', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 11, 11, 'በዶር ሀገር ዳርቻ ሁሉ የአሚናዳብ ልጅ ነበረ፤ ለእርሱም የሰሎሞን ልጅ ጣፈትም ሚስቱ ነበረች፤'),
  ('cf05d3b6-f121-54fa-aa2e-b962f1e2bd7a', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 12, 12, 'ከቤትሳን ጀምሮ እስከ አቤልምሖላና እስከ ዮቅምዓም ማዶ ድረስ በታዕናክና በመጊዶ በጸርታንም አጠገብ በኢይዝራኤል በታች ባለው በቤትሳን ሁሉ የአሒሉድ ልጅ በዓና ነበረ፤'),
  ('542645ce-a862-5417-aa25-2d14eb0a3cb9', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 13, 13, 'በሬማት ዘገለዓድ የጌቤር ልጅ ነበረ፤ ለእርሱም በገለዓድ ያሉት የምናሴ ልጅ የኢያዕር መንደሮች ነበሩ፤ ለእርሱም ደግሞ በባሳን፥ በአርጎብ ዳርቻ ያሉት ቅጥርና የናስ መወርወሪያዎች የነበረባቸው ስድሳ ታላላቅ ከተሞች ነበሩበት፤'),
  ('2dbf7e5f-9765-5fd3-a836-0b188562f770', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 14, 14, 'በማሃናይም የሳዶ ልጅ አሒናዳብ ነበረ፤'),
  ('e0c2ee2d-35f2-5e46-aa7e-1f393fbb3b46', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 15, 15, 'በንፍታሌምም አኪማኦስ ነበረ፤ እርሱም የሰሎሞንን ልጅ ባሴማትን አግብቶ ነበር፤'),
  ('69a8e98e-9398-5051-ab15-f33d1e6a34e8', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 16, 16, 'በአሴርና በበዓሎት የኩሲ ልጅ በዓና ነበረ፤'),
  ('77f57d91-4a06-5b9f-ac6f-67bd8da8b032', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 17, 17, 'በይሳኮርም የፋሩዋ ልጅ ኢዮሣፍጥ ነበረ፤'),
  ('e1e054d6-3cab-51a8-aa76-22c7be9f3a8c', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 18, 18, 'በብንያም የኤላ ልጅ ሳሚ ነበረ፤'),
  ('d9d6ae96-ae83-5ae1-a9bd-97ec1473c18e', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 19, 19, 'በአሞራውያን ንጉሥ በሴዎንና በባሳን ንጉሥ በዐግ ሀገር፥ በጋድ ሀገር፥ የአዴ ልጅ ጌቤር ነበረ፤ በይሁዳም ምድር ላይ እርሱ ብቻውን ሹም ነበረ።'),
  ('e2df90fb-00fd-58ac-aef7-69d877115ef7', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 20, 20, 'ይሁዳና እስራኤልም እንደ ባሕር አሸዋ ብዛት ብዙ ነበሩ፤ ይበሉና ይጠጡም፥ ደስም ይላቸው ነበር።'),
  ('20f7b942-8774-5d84-a959-c4e3d79e6373', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 21, 21, 'ሰሎሞንም ከወንዙ ጀምሮ እስከ ግብፅ ምድር ዳርቻ እስከ ፍልስጥኤማውያን ሀገር ድረስ በመንግሥታት ሁሉ ላይ ነግሦ ነበር፤ ግብርም ያመጡለት ነበር፤ በዕድሜውም ሙሉ ለሰሎሞን ይገዙ ነበር።'),
  ('fd85e594-87e7-526e-ab37-644aa452c74a', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 22, 22, 'ለሰሎሞንም ለቀን ለቀኑ ቀለብ የሚሆን ሠላሳ ቆሮስ መልካም ዱቄትና ስድሳ ቆሮስ መናኛ ዱቄት፤'),
  ('54468a9f-ae60-50dc-a322-0ac641fb3cd9', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 23, 23, 'ከዋሊያና ከሚዳቋ፥ ከበረሃ ፍየልና ከሰቡ ወፎች በቀር ዐሥር ፍሪዳዎች፥ ሃያም የተሰማሩ በሬዎች፥ አንድ መቶም በጎች ነበረ።'),
  ('b7de787c-28ba-519e-a444-09b5cfdfe1d5', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 24, 24, 'ከወንዙ ወዲህ ባሉት ነገሥታት ሁሉ፥ ከወንዙም ወዲህ ባለው ሀገር ሁሉ ላይ ከቲላሳ ጀምሮ እስከ ጋዛ ድረስ ነግሦ ነበር፤ በዙሪያውም ባለው በሁሉ ወገን ሰላም ሆኖለት ነበር።'),
  ('115d60f7-a815-5b19-a470-ec7a291bbf60', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 25, 25, 'በሰሎሞንም ዘመን ሁሉ ይሁዳና እስራኤል ከዳን ጀምሮ እስከ ቤርሳቤህ ድረስ እያንዳንዳቸው ከወይኑና ከበለሱ በታች ተዘልለው ይቀመጡ ነበር።'),
  ('fdee030b-cdcb-5898-a97e-50a7a6bc8e0a', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 26, 26, 'ለሰሎሞንም ሰረገላ የሚስቡ አርባ ሺህ ፈረሶች፥ ዐሥራ ሁለት ሺህ ፈረሰኞች ነበሩት።'),
  ('e67e2de4-351f-5de4-a7a2-7ecb0e5e3bbd', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 27, 27, 'እነዚያም ሹሞች እያንዳንዱ በየወሩ ንጉሡን ሰሎሞንንና ወደ ንጉሡ ወደ ሰሎሞን ማዕድ የሚቀርቡትን ሁሉ ይቀልቡ ነበር፤ ምንም አያጐድሉም ነበር።'),
  ('3c312251-72c2-5f58-a95c-93994b1c3f44', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 28, 28, 'እያንዳንዱም እንደ ደንቡ የንጉሡን ሰረገላዎች ለሚስቡ ለፈረሶችና ለሰጋር በቅሎዎች ገብስና ገለባ፥ እንዲሁም ዕቃዎችን ወደ ስፍራቸው ያመጡ ነበር።'),
  ('b16cb9f4-6e2e-5f04-a1d1-2230d9670cb3', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 29, 29, 'እግዚአብሔርም ለሰሎሞን እጅግ ብዙ ጥበብንና ማስተዋልን፥ በባሕርም ዳር እንዳለ አሸዋ የልብ ስፋትን ሰጠው።'),
  ('1813689d-6754-564e-ab96-4e9b29e5b834', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 30, 30, 'የሰሎሞንም ጥበብ ከቀደሙ ሰዎች ሁሉ ጥበብና ከግብፅ ጥበብ ሁሉ በዛ።'),
  ('849d482d-c407-53c9-a270-e1f74cdf8adc', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 31, 31, 'ከሰዎችም ሁሉ ይልቅ ብልህ ነበረ፤ ከኢይዝራኤላዊው ከኤታንና ከማሖል ልጆች ከአውናንና ከከልቀድ፥ ከደራልም ይልቅ ጥበበኛ ነበረ። በዙሪያውም ባሉ አሕዛብ ሁሉ ዝናው ወጣ።'),
  ('fd5b470e-b969-5588-a72a-b486f41d76d6', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 32, 32, 'ሰሎሞንም ሦስት ሺህ ምሳሌዎችን ተናገረ፤ መሐልዩም አንድ ሺህ አምስት ነበረ።'),
  ('9e382ed8-6a95-5bd4-a5cc-8a126a313607', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 33, 33, 'ስለ ዛፍም ከሊባኖስ ዝግባ ጀምሮ በቅጥር ግንብ ላይ እስከሚበቅለው እስከ አሽክት ድረስ ይናገር ነበር፤ ደግሞም ስለ አውሬዎችና ስለ ወፎች ስለ ተንቀሳቃሾችና ስለ ዓሣዎች ይናገር ነበር።'),
  ('f4559989-39d6-5f8c-a7f9-280c255eea6e', '183d8d50-1b61-5044-a502-c39a83e984f2', 'ff32a02a-5fe7-5b9c-a847-c298d263e0b4', 34, 34, 'ከአሕዛብም ሁሉ፥ ጥበቡን ሰምተው ከነበሩ ከምድር ነገሥታት ሁሉ የሰሎሞንን ጥበብ ለመስማት ሰዎች ይመጡ ነበር።'),
  ('dc937b77-1cf8-53ac-ad63-125a6a6f5f48', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 1, 1, 'የጢሮስ ንጉሥ ኪራም ለአባቱ ለዳዊት በዘመኑ ሁሉ ወዳጁ ስለ ነበረ፥ ሰሎሞን በአባቱ ፋንታ ንጉሥ ለመሆን እንደ ተቀባ ሰምቶ አገልጋዮቹን ወደ ሰሎሞን ላከ።'),
  ('e7bbd712-07d3-5083-a773-5e3fd5e5d0e8', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 2, 2, 'ሰሎሞንም ወደ ኪራም እንዲህ ብሎ ላከ፦'),
  ('f3002fbb-4e53-55f3-a3fe-9891debb130c', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 3, 3, '“እግዚአብሔር ከእግሩ በታች እስኪጥልለት ድረስ በዙሪያው ስለ ነበረ ጦርነት አባቴ ዳዊት ለአምላኩ ለእግዚአብሔር ስም ቤት መሥራት እንዳልቻለ አንተ ታውቃለህ።'),
  ('72cfad86-072e-5511-a62e-c4e8a6098591', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 4, 4, 'አሁንም አምላኬ እግዚአብሔር በዙሪያዬ ካሉት ዕረፍት ሰጥቶኛል፤ ክፉም ነገር የሚያደርግ ጠላት የለብኝም።'),
  ('0097667a-8e87-54f1-a800-aea5376808bc', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 5, 5, 'እነሆም፥ እግዚአብሔር ለአባቴ ለዳዊት፦ በአንተ ፋንታ በዙፋንህ ላይ የማስቀምጠው ልጅህ እርሱ ለስሜ ቤት ይሠራል ብሎ እንደ ነገረው፥ ለአምላኬ ለእግዚአብሔር ስም ቤት እሠራ ዘንድ አስባለሁ።'),
  ('5d15cc7a-f70d-5a47-a978-01a6b94ec1ed', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 6, 6, 'አሁንም ከወገኔ እንደ ሲዶናውያን እንጨት መቍረጥ የሚያውቅ እንደሌለ ታውቃለህና የዝግባ ዛፍ ከሊባኖስ ይቈርጡልኝ ዘንድ አገልጋዮችህን እዘዝ፤ አገልጋዮቼም ከአገልጋዮችህ ጋር ይሁኑ፤ የአገልጋዮችህንም ዋጋ እንደ ተናገርኸው ሁሉ እሰጥሃለሁ።”'),
  ('fb77fdd0-fa1c-55d5-adc2-182b6f9ce476', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 7, 7, 'ኪራምም የሰሎሞንን ቃል ሰምቶ እጅግ ደስ አለውና፥ “በዚህ ታላቅ ሕዝብ ላይ ጥበበኛ ልጅ ለዳዊት የሰጠ እግዚአብሔር ዛሬ ይመስገን” አለ።'),
  ('46b2105a-4d04-53c8-a71a-7bf0ce26e6d8', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 8, 8, 'ኪራምም እንዲህ ሲል ወደ ሰሎሞን ላከ፥ “የላክህብኝን ሁሉ ሰማሁ፤ ስለ ዝግባውና ስለ ጥዱ እንጨት ፈቃድህን ሁሉ አደርጋለሁ።'),
  ('139a1e32-0808-59c9-a28d-b5db756a2890', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 9, 9, 'አገልጋዮቼ ከሊባኖስ ወደ ባሕር ያወርዱልሃል፤ እኔም በመርከብ አድርጌ በባሕር ላይ እያንሳፈፍሁ አንተ እስከ ወሰንኸው ስፍራ ድረስ አደርስልሃለሁ፤ በዚያም እፈታዋለሁ፤ አንተም ከዚያ ታስወስደዋለህ፤ አንተም ፈቃዴን ታደርጋለህ፤ ለቤተ ሰቦቼም ቀለብ የሚሆነውን ትሰጠኛለህ።”'),
  ('07652c57-0be1-5936-a6de-7dc1ec2b0c32', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 10, 10, 'እንዲሁም ኪራም የዝግባውንና የጥዱን እንጨት፥ የሚሻውንም ሁሉ ለሰሎሞን ሰጠው።'),
  ('8d02f2ac-9aff-58db-a8d3-88e2d7656706', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 11, 11, 'ሰሎሞንም ለኪራም ስለ ቤቱ ቀለብ ሃያ ሺህ የቆሮስ መስፈሪያ ስንዴ፥ ሃያ ሺህም በቤት መስፈሪያ ጥሩ ዘይት ይሰጠው ነበር፤ ሰሎሞንም ለኪራም በየዓመቱ ይህን ይሰጥ ነበር።'),
  ('dba0be53-5419-542b-a145-b6d349a6089c', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 12, 12, 'እግዚአብሔርም እንደ ነገረው ለሰሎሞን ጥበብን ሰጠው፤ በኪራምና በሰሎሞንም መካከል ሰላም ነበረ፤ በመካከላቸውም ቃል ኪዳን አደረጉ።'),
  ('83db1915-acb4-5899-aab0-c12a0f60c416', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 13, 13, 'ሰሎሞንም ከእስራኤል ሁሉ ገባሮቹን መርጦ አወጣ፤ የገባሮቹም ቍጥር ሠላሳ ሺህ ሰዎች ነበረ።'),
  ('4f0e1bae-b791-546b-a46b-b169ecc5f364', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 14, 14, 'በየወሩም እያፈራረቀ ወደ ሊባኖስ ዐሥር ዐሥር ሺህ ይልክ ነበር፤ አንድ ወርም በሊባኖስ፥ ሁለት ወርም በቤታቸው ይቀመጡ ነበር። አዶኒራምም የገባሪዎች አለቃ ነበረ።'),
  ('4f7c0a90-ba9a-5a1f-a208-45c8b52d73e8', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 15, 15, 'ለሰሎሞንም ሰባ ሺህ ተሸካሚዎች፥ ሰማንያ ሺህም በተራራው ላይ ድንጋይ የሚጠርቡ ጠራቢዎች ነበሩት።'),
  ('876442fa-93a5-568b-add8-5d47756726a6', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 16, 16, 'ይኸውም በሰሎሞን ሥራ ላይ ከተሾሙት ከሦስት ሺህ ስድስት መቶ የሠራተኞች አለቆች ሌላ ነው።'),
  ('66b318a0-5e87-59e6-a9fa-ef54c9483416', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 17, 17, 'ንጉሡም የለዘቡ ታላላቅ ድንጋዮችንና ለቤቱም መሠረት ያልተጠረበውን ድንጋይ ያመጡ ዘንድ አዘዘ።'),
  ('2299c550-ec64-5945-a2ad-70619d655769', '902d7897-a11f-5588-a5ef-16cc18573105', '29467790-63ba-556f-a43e-146b181781d6', 18, 18, 'የሰሎሞንና የኪራም አናጢዎች፥ ጌባላውያንም ወቀሩአቸው፤ ለመሠረትም አኖሩአቸው፤ ቤቱንም ለመሥራት እንጨቱንና ድንጋዮቹን ሦስት ዓመት አዘጋጁ።'),
  ('f841a313-b200-51d2-ab16-966f8cdb74a5', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 1, 1, 'የእስራኤል ልጆች ከግብፅ ምድር ከወጡ አራት መቶ ሰማንያ አራት ዓመት በሆነ ጊዜ፥ ሰሎሞን በእስራኤል ላይ በነገሠ በአራተኛው ዓመት፥ ዚፍ በሚባለው በሁለተኛው ወር የእግዚአብሔርን ቤት መሥራት ጀመረ።'),
  ('d7df2098-7849-5014-a09e-3c2901831bfe', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 2, 2, 'ንጉሡ ሰሎሞንም ለእግዚአብሔር የሠራው ቤት ርዝመቱ ስድሳ ክንድ፥ ወርዱም ሃያ ክንድ፥ ቁመቱም ሠላሳ ክንድ ነበረ።'),
  ('67668c29-d606-5016-acad-fb1f4e3c817c', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 3, 3, 'በመቅደሱም ፊት ወለል ነበረ፤ ርዝመቱም እንደ መቅደሱ ወርድ ሃያ ክንድ፥ ወርዱም ከቤቱ ወደ ፊት ዐሥር ክንድ ነበረ፤ ቤቱንም ሠርቶ ጨረሰ።'),
  ('e7fe3e9f-e885-59ae-ab43-525a9b7fcefc', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 4, 4, 'ለቤቱም በዐይነ ርግብ የተዘጉ መስኮቶችን አደረገ።'),
  ('69aa5e65-7844-5416-af5b-64015383cbb6', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 5, 5, 'በቤቱም ግንብ ዙሪያ፥ በመቅደሱና በቅድስተ ቅዱሳኑ ግንብ ዙሪያ ደርብ ሠራ፤ በዙሪያውም ጓዳዎች አደረገ።'),
  ('9bf7d2ea-86cf-5c8f-af84-84cfc49f1761', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 6, 6, 'የታችኛውም ደርብ ወርዱ አምስት ክንድ፥ የመካከለኛውም ደርብ ወርዱ ስድስት ክንድ፥ የሦስተኛውም ደርብ ወርዱ ሰባት ክንድ ነበረ። ሰረገሎቹ በቤቱ ግንብ ውስጥ እንዳይገቡ ከቤቱ ግንብ ውጭ አረፍቶችን አደረገ።'),
  ('7f6d9cdf-d702-5095-a271-37e7665e1d8c', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 7, 7, 'ቤቱም በተሠራ ጊዜ ፈጽመው በተወቀሩ ድንጋዮች ተሠራ፤ ሲሠሩትም መራጃና መጥረቢያ፥ የብረትም ዕቃ ሁሉ በቤቱ ውስጥ አልተሰማም።'),
  ('fb9d36f9-2fb8-5091-ac27-4fb73f64fb14', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 8, 8, 'የታችኛውም ደርብ ጓዳዎች በር በቤቱ ቀኝ አጠገብ ነበረ። ከዚያም ወደ መካከለኛው ደርብ፥ ከመካከለኛውም ወደ ሦስተኛው ደርብ የሚወጡበት መውጫ ነበረው።'),
  ('c79179a9-3246-5da8-a2ae-13fdba1d382c', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 9, 9, 'ቤቱንም ሠርቶ ፈጸመው፤ የቤቱንም ጠፈር በዝግባ ሳንቃዎች አደረገ።'),
  ('1af02229-62e8-50bb-ad58-60660c2d6132', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 10, 10, 'በቤቱም ዙሪያ ሁሉ ቁመታቸው አምስት አምስት ክንድ የሆኑ ደርቦችን ሠራ፤ ከቤቱም ጋር በዝግባ እንጨት አጋጠማቸው።'),
  ('7fa57b61-86ec-5b01-ad83-36a5db348101', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 11, 11, 'የእግዚአብሔርም ቃል ወደ ሰሎሞን እንዲህ ሲል መጣ፦'),
  ('b4854ec4-3a8e-55b7-a083-ccfad5799899', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 12, 12, '“ስለዚህ ስለምትሠራልኝ ቤት በሥርዐቴ ብትሄድ፥ ፍርዴንም ብታደርግ፥ ትመላለስባቸውም ዘንድ ትእዛዞቼን ሁሉ ብትጠብቅ፥ ለአባትህ ለዳዊት የነገርሁትን ቃል ከአንተ ጋር አጸናለሁ።'),
  ('489db852-c310-52b2-a5f1-b7421ef3d941', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 13, 13, 'በእስራኤልም ልጆች መካከል እኖራለሁ፤ ሕዝቤንም እስራኤልን አልጥልም።”'),
  ('7a938d18-a632-5352-aa24-0e7c3643ea38', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 14, 14, 'ሰሎሞንም ቤቱን ሠራው፤ ፈጸመውም።'),
  ('f452e3b7-bddd-59ee-a872-a77bde925997', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 15, 15, 'የቤቱንም ግንብ ውስጡን በዝግባ ሳንቃ ለበጠ፤ ከቤቱም መሠረት ጀምሮ እስከ ጣራው ድረስ የውስጡን ግንብ በእንጨት ለበጠው፤ ደግሞም የቤቱን ወለል በጥድ እንጨት አነጠፈው።'),
  ('d34bbe9d-c40c-593b-affe-519f7b616652', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 16, 16, 'ከቤተ መቅደሱ አያይዞ ከመሠረቱ ጀምሮ እስከ ጣራው ድረስ ሃያውን ክንድ በዝግባ ጠርብ ሠራ፤ ከመቅደሱም ከፍሎ ቅድስተ ቅዱሳኑን አደረገ።'),
  ('309b4629-f59a-5080-aa54-89a51643c127', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 17, 17, 'በቅድስተ ቅዱሳኑ ፊት ያለውም መቅደስ ርዝመቱ አርባ ክንድ ነበረ።'),
  ('969b6154-46ef-535f-a95d-7f62b5a68182', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 18, 18, 'የቤቱንም ውስጥ በተጐበጐበና በፈነዳ አበባ፥ በተቀረጸ ዝግባ ለበጠው፤ ሁሉም ዝግባ ነበረ፤ ድንጋዩም አልታየም ነበር።'),
  ('18857cc4-d013-5f11-a281-b7c0dd218c37', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 19, 19, 'በዚያም የእግዚአብሔርን ቃል ኪዳን ታቦት ያኖር ዘንድ በቤቱ ውስጥ ቅድስተ ቅዱሳኑን አበጀ።'),
  ('426b9da1-6366-5540-aed1-a2cda3b01c7e', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 20, 20, 'የቅድስተ ቅዱሳኑም ርዝመት ሃያ ክንድ፥ ስፋቱም ሃያ ክንድ፥ ቁመቱም ሃያ ክንድ ነበረ፤ በጥሩም ወርቅ ለበጠው።'),
  ('55461d17-baa5-55ed-a96c-de58a694f81b', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 21, 21, 'በቅድስተ ቅዱሳኑም ፊት ከዝግባ መሠዊያን ሠራ፤ በጥሩ ወርቅም ለበጠው።'),
  ('cbed686e-34a1-5e80-a703-2c7b960bdf53', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 22, 22, 'የሠራው ቤት ሁሉ እስከ ተፈጸመ ድረስ ቤቱን ሁሉ በወርቅ ለበጠው፤ በቅድስተ ቅዱሳኑም ፊት የነበረውን መሠዊያ ሁሉ በወርቅ ለበጠው።'),
  ('0e15c68b-ed90-5bbb-a0a6-b6c5adcab72f', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 23, 23, 'በቅድስተ ቅዱሳኑም ውስጥ ቁመታቸው ዐሥር ክንድ የሆነ ከወይራ እንጨት ሁለት ኪሩቤልን ሠራ።'),
  ('ead6e6de-521d-5b42-afbe-f1a7d5bafa26', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 24, 24, 'የኪሩብም አንደኛው ክንፍ አምስት ክንድ፥ የኪሩብም ሁለተኛው ክንፍ አምስት ክንድ ነበረ፤ ከአንደኛው ክንፍ ጫፍ ጀምሮ እስከ ሁለተኛው ክንፍ ጫፍ ድረስ ዐሥር ክንድ ነበረ።'),
  ('c54fe707-550c-5b65-aca2-d5f8ced60a8a', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 25, 25, 'እንደዚሁም ሁለተኛው ኪሩብ ዐሥር ክንድ ነበረ፤ ሁለቱም ኪሩቤል አንድ ልክና አንድ መልክ ነበሩ።'),
  ('436fea72-77ce-5273-a73b-5ddeeb645dc9', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 26, 26, 'የአንዱ ኪሩብ ቁመት ዐሥር ክንድ ነበረ፤ የሁለተኛውም ኪሩብ እንዲሁ ነበረ።'),
  ('12f3a612-a3a4-5a5b-a2cf-e67e6ff040dd', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 27, 27, 'ሁለቱም ኪሩቤል በውስጠኛው ቤት መካከል ነበሩ። የኪሩቤልም ክንፎቻቸው ተዘርግተው ነበር፤ የአንዱም ኪሩብ ክንፍ አንደኛውን ግንብ ይነካ ነበር፤ የሁለተኛውም ኪሩብ ክንፍ ሁለተኛውን ግንብ ይነካ ነበር፤ የሁለቱም ክንፎች በቤቱ መካከል እርስ በርሳቸው ይነካኩ ነበር።'),
  ('20079f9b-7a17-5c39-a0f7-3262690a2dfd', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 28, 28, 'ኪሩቤልንም በወርቅ ለበጣቸው።'),
  ('f9de6b79-d792-5cf0-a250-fd847f51f462', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 29, 29, 'በቤቱም ግንብ ሁሉ ዙሪያ በውስጥና በውጭ የኪሩቤልና የዘንባባ ዛፍ፥ የፈነዳም አበባ ሥዕል ቀረጸ።'),
  ('d65b1356-11b5-55c2-a7ec-0b8f378e7bc5', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 30, 30, 'የቤቱንም ወለል በውስጥና በውጭ በወርቅ ለበጠ።'),
  ('d3cb0b0f-2768-5bee-ab1c-496fa821bbf2', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 31, 31, 'ለቅድስተ ቅዱሳኑም መግቢያ ከወይራ እንጨት ሳንቃዎችን ሠራ፤ መድረኩንና መቃኖቹን፥ ደፉንም አምስት ማዕዘን አደረገ።'),
  ('9f0de35d-a0bd-558a-ace3-8156989e4627', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 32, 32, 'ሁለቱንም ሣንቃዎች ከወይራ እንጨት ሠራ፤ የኪሩቤልንና የዘንባባ ዛፍ፥ የፈነዳም አበባ ሥዕል ቀረጸባቸው፤ በወርቅም ለበጣቸው፤ ኪሩቤልንና የዘንባባውን ዛፍ በወርቅ ለበጠ።'),
  ('03833538-3d5b-50ca-abf1-8861052c8a8e', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 33, 33, 'እንዲሁም ለመቅደሱ መግቢያ ከወይራ እንጨት አራት ማዕዘን መቃን አደረገ።'),
  ('a38f6107-81ec-5977-a2aa-559465090ea3', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 34, 34, 'ሁለቱንም ደጆች ከጥድ እንጨት ሠራ፤ አንዱ ደጅ በማጠፊያ ከተያያዙ ከሁለት ሣንቃዎች ተሠራ፤ ሁለተኛውም ደጅ በማጠፊያ ከተያያዙ ከሁለት ሣንቃዎች ተሠራ።'),
  ('6331f6ef-52a4-5a8b-a6ed-45bba141da2d', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 35, 35, 'የኪሩቤልንና የዘንባባ ዛፍ፥ የፈነዳም አበባ ሥዕል ቀረጸባቸው፤ በተቀረጸውም ሥራ ላይ በወርቅ ለበጣቸው፤ እስከ መድረካቸውም የተያያዙ ነበሩ።'),
  ('384ced40-36e1-557b-aec0-c2ab23ffb5ff', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 36, 36, 'የውስጠኛውንም አደባባይ ቅጥር ሦስቱን ተራ በተጠረበ ድንጋይ፥ አንዱንም ተራ በዝግባ ሣንቃ ሠራው፤ በመቅደሱ ፊት ለፊት ላለው ቤት ወለልም መጋረጃ ሠራ።'),
  ('964eaaa8-fc68-5472-a37d-0549aacc34fb', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 37, 37, 'በአራተኛው ዓመት ከሚያዝያ በሁለተኛው ወር የእግዚአብሔርን ቤት መሠረተ።'),
  ('195b3bf1-76cb-5bda-ae01-18c2b8c52c67', '8b156784-e607-581f-ad52-cbeada6d796d', 'e5fb1f89-638a-5283-ab8a-d7f0c46c031e', 38, 38, 'በዐሥራ አንደኛውም ዓመት ቡል በሚባል በስምንተኛው ወር ቤቱ እንደ ክፍሎቹና እንደ ሥርዐቱ ሁሉ ተጨረሰ። በሰባት ዓመትም ሠራው።'),
  ('8b647d33-bba6-590c-a3f3-3e97f501892d', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 1, 1, 'ሰሎሞንም የራሱን ቤት በዐሥራ ሦስት ዓመት ሠራ፤ የቤቱንም ሥራ ሁሉ ጨረሰ።'),
  ('9aaacbb9-02bb-51bf-aa80-7a978f337d8e', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 2, 2, 'የሊባኖስ ዱር ቤት የሚባል ቤትንም ሠራ፤ ርዝመቱንም መቶ ክንድ፥ ስፋቱንም አምሳ ክንድ፥ ቁመቱንም ሠላሳ ክንድ አደረገ፤ የዋንዛም እንጨት በሦስት ወገን በተሠሩ አዕማድ ላይ ቆሞ ነበር፤ በአዕማዱም ላይ የዋንዛ እንጨት አግዳሚ ሰረገሎች ነበሩ።'),
  ('5e11e428-3d7a-5639-a8e7-61fa167fe222', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 3, 3, 'በአዕማዱም ላይ በነበሩ አግዳሚዎች ቤቱ በዋንዛ ሳንቃ ተሸፍኖ ነበር፤ አዕማዱም በአንዱ ወገን ዐሥራ አምስት፥ በአንዱ ወገን ዐሥራ አምስት የሆኑ አርባ አምስት ነበሩ።'),
  ('98bba68d-785c-597e-a45b-0c1de514cfe8', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 4, 4, 'መስኮቶቹም በሦስት ወገን ነበሩ፤ መስኮቶቹም በሦስት ወገን ፊት ለፊት ይተያዩ ነበር።'),
  ('bf20e033-b561-5966-a189-a877b2b73ab7', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 5, 5, 'ደጆቹ፥ መቃኖቹና የታችኛውና የላይኛው መድረኮች ሁሉ አራት ማዕዘን ነበሩ፤ መስኮቶቹም በሦስት ወገን ሆነው ፊት ለፊት ይተያዩ ነበር።'),
  ('39866682-c560-5220-ae74-08121f8f990f', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 6, 6, 'አዕማዱም ያሉበትን ቤት ሠራ፤ ርዝመቱም አምሳ ክንድ፥ ስፋቱም ሠላሳ ክንድ ነበረ፤ በእርሱም ፊት ደግሞ ታላቅ አዕማድና መድረክ ያሉበት ወለል ነበረ።'),
  ('ceef3992-95ba-590d-a143-7c8313a5a21a', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 7, 7, 'የሚፈርድበትም የቤቱ ዙፋን በዚያ አለ። ለመፍረጃውም ቤትን ሠራ፤ ከላይ እስከ ታችም በዋንዛ እንጨት አያያዘው።'),
  ('15a438c3-7c08-5ced-a03d-f13b651759f4', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 8, 8, 'ከፍርድ ሰቀላ ወደ ውስጥ፥ በሌላውም አደባባይ ውስጥ የነበረውን የሚኖርበትን ቤት እንዲሁ ሠራ፤ እንደዚህም ቤት ያለ ቤትን ሰሎሞን ላገባት ለፈርዖን ልጅ ሠራ።'),
  ('aa6f7990-d178-5a8c-a769-293a6da30beb', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 9, 9, 'ይህም ሁሉ ከመሠረቱ ጀምሮ እስከ ጕልላቱ ድረስ በከበረና በተጠረበ በውስጥና በውጭ በልክ በተከረከመ ድንጋይ ተሠርቶ ነበር፤ በውጭውም እስከ ታላቁ አደባባይ ድረስ እንዲሁ ነበረ።'),
  ('7f270d76-2322-57e9-a722-85ffac788924', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 10, 10, 'መሠረቱም ዐሥር ዐሥር ክንድና ስምንት ስምንት ክንድ በሆኑ በከበሩ በታላላቅ ድንጋዮች ተሠርቶ ነበር።'),
  ('788a9a15-d01e-58dc-a802-cb60973a5ee4', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 11, 11, 'በላዩም ልክ ሆኖ የተከረከመ ጥሩ ድንጋይና የዝግባ ሣንቃ ነበረ።'),
  ('f52723eb-8855-548b-ab45-d938f18144af', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 12, 12, 'በታላቁም አደባባይ ዙሪያ የነበረው ቅጥር እንደ እግዚአብሔር ቤት እንደ ውስጠኛው አደባባይ ቅጥርና እንደ ቤቱ ወለል ሦስቱ ወገን በተጠረበ ድንጋይ አንዱም ወገን በዝግባ ሳንቃ ተሠርቶ ነበር።'),
  ('4585131b-e2a1-5d8b-a216-a93f98cbda54', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 13, 13, 'ንጉሡም ሰሎሞን ልኮ ኪራምን ከጢሮስ አስመጣ።'),
  ('1d98341a-1a27-5920-a977-dfefeff2d361', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 14, 14, 'እርሱም ከንፍታሌም ወገን የነበረች የባል አልባ ሴት ልጅ ነበረ፤ አባቱም የጢሮስ ሰው ናስ ሠራተኛ ነበረ፤ የናስንም ሥራ ሁሉ ይሠራ ዘንድ በጥበብና በማስተዋል፥ በብልሃትም ተሞልቶ ነበር። ወደ ንጉሡም ወደ ሰሎሞን መጥቶ ሥራውን ሁሉ ሠራ።'),
  ('f698dfd3-cf46-59f2-ade0-291e8dece13f', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 15, 15, 'በቤቱ ውስጥ ላለው ወለል ሁለቱን የናስ አዕማድ ሠራ፤ የአንዱም ዓምድ ቁመት ዐሥራ ስምንት ክንድ ነበረ፤ የዙሪያውም መጠን ዐሥራ ሁለት ክንድ ነበረ፤ የዓምዱም ውፍረት አንድ ጋት ነበረ፤ ውስጠ ክፍትም ነበረ። ሁለተኛውም ዓምድ እንዲሁ ነበረ።'),
  ('5c3caf47-09be-57ee-aff7-b142009fdb94', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 16, 16, 'በሁለቱም አዕማድ ራስ ላይ እንዲቀመጡ ከፈሰሰ ናስ ሁለት ጕልላትን ሠራ፤ የአንዱም ጕልላት ቁመት አምስት ክንድ፥ የሁለተኛውም ጕልላት ቁመት አምስት ክንድ ነበረ።'),
  ('093270f6-40cb-5043-a31b-cedc85e64492', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 17, 17, 'በአዕማዱም ራስ ላይ የነበሩትን ጕልላቶች ይሸፍኑ ዘንድ ሁለት እንደ መርበብ ሥራ አደረገ፤ አንዱም መርበብ ለአንዱ ጕልላት፥ ሁለተኛውም መርበብ ለሁለተኛው ጕልላት ነበረ።'),
  ('a4847232-539c-55fa-ad63-d5dea8f0a381', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 18, 18, 'ሮማኖችንም ሠራ፤ በአንድ ጕልላት ዙሪያ በሁለት ተራ፥ በአንድም መርበብ ላይ ሁለት ተራ ነበረ፤ እንዲሁም ለሁለተኛው ጕልላት አደረገ።'),
  ('a1e02a4d-43fd-5b50-a24f-7b8f3789d161', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 19, 19, 'በወለሉም አዕማድ በነበሩት ጕልላቶች ላይ የሱፍ አበባ የሚመስል ሥራ አራት ክንድ አድርጎ ቀረጸ።'),
  ('c91022c9-7ff8-5c58-a4a4-9fcbfb6f97d0', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 20, 20, 'በሁለቱም አዕማድ በነበሩት ጕልላቶች ላይ በመርበቡ ሥራ አጠገብ ሮማኖቹን አደረገ። ሮማኖቹም በአንዱ ወገን ሁለት መቶ ነበሩ። የሁለተኛውም ጕልላት እንዲሁ ነበረ።'),
  ('25ed3ea8-abfc-5707-ad48-d99b2b8534e1', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 21, 21, 'አዕማዱንም በመቅደሱ ወለል አጠገብ አቆማቸው፤ የቀኙንም ዓምድ አቁሞ ያቁም ብሎ ጠራው፤ የግራውንም ዓምድ አቁሞ በለዝ ብሎ ጠራው።'),
  ('479434e4-da8e-5062-aa95-0c2ef7363c00', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 22, 22, 'በአዕማዱም ራስ ላይ የሱፍ አበባ የሚመስል ሥራ አደረገ። እንዲሁም የአዕማዱ ሥራ ተጨረሰ።'),
  ('97489d9e-62e3-5319-a433-7edc5cdf213f', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 23, 23, 'ከፈሰሰም ናስ ከዳር እስከ ዳር ዐሥር ክንድ፥ ቁመቱም አምስት ክንድ፥ በዙሪያውም ሠላሳ ክንድ የሆነ ክብ ኩሬ ሠራ።'),
  ('79519741-e2f3-5a49-a32d-9577cf8965fc', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 24, 24, 'ከከንፈሩም በታች ለአንድ ክንድ ዐሥር፥ ለአንድ ክንድም ዐሥር ጕብጕቦች አዞረበት፤ ከንፈሮቹም እንደ ጽዋ ከንፈር ነበሩ። በውስጡም አበቦች በቅለውበት ነበር። ውፍረቱም ስንዝር ነበር።'),
  ('da70c6eb-099a-5e6c-a312-d89ad6f6a868', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 25, 25, 'ኩሬውም በዐሥራ ሁለት በሬዎች ምስል ላይ ተቀምጦ ነበር፤ ከእነርሱም ሦስቱ ወደ ሰሜን፥ ሦስቱም ወደ ምዕራብ፥ ሦስቱም ወደ ደቡብ፥ ሦስቱም ወደ ምሥራቅ ይመለከቱ ነበር። ኩሬውም በላያቸው ነበረ፤ የሁሉም ጀርባቸው በስተውስጥ ነበረ።'),
  ('48226d21-c40a-5d62-a893-323677539a51', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 26, 26, 'ውፍረቱም አንድ ጋት ነበረ። ከንፈሩም እንደ ጽዋ ከንፈር ተሠርቶ ነበር፤ እንደ ሱፍ አበባዎች ሆኖ ተከርክሞ ነበር። ሁለት ሺህም የባዶስ መስፈሪያ ይይዝ ነበር።'),
  ('8b903abd-a009-5f8d-a34f-57679344fe5c', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 27, 27, 'ዐሥርም የናስ መቀመጫዎችን ሠራ፤ የአንዱም መቀመጫ ርዝመት አራት ክንድ፥ ወርዱም አራት ክንድ፥ ቁመቱም ሦስት ክንድ ነበረ።'),
  ('28ee0f2b-6f86-5734-a478-033c0c1dc618', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 28, 28, 'መቀመጫዎችንም እንዲሁ ሠራ፤ እርስ በርሳቸውም አያይዞ ሰንበር ባለው ክፈፍ ሠራቸው።'),
  ('545fd0e8-ee9d-5c64-a351-b7c5f4b77246', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 29, 29, 'በክፈፎቹም መካከል በነበሩ ሰንበሮች ላይ አንበሳዎችና በሬዎች፥ ኪሩቤልም ነበሩ፤ እንዲሁም በክፈፎቹ ላይ ነበረ፤ ከአንበሳዎቹና ከበሬዎቹ በታች ሻኩራ የሚመስል ተንጠልጥሎ ነበር።'),
  ('971e5e1b-58d6-5011-a7e8-e13974c9342a', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 30, 30, 'በየመቀመጫዎቹም ሁሉ አራት የናስ መንኰራኵሮች ነበሩባቸው፤ መንኰራኵሮቹም የሚዞሩበትን የናስ ወስከምት ሠራ፤ ከመታጠቢያውም ሰን በታች በአራቱ ማዕዘን በኩል አራት በምስል የፈሰሱ እግሮች ነበሩ።'),
  ('9d94408e-0d32-51b2-a157-defe61d2e15b', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 31, 31, 'በክፈፉም ውስጥ የነበረ አንገት አንድ ክንድ ነበረ፤ አንገቱም ድቡልቡል ነበረ፤ ቁመቱም ክንድ ተኩል ነበረ። በአንገቱም ላይ ቅርጽ ነበረበት፤ ክፈፉ ግን አራት ማዕዘን ነበረ እንጂ ድቡልቡል አልነበረም።'),
  ('e6dca016-b505-5d5e-a5d9-4a80a21ea878', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 32, 32, 'አራቱም መንኰራኵሮች ከሰንበሮቹ በታች ነበሩ፤ የመንኰራኵሮቹም ወስከምት በመቀመጫው ውስጥ ነበረ፤ የመንኰራኵሩም ቁመት ክንድ ተኩል ነበረ።'),
  ('4d6b81c6-64d5-5d2b-a789-e129b60cb48f', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 33, 33, 'የመንኰራኵሮቹም ሥራ እንደ ሰረገላ መንኰራኵር ሥራ ነበረ፤ ወስከምቶቹና የመንኰራኵሮቹ ክፈፍ፥ ቅትርቶቹም፥ ወስከምቱ የሚገባበት ቧምቧ ሁሉ በምስል የፈሰሰ ነበር።'),
  ('e1d5af1e-ab51-501b-a8dd-ec5e8963e032', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 34, 34, 'በየአንዳንዱም መቀመጫ በአራቱ ማዕዘን በኩል አራት ደገፋዎች ነበሩ፤ ደገፋዎቹም ከመቀመጫው ጋር ተጋጥመው ነበር።'),
  ('d2fa791f-de73-595c-a88d-edd6b7174c6a', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 35, 35, 'በመቀመጫውም ራስ ላይ ስንዝር የሚሆን ድቡልቡል ነገር ነበረ፤ በመቀመጫውም ላይ የነበሩ መያዣዎችና ሰንበሮች ከእርሱ ጋር ይጋጠሙ ነበረ፤ ከላይም ክፍት ነበረ፤'),
  ('14d990ba-c2f9-59bb-a956-15569edb6793', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 36, 36, 'በክፈፎቻቸውም ኪሩቤልና አንበሶች የዘንባባ ዛፎችም ነበሩ፤ እያንዳንዱም ፊት ለፊት በስተውስጥና በዙሪያው ተያይዞ ነበር።'),
  ('fd075091-8e0e-5bde-a5cf-acd69a11da38', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 37, 37, 'እንዲሁም ዐሥሩን መቀመጫዎች ሠራ፤ ሁሉም በመጠን፥ በንድፍም ትክክሎች ነበሩ።'),
  ('a1c725ab-9af6-572e-a244-a60cd5e3434c', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 38, 38, 'ዐሥሩንም የናስ መታጠቢያ ሰን ሠራ፤ አንዱ መታጠቢያ ሰን አርባ የባዶስ መስፈሪያ ያነሣ ነበር፤ እያንዳንዱም መታጠቢያ ሰን አራት ክንድ ነበረ፤ በዐሥሩም መቀመጫዎች ላይ በእያንዳንዱ አንድ አንድ መታጠቢያ ሰን ይቀመጥ ነበር።'),
  ('c9c42976-5eda-5585-a4af-1be27352255a', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '3102df50-2a70-5fc0-a853-0cb97f751b32', 39, 39, 'አምስቱንም መቀመጫዎች በቤቱ ቀኝ፥ አምስቱንም በቤቱ ግራ አኖራቸው፤ ኩሬውንም በቤቱ ቀኝ በአዜብ ፊት ለፊት በስተምሥራቅ አኖረው።'),
  ('155f5194-054f-541f-af46-e123201b97da', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 1, 40, 'ኪራምም ምንቸቶችንና መጫሪያዎችን፥ ድስቶችንም ሠራ፤ ኪራምም ለንጉሡ ለሰሎሞን በእግዚአብሔር ቤት የሠራውን ሥራ ሁሉ ጨረሰ።'),
  ('3df0c22f-7dc5-56c1-a856-bd22736d9a80', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 2, 41, 'ሁለቱንም አዕማድ፥ በሁለቱም አዕማድ ራስ ላይ የነበሩትን ኩብ የሚመስሉትን ጕልላቶች፥ በሁለቱም አዕማድ ላይ የነበሩትን ሁለቱን ጕልላቶች የሚሸፍኑትን ሁለቱን መርበቦች፥'),
  ('2e789800-a8fc-5d1e-aa17-ce70d8c4be0d', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 3, 42, 'በሁለቱም አዕማድ ላይ የነበሩትን ሁለቱን ጕልላቶች ይሸፍኑ ዘንድ ለእያንዳንዱ መርበብ በሁለት በሁለት ተራ አድርጎ ለሁለቱ መርበቦች አራት መቶ ሮማኖችን አደረገ።'),
  ('20532295-4090-50af-ac61-0597e231a273', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 4, 43, 'ዐሥሩንም መቀመጫዎች፥ በመቀመጫዎቹም ላይ የሚቀመጡትን ዐሥሩን መታጠቢያ ሰን፥'),
  ('8b5e7c16-c2be-50fd-a2a7-d590bc245f56', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 5, 44, 'አንዱንም ኩሬ፥ ከኩሬውም በታች የሚሆኑትን ዐሥራ ሁለቱን በሬዎች፥'),
  ('1eb49c0e-5ea9-58df-a054-9995198ab6a7', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 6, 45, 'ምንቸቶቹንም፥ መጫሪያዎቹንም፥ ድስቶቹንም፥ ዕቃዎቹንም ሁሉ ኪራም ለንጉሡ ለሰሎሞን ለእግዚአብሔር ቤት ሠራ። በንጉሡ ቤትና በእግዚአብሔር ቤትም አርባ ስምንት አዕማድ ነበሩ። ኪራምም ለንጉሡ የሠራቸው ዕቃዎች ሁሉ ከጥሩ ናስ ነበር።'),
  ('e610f4ac-12a2-531b-a584-8898c450ef1f', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 7, 46, 'በዮርዳኖስም ሜዳ በሱኮትና በተርታን መካከል ባለው በወፍራሙ መሬት ውስጥ አስፈሰሰው።'),
  ('3f754cfa-f3a2-5a90-ae8b-b520443dcb84', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 8, 47, 'ይህ ሁሉ ሥራ ለተሠራበት ናስ ሚዛን አልነበረውም፤ የናሱም ሚዛን ብዙ ነበርና አይቈጠርም ነበር።'),
  ('72b78681-ee99-5aba-a811-ed5c883ee2fc', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 9, 48, 'ሰሎሞንም ለእግዚአብሔር ቤት ዕቃን ሁሉ አሠራ፤ የወርቁን መሠዊያ፥ የገጹም ኅብስት የነበረበትን የወርቅ ገበታ፥'),
  ('fc908685-cc3f-5e6e-a07e-9711f9d4439e', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 10, 49, 'በቅድስተ ቅዱሳኑ ፊት አምስቱ በቀኝ፥ አምስቱም በግራ የሚቀመጡትን ከጥሩ ወርቅ የተሠሩትንም መቅረዞች፥ የወርቁንም አበባዎችና ቀንዲሎች፥ መኮስተሪያዎችንም፥'),
  ('964dc9b5-3d6c-5c8c-ada9-62fffd454101', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 11, 50, 'ከጥሩ ወርቅም የተሠሩትን ጽዋዎችና ጕጠቶች፥ ድስቶቹንና ጭልፋዎቹንም፥ ማንደጃዎቹንም፥ ጽንሐሖችን፥ ለውስጠኛውም ቤት ለቅድስተ ቅዱሳን ደጆች፥ ለቤተ መቅደሱም ደጆች የሚሆኑትን የወርቅ ማጠፊያዎች አሠራ።'),
  ('ba168b4f-a296-5b98-abd0-e571bfca4b4a', '0899ffe6-2cad-5844-a93b-e7628b38e5da', '9faad1b8-af0e-5852-a3d1-9c3534e37d34', 12, 51, 'እንዲሁም ንጉሡ ሰሎሞን ለእግዚአብሔር ቤት የአሠራው ሥራ ሁሉ ተፈጸመ። አባቱም ዳዊት የቀደሰውን፥ ራሱም የቀደሰውን፥ የብርና የወርቅ ዕቃ ሰሎሞን በእግዚአብሔር ቤት ውስጥ በነበሩ ግምጃ ቤቶች አገባ።'),
  ('5341a6f8-be08-54ba-ac2f-49ba33f83820', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 1, 1, 'ሰሎሞንም የእግዚአብሔርን ቤትና የራሱን ቤተ መንግሥት ሠርቶ ከፈጸመ ከሃያ ዓመት በኋላ ያንጊዜ የእግዚአብሔርን ቃል ኪዳን ታቦት ከዳዊት ከተማ ከጽዮን ያወጡ ዘንድ የእስራኤልን ሽማግሌዎችና የነገድ አለቆችን ሁሉ፥ የእስራኤልን ልጆች የአባቶቻቸውን ቤቶች መሳፍንት ንጉሡ ሰሎሞን በጽዮን ሰበሰባቸው።'),
  ('15a2b696-e64f-5be7-a59e-efce9c162baa', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 2, 2, 'ይኸውም አታሚን በሚባል በሰባተኛው ወር ነበር።'),
  ('5d4b1e48-81d5-595b-a1c9-052b95c3e941', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 3, 3, 'ካህናቱም ታቦቷን አነሡ፤'),
  ('2ecb25be-adb6-5682-a350-070eb05de827', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 4, 4, 'የምስክሩንም ድንኳን፥ በድንኳኑም ውስጥ የነበረውን የተቀደሰውን ዕቃ ሁሉ አመጡ።'),
  ('71ec108c-501e-5b05-a70c-e9392e421089', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 5, 5, 'ንጉሡም ሰሎሞን ከእርሱ ጋር የተሰበሰቡ የእስራኤል ማኅበር ሁሉ ከእርሱ ጋር በታቦቷ ፊት ሆነው፥ ከብዛታቸው የተነሣ የማይቈጠሩትንና የማይመጠኑትን በጎችና በሬዎች ይሠዉ ነበር።'),
  ('98cadfa4-0af8-5e34-a27f-e2f39efb6719', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 6, 6, 'ካህናቱም የእግዚአብሔርን ቃል ኪዳን ታቦት በቤቱ በቅድስተ ቅዱሳን ውስጥ ከኪሩቤል ክንፍ በታች ወደ ነበረው ወደ ስፍራዋ አገቧት።'),
  ('183cbb72-e1d2-5bba-a602-ff0ae1793da4', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 7, 7, 'ኪሩቤልም በታቦቷ ስፍራ ላይ ክንፎቻቸውን ዘርግተው ነበር፤ ኪሩቤልም ታቦቷንና የተቀደሱ ዕቃዎችን በስተላይ በኩል ሸፍነው ነበር።'),
  ('4fe3b728-7047-5f63-a8d5-e724a003e902', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 8, 8, 'መሎጊያዎቹም ረጃጅሞች ነበሩ፤ በቅድስተ ቅዱሳኑ ፊት ከመቅደሱ ውስጥ ጫፎቻቸው ይታዩ ነበር፤ በውጭ ግን አይታዩም ነበር፤'),
  ('04503ffb-ba29-51e4-a878-c2e0fef3ada5', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 9, 9, 'በታቦቷም ውስጥ የእስራኤል ልጆች ከግብፅ ምድር በወጡ ጊዜ እግዚአብሔርም ከእነርሱ ጋር ቃል ኪዳን ባደረገ ጊዜ ሙሴ በኮሬብ ካስቀመጣቸው የቃል ኪዳን ጽላት ከሚባሉት ከሁለቱ የድንጋይ ጽላት በቀር ምንም አልነበረባትም።'),
  ('5aee310e-de5e-5cf5-ae20-7ce5113bc330', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 10, 10, 'ካህናቱም ከመቅደሱ በወጡ ጊዜ ደመናው የእግዚአብሔርን ቤት ሞላው።'),
  ('96a07426-2d26-5348-a81f-95d899846a59', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 11, 11, 'የእግዚአብሔርም ክብር ቤቱን ሞልቶት ነበርና ካህናቱ ከደመናው የተነሣ ለማገልገል ይቆሙ ዘንድ አልቻሉም።'),
  ('242b1afb-a490-5916-ab79-7f07a43c0a20', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 12, 12, 'ያንጊዜም ሰሎሞን እንዲህ አለ፥ “እግዚአብሔር፦ በደመናው ውስጥ እኖራለሁ ብሎአል፤'),
  ('c078e6e6-c430-519a-a8bb-324eb0c2316e', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '69a5faee-cae3-5aaf-a4d8-ed8dfaaa7501', 13, 13, 'እኔም ለዘለዓለም የምትኖርበትን ማደሪያ ቤት በእውነት ሠራሁልህ።”'),
  ('7c107203-c10d-5064-aa42-61d77a75a392', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9f640f88-f47f-55db-a51b-8f99cb7082b5', 1, 14, 'ንጉሡም ፊቱን ዘወር አድርጎ የእስራኤልን ጉባኤ ሁሉ መረቃቸው፤ የእስራኤልም ጉባኤ ሁሉ ቆመው ነበር።'),
  ('803178b6-0c74-54e8-aa98-6a758b17ad8e', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9f640f88-f47f-55db-a51b-8f99cb7082b5', 2, 15, 'እርሱም አለ፥ “ለአባቴ ለዳዊት በአፉ የተናገረ፥ በእጁም የፈጸመ የእስራኤል አምላክ እግዚአብሔር ይመስገን።'),
  ('229947ca-88e0-5863-a0c2-f8664446aafc', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9f640f88-f47f-55db-a51b-8f99cb7082b5', 3, 16, 'ሕዝቤን እስራኤልን ከግብፅ ካወጣሁበት ቀን ጀምሮ ስሜ በዚያ ይሆን ዘንድ በእርስዋም ቤት ይሠራልኝ ዘንድ፥ ከእስራኤል ነገድ ሁሉ ከተማን አልመረጥሁም፤ አሁን ግን ስሜ በዚያ ይሆን ዘንድ ኢየሩሳሌምን መርጫለሁ፤ በሕዝቤም በእስራኤል ላይ ንጉሥ ይሆን ዘንድ ዳዊትን መርጫለሁ።”'),
  ('1c1c86f1-1d0b-5730-a806-f883c7940410', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9f640f88-f47f-55db-a51b-8f99cb7082b5', 4, 17, 'አባቴም ዳዊት ለእስራኤል አምላክ ለእግዚአብሔር ስም ቤት ይሠራ ዘንድ በልቡ አሰበ።'),
  ('a7200b63-c0d5-57ff-a68e-a18ac85656c9', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9f640f88-f47f-55db-a51b-8f99cb7082b5', 5, 18, 'እግዚአብሔርም አባቴን ዳዊትን፥ “ለስሜ ቤት ትሠራ ዘንድ በልብህ አስበሃልና ይህን በልብህ ማሰብህ መልካም አደረግህ።'),
  ('3bbab5e8-230a-59a5-a6b4-d4832930ff06', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9f640f88-f47f-55db-a51b-8f99cb7082b5', 6, 19, 'ነገር ግን ከወገብህ የሚወጣው ልጅህ እርሱ ለስሜ ቤት ይሠራል እንጂ ቤት የምትሠራልኝ አንተ አይደለህም” አለው።'),
  ('e913d342-d103-5584-a8b5-bbb842681d19', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9f640f88-f47f-55db-a51b-8f99cb7082b5', 7, 20, 'እግዚአብሔርም የተናገረውን ቃል አጸና፤ እግዚአብሔርም ተስፋ እንደ ሰጠ በአባቴ በዳዊት ፋንታ ተነሣሁ፤ በእስራኤልም ዙፋን ላይ ተቀመጥሁ፤ ለእስራኤልም አምላክ ለእግዚአብሔር ስም ቤት ሠራሁ።'),
  ('7b8696a6-8657-5d61-a1af-a758fec03198', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9f640f88-f47f-55db-a51b-8f99cb7082b5', 8, 21, 'ከግብፅም ምድር ባወጣቸው ጊዜ ከአባቶቻችን ጋር ያደረገው የእግዚአብሔር ቃል ኪዳን ላለባት ታቦት ስፍራን በዚያ አደርግሁላት።'),
  ('dab5397d-27ae-5a83-a7f3-3d459c686e26', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 1, 22, 'የእስራኤልም ጉባኤ ሁሉ እያዩ ሰሎሞን በእግዚአብሔር መሠዊያ ፊት ቆሞ እጆቹን ወደ ሰማይ ዘረጋ።'),
  ('28c8beb4-d5aa-5da7-a495-21aaa6497798', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 2, 23, 'እንዲህም አለ፥ “የእስራኤል አምላክ አቤቱ! በላይ በሰማይ፥ በታችም በምድር አንተን የሚመስል አምላክ የለም፤ በፍጹም ልቡ በፊትህ ለሚሄድ ባሪያህ ቃል ኪዳንንና ምሕረትን የምትጠብቅ፥'),
  ('36d39b37-cb84-5f67-a9c0-468dab4a2804', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 3, 24, 'ለባሪያህ ለአባቴ ለዳዊት የሰጠኸውን ተስፋ የጠበቅህ፥ በአፍህ ተናግረህ፥ እንደ ዛሬ ቀንም በእጅህ ፈጸምኸው።'),
  ('45be2728-6a31-53df-a299-35b0950cf721', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 4, 25, 'አሁንም የእስራኤል አምላክ አቤቱ፦ አንተ በፊቴ እንደ ሄድህ ልጆችህ በፊቴ ይሄዱ ዘንድ መንገዳቸውን ቢጠብቁ፥ በፊቴ በእስራኤል ዙፋን የሚቀመጥ ሰው ከአንተ አይጠፋም ብለህ ለአባቴ ለዳዊት ተስፋ የሰጠኽውን ጠብቅ።'),
  ('fc6e9074-57e8-5bc7-afc3-d53d112054ac', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 5, 26, 'አሁንም የእስራኤል አምላክ ሆይ! ለባሪያህ ለአባቴ ለዳዊት የተናገርኸው ቃል እባክህ እውነት ይሁን።'),
  ('6104b4af-d882-5802-a489-16da7edc3c59', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 6, 27, '“በውኑ እግዚአብሔር ከሰው ጋር በምድር ላይ ይኖራልን? እነሆ ሰማይ ከሰማያትም በላይ ያለው ሰማይ ይይዝህ ዘንድ አይችልም፤ ይልቁንስ እኔ ለስምህ የሠራሁት ቤት እንዴት ያንስ!'),
  ('d7f131a5-c510-5e7a-acf9-351ec7dde35f', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 7, 28, 'አቤቱ አምላኬ ሆይ! ወደ ባሪያህ ጸሎትና ልመና ተመልከት፤ ዛሬም ባሪያህ በፊትህ የሚጸልየውን ጸሎት ስማ፤'),
  ('43d1ba93-569d-5a14-a54d-6dccf56998ed', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 8, 29, 'ባሪያህ ወደዚህ ስፍራ የሚጸልየውን ጸሎት ትሰማ ዘንድ፦ በዚያ ስሜ ይሆናል ወዳልኸው ስፍራ ወደዚህ ቤት ዐይኖችህ ሌሊትና ቀን የተገለጡ ይሁኑ።'),
  ('d1b02931-c55e-5d58-a556-25cabdaa59d0', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 9, 30, 'ባሪያህና ሕዝብህ እስራኤል ወደዚህ ስፍራ የሚጸልዩትን ልመና ስማ፤ በማደሪያህ በሰማይ ስማ፤ ሰምተህም ይቅር በል።'),
  ('da757d6c-a869-55eb-aa78-fb2fb90619d8', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 10, 31, '“ሰው ባልጀራውን ቢበድል፥ ይምልም ዘንድ በላዩ መሐላ ቢጫንበት፥ እርሱም መጥቶ በዚህ ቤት በመሠዊያህ ፊት ቢናዘዝ፥'),
  ('cfe6ba15-b56c-5c80-a647-6072f15dfa71', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 11, 32, 'በሰማይ ስማ፤ አድርግም፤ በባሪያዎችህም በእስራኤል ላይ ዳኛ ሁን፤ በበደለኛውም ላይ ፍረድ፤ መንገዱንም በራሱ ላይ መልስበት፤ ጻድቁን አጽድቀው፤ እንደ ጽድቁም ክፈለው።'),
  ('d495cf35-dede-568b-a405-18675406ab1a', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 12, 33, '“ሕዝብህ እስራኤል አንተን ስለ በደሉ በጠላቶቻቸው ፊት ድል ቢሆኑ፥ ወደ አንተም ቢመለሱ፥ ለስምህም ቢናዘዙ፥'),
  ('eb993329-5eab-5244-a4f3-401d95e39e87', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 13, 34, 'በዚህም ቤት ቢጸልዩና ቢለምኑህ፥ አንተ በሰማይ ስማ፤ የሕዝብህንም የእስራኤልን ኀጢአት ይቅር በል፤ ለአባቶቻቸውም ወደ ሰጠሃት ምድር መልሳቸው።'),
  ('07e7ed68-028f-54b6-ae60-7658d6950304', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 14, 35, '“አንተን ስለ በደሉ ሰማይ ቢዘጋ፥ ዝናብም ባይዘንብ፥ በዚህም ስፍራ ቢጸልዩ፥ ለስምህም ቢናዘዙ፥ ባስጨነቅሃቸውም ጊዜ ከኀጢአታቸው ቢመለሱ፥'),
  ('ce67e46e-8a90-543c-a58c-c13b9fb73875', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 15, 36, 'አንተ በሰማይ ስማ፤ የሚሄዱበትንም መልካም መንገድ በማሳየት የባሪያዎችህንና የሕዝብህን የእስራኤልን ኀጢአት ይቅር በል፤ ለሕዝብህም ርስት አድርገህ ለሰጠሃት ምድር ዝናብን ስጥ።'),
  ('2467ab19-1df0-5288-ad09-7cebe8ceee26', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 16, 37, '“በምድር ላይም ራብ፥ ወይም ቸነፈር፥ ወይም ዋግ፥ ወይም አረማሞ ቢሆን፥ አንበጣ፥ ወይም ኩብኩባ ቢመጣ፥ የሕዝብህም ጠላት ከከተሞቻቸው በአንዲቱ ከብቦ ቢያስጨንቃቸው፥ መቅሠፍትና ደዌ ሁሉ ቢሆን፥'),
  ('6d9409b9-cb1e-5a20-a301-ef58799c7d64', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 17, 38, 'ማናቸውም ሰው የልቡን ሕመም ዐውቆ ጸሎትና ምህላ ቢያደርግ፥ እጆቹንም ወደዚህ ቤት ቢዘረጋ፥'),
  ('9bd9bc47-22d8-5d92-abb4-758374c43bd1', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 18, 39, 'በማደሪያህ በሰማይ ስማ፤ ይቅርም በል፤ አንተ ብቻ የሰውን ልጆች ሁሉ ልብ ታውቃለህና ልቡን ለምታውቀው ሰው ሁሉ እንደ መንገዱ ሁሉ መጠን ክፈለውና ስጠው።'),
  ('a57a3446-4de1-54a0-a79f-6ded92b710ab', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 19, 40, 'ለአባቶቻችን በሰጠሃት ምድር ላይ በሚኖሩበት ዘመን ሁሉ ይፈሩህ ዘንድ።'),
  ('9a46a388-2a32-5a94-a70c-eaa509cbec7e', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 20, 41, '“ከሕዝብህም ከእስራኤል ወገን ያልሆነ እንግዳ ስለ ስምህ ከሩቅ ሀገር ቢመጣ፥'),
  ('27264c9e-2be7-558c-aade-b0ea13accff2', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 21, 42, 'ታላቁን ስምህን፥ ብርቱይቱንም እጅህን፥ የተዘረጋችውንም ክንድህን ሰምተው ቢመጡና በዚህ ቤት ቢጸልዩ፥'),
  ('1451af7e-8727-5bfa-a509-a074fa13cd52', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 22, 43, 'አንተ በማደሪያህ በሰማይ ስማ፤ የምድርም አሕዝብ ሁሉ ስምህን ያውቁ ዘንድ፥ እንደ ሕዝብህ እንደ እስራኤል ይፈሩህ ዘንድ፥ በዚህም በሠራሁት ቤት ስምህ እንደ ተጠራ ያውቁ ዘንድ፥ እንግዳው የሚለምንህን ሁሉ አድርግ።'),
  ('277d697b-31ef-5d98-a8dd-bd3b5291f583', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 23, 44, '“ሕዝብህም ጠላቶቻቸውን ለመውጋት አንተ በምትመልሳቸው መንገድ ቢወጡ፥ አንተም ወደ መረጥሃት ከተማ፥ እኔም ለስምህ ወደ ሠራሁት ቤት በእግዚአብሔር ስም ቢጸልዩ፥'),
  ('b864f1af-3d32-59e5-ad6e-717251eda707', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 24, 45, 'ጸሎታቸውንና ልመናቸውን በሰማይ ስማ፤ ፍርድንም አድርግላቸው።'),
  ('fb764fc9-6486-5932-a99e-004c5a4d3258', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 25, 46, '“የማይበድልም ሰው የለምና አንተን ቢበድሉ፥ ተቈጥተህም ለጠላቶቻቸው አሳልፈህ ብትሰጣቸው፥ ሩቅ ወይም ቅርብ ወደ ሆነ ወደ ጠላቶች ሀገር ቢማረኩም፥'),
  ('a7523069-6188-54d3-ad21-fee171e423ab', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 26, 47, 'በተማረኩበትም ሀገር ሆነው በልባቸው ንስሓ ቢገቡ፥ በተማረኩበትም ሀገር ሳሉ ተመልሰው፦ ኀጢአት ሠርተናል፥ በድለንማል፥ ክፉንም አድርገናል ብለው ቢለምኑህ፥'),
  ('17fabdec-5117-5f61-acad-11b192257100', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 27, 48, 'በማረኩአቸው በጠላቶቻቸው ሀገር ሳሉ በፍጹም ልባቸውና በፍጹም ነፍሳቸው ወደ አንተ ቢመለሱ፥ ለአባቶቻቸው ወደ ሰጠሃት ወደ ምድራቸው ወደ መረጥሃትም ከተማ ለስምህም ወደ ሠራሁት ቤት ቢጸልዩ፥'),
  ('4bd7e8db-16cd-572b-a46f-8f30d132f8ef', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 28, 49, 'ጸሎታቸውንና ልመናቸውን በማደሪያህ በሰማይ ስማ፤'),
  ('a6713de9-ce63-500f-a52c-3e5127a642f2', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 29, 50, 'አንተንም የበደሉህን ሕዝብህን ፥ በአንተም ላይ ያደረጉትን በደላቸውን ሁሉ ይቅር በል፤ ይራሩላቸውም ዘንድ በማረኩአቸው ፊት ምሕረትን ስጣቸው፤'),
  ('6cb6ea57-844b-5584-a968-4e465d3e8a49', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 30, 51, 'ከግብጽ ምድር ከብረት እቶን ውስጥ ያወጣሃቸው ሕዝብህና ርስትህ ናቸውና።'),
  ('d636701e-a020-5e9c-a518-b999d5327d6b', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 31, 52, 'በጠሩህ ጊዜ ሁሉ ትሰማቸው ዘንድ ለባሪያህና ለሕዝብህ ለእስራኤል ልመና ዐይኖችህ የተገለጡ፥ ጆሮዎችህ የተከፈቱ ይሁኑ።'),
  ('5d26bb1e-adb2-508d-acca-5ab9f612fe8b', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 32, 53, 'ጌታዬ እግዚአብሔር ሆይ! አባቶቻችንን ከግብፅ ባወጣህ ጊዜ በባሪያህ በሙሴ እጅ እንደ ተናገርህ ርስት ይሆኑህ ዘንድ ከምድር አሕዛብ ሁሉ ለይተሃቸዋልና።” ያንጊዜም ሰሎሞን ሥራውን በጨረሰ ጊዜ ስለዚያ ቤት እንዲህ ሲል ተናገረ። “እግዚአብሔር በሰማይ ፀሐይን አሳየ፤ እግዚአብሔር በጨለማ ውስጥ እንደሚኖር ተናገረ፤ ቤቴን ሥራ፤ በመታደስም ለመኖር ለራስህ ጥሩ ቤትን ሥራ፤” ይህችስ በመሐልይ መጽሐፍ የተጻፈች አይደለምን?'),
  ('b182b855-7051-5f5e-a58e-a1495ea08ad0', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 33, 54, 'ሰሎሞንም ይህችን ጸሎትና ልመና ሁሉ ለእግዚአብሔር ጸልዮ በፈጸመ ጊዜ፥ በጕልበቱ ተንበርክኮ፥ እጁንም ወደ ሰማይ ዘርግቶ ነበርና ከእግዚአብሔር መሠዊያ ፊት ከሰገደበት ተነሣ።'),
  ('eb2ab05c-c325-5e55-a556-797d8bb5d6ab', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 34, 55, 'ቆሞም የእስራኤልን ጉባኤ ሁሉ በታላቅ ድምፅ ሲመርቅ እንዲህ አለ፦'),
  ('65c4613a-3391-56e1-aa01-def73e346157', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 35, 56, '“እንደ ተናገረው ተስፋ ሁሉ ለሕዝቡ ለእስራኤል ዕረፍትን የሰጠ እግዚአብሔር ይመስገን፥ በባሪያው በሙሴ ቃል ከተናገረው ከመልካም ቃል ሁሉ ያጐደለው አንድም ቃል የለም።'),
  ('e07d10f9-e18b-5e1c-a67f-f4f1ffdcb653', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 36, 57, 'አምላካችን እግዚአብሔር ከአባቶቻችን ጋር እንደ ነበረ ከእኛም ጋር ይሁን፤ አይተወን፤ አይጣለንም፤'),
  ('be1baf1a-9d95-5aba-ac8b-4fa3aaa71c82', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 37, 58, 'በመንገዱም ሁሉ እንሄድ ዘንድ፥ ለአባቶቻችንም ያዘዛትን ትእዛዙንና ሥርዐቱን እንጠብቅ ዘንድ፥ ልባችንን ወደ እርሱ ይመልስ።'),
  ('fb330e82-3d5a-53dd-af1b-16461aeaed1b', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 38, 59, 'ለባሪያውና ለሕዝቡ እስራኤል በየዕለቱ ፍርድን ያደርግ ዘንድ ይህች በእግዚአብሔር ፊት የለመንኋት ቃል በቀንና በሌሊት ወደ አምላካችን ወደ እግዚአብሔር የቀረበች ትሁን፤'),
  ('d71a8a31-1eea-5574-abbf-52e8f7c09bd1', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 39, 60, 'የምድር አሕዛብ ሁሉ እግዚአብሔር እርሱ አምላክ እንደ ሆነ፥ ከእርሱም በቀር ሌላ እንደ ሌለ ያውቁ ዘንድ፥'),
  ('b39dc905-2110-5608-a247-76b2e55dcbcb', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '9c03bf75-ae0c-5f27-ad7a-9313ec5052a8', 40, 61, 'እንደ ዛሬው ቀን በሥርዐቱ እንሄድ ዘንድ፥ ትእዛዙንም እንጠብቅ ዘንድ፥ ከአምላካችን ከእግዚአብሔር ጋር ልባችን ፍጹም ይሁን።”'),
  ('95c7d1f7-fe94-51f5-a120-e26530309c65', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '29f00dff-7f36-504a-abc3-48cd1f784959', 1, 62, 'ንጉሡም ከእርሱም ጋር የእስራኤል ልጆች ሁሉ በእግዚአብሔር ፊት መሥዋዕት ሠዉ።'),
  ('e94cbc18-3920-517f-aaf4-d7f6ed00e286', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '29f00dff-7f36-504a-abc3-48cd1f784959', 2, 63, 'ንጉሡ ሰሎሞንም ለእግዚአብሔር ስለ ሰላም መሥዋዕት ሃያ ሁለት ሺህ በሬዎችንና መቶ ሃያ ሺህ በጎችን አቀረበ። ንጉሡና የእስራኤል ልጆች ሁሉ እንዲሁ የእግዚአብሔርን ቤት ቀደሱ፤ አከበሩም።'),
  ('a0176ef1-d39e-52ce-a265-04c29a8d63d2', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '29f00dff-7f36-504a-abc3-48cd1f784959', 3, 64, 'በእግዚአብሔር ፊት ያለው የናሱ መሠዊያ የሚቃጠለውን መሥዋዕትና የእህሉን ቍርባን የሰላሙንም መሥዋዕት ስብ ይይዝ ዘንድ ታናሽ ስለ ነበረ፥ በዚያ የሚቃጠለውን መሥዋዕትና የእህሉን ቍርባን፥ የሰላሙንም መሥዋዕት ስብ አሳርጎአልና በእግዚአብሔር ቤት ፊት የነበረውን የአደባባዩን መካከል ንጉሡ በዚያ ቀን ቀደሰ።'),
  ('270d24b1-69b1-5d55-a928-30535b655e7c', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '29f00dff-7f36-504a-abc3-48cd1f784959', 4, 65, 'በዚያም ዘመን ሰሎሞን፥ ከእርሱም ጋር እስራኤል ሁሉ ከኤማት መግቢያ ጀምሮ እስከ ግብፅ ወንዝ ድረስ ያለው ታላቅ ጉባኤ፥ እርሱ በሠራው ቤት ውስጥ በአምላካችን በእግዚአብሔር ፊት እየበሉና እየጠጡ፥ ደስታም እያደረጉ ሰባት ቀን በዓሉን አከበሩ።'),
  ('a3f16dc4-4802-5961-a6df-f6ff96a09c5d', '66a39cb5-5c46-599a-ac3d-9bb628fd619b', '29f00dff-7f36-504a-abc3-48cd1f784959', 5, 66, 'በስምንተኛውም ቀን ሕዝቡን አሰናበተ፤ እነርሱም ንጉሡን መረቁ፤ እግዚአብሔርም ለባሪያው ለዳዊትና ለሕዝቡ ለእስራኤል ስላደረገው ቸርነት ሁሉ በልባቸው ደስ ብሏቸው፥ ሐሴትም አድርገው ወደ እየቤታቸው ሄዱ።'),
  ('4b334387-5e0c-54a4-ab3e-3b16b453c02b', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 1, 1, 'ከዚህም በኋላ ሰሎሞን የእግዚአብሔርን ቤት፥ የንጉሡን ቤትና ሰሎሞን ያደርገው ዘንድ የወደደውን ሁሉ ሠርቶ በፈጸመ ጊዜ፥'),
  ('00b96fa8-f367-5471-a891-11bbd060639a', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 2, 2, 'እግዚአብሔር በገባዖን ለሰሎሞን እንደ ተገለጠለት ዳግመኛ ተገለጠለት።'),
  ('b8e79a2c-7b11-5ad8-a452-60c31bbfa357', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 3, 3, 'እግዚአብሔርም አለው፥ “በፊቴ የጸለይኸውን ጸሎትህንና ልመናህን ሰምቻለሁ፤ እንደ ጸሎትህም ሁሉ አደረግሁልህ፤ ለዘለዓለምም ስሜ በዚያ ያድር ዘንድ ይህን የሠራኸውን ቤት ቀድሻለሁ፤ ዐይኖችና ልቤም በዘመኑ ሁሉ በዚያ ይሆናሉ።'),
  ('65c73522-d1e0-5c39-aa5c-ba8f89545cc1', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 4, 4, 'ዳዊትም አባትህ በጽድቅ፥ በንጹሕ ልብና በቅንነት እንደ ሄደ አንተ ደግሞ በፊቴ ብትሄድ፥ ያዘዝሁህንም ሁሉ ብታደርግ፥ ሥርዐቴንም ሕጌንም ብትጠብቅ፥')
